def _assert_blocked_without_next_action_summary(payload: dict) -> None:
    expected_ids = [
        check["requirement_id"]
        for check in payload["checks"]
        if check["status"] == "fail" and not check["next_actions"]
    ]
    assert payload["blocked_without_next_action_ids"] == expected_ids
    assert payload["blocked_without_next_action_count"] == len(expected_ids)


def _assert_printed_unique_action_diagnostics(
    *,
    stdout: str,
    prefix: str,
    line_name: str,
    actions: list[dict],
) -> None:
    if not actions:
        return
    line = next(
        item
        for item in stdout.splitlines()
        if f"[{prefix}] {line_name}.1 " in item
    )
    action = actions[0]
    assert f"kind={action['kind']}" in line
    assert f"has_command_hint={action['has_command_hint']}" in line
    assert (
        f"has_unresolved_command_placeholder="
        f"{action['has_unresolved_command_placeholder']}"
    ) in line
    assert "blocker_reasons=" in line
    assert "blocked_by_requirement_ids=" in line
    assert "unresolved_command_placeholders=" in line
    assert "missing_metric_inputs=" in line
    assert f"human_review_open_task_id_count={len(action['human_review_open_task_ids'])}" in line
    assert "requires_human_review=" not in line


def _assert_printed_unique_action_limit(
    *,
    stdout: str,
    prefix: str,
    line_name: str,
    actions: list[dict],
    limit: int,
) -> None:
    printed_count = len(actions[:limit]) if limit > 0 else len(actions)
    omitted_count = max(0, len(actions) - printed_count)
    assert f"[{prefix}] {line_name}_total_count={len(actions)}" in stdout
    assert f"[{prefix}] {line_name}_printed_count={printed_count}" in stdout
    assert f"[{prefix}] {line_name}_omitted_count={omitted_count}" in stdout
    if len(actions) >= limit and limit > 0:
        assert f"[{prefix}] {line_name}.{limit} " in stdout
    if len(actions) > limit and limit > 0:
        assert f"[{prefix}] {line_name}.{limit + 1} " not in stdout


