def _stdout_test_count_mapping(mapping: dict[str, int]) -> str:
    return ",".join(f"{key}:{value}" for key, value in sorted(mapping.items())) or "-"


def _stdout_test_ids_by_kind_mapping(mapping: dict[str, list[str]]) -> str:
    return ";".join(
        f"{key}:{'|'.join(values) or '-'}"
        for key, values in sorted(mapping.items())
    ) or "-"


def _stdout_test_list_count_mapping(mapping: dict[str, list[str]]) -> str:
    return ",".join(f"{key}:{len(values)}" for key, values in sorted(mapping.items())) or "-"


def _stdout_test_nested_count_mapping(mapping: dict[str, dict[str, int]]) -> str:
    return ";".join(
        f"{key}:{'|'.join(f'{field}:{count}' for field, count in sorted(value.items())) or '-'}"
        for key, value in sorted(mapping.items())
    ) or "-"


def _stdout_test_nested_ids_mapping(mapping: dict[str, dict[str, list[str]]]) -> str:
    return ";".join(
        f"{key}:{'|'.join(f'{field}:{','.join(values) or '-'}' for field, values in sorted(value.items())) or '-'}"
        for key, value in sorted(mapping.items())
    ) or "-"


def _reviewer_value_hint_counts_by_requirement_for_test(
    *,
    missing_value_counts: dict[str, dict[str, int]],
    missing_suggestion_counts: dict[str, dict[str, int]],
) -> dict[str, dict[str, int]]:
    values: dict[str, dict[str, int]] = {}
    for requirement_id, counts_by_field in missing_value_counts.items():
        missing_suggestions = missing_suggestion_counts.get(requirement_id, {})
        for field_name, count in counts_by_field.items():
            hint_count = count - missing_suggestions.get(field_name, 0)
            if hint_count > 0:
                values.setdefault(requirement_id, {})[field_name] = hint_count
    return values


def _reviewer_value_hint_counts_by_field_for_test(
    *,
    missing_value_counts: dict[str, int],
    missing_suggestion_counts: dict[str, int],
) -> dict[str, int]:
    values: dict[str, int] = {}
    for field_name, count in missing_value_counts.items():
        hint_count = count - missing_suggestion_counts.get(field_name, 0)
        if hint_count > 0:
            values[field_name] = hint_count
    return values


