def _roadmap_frontier_ids_by_kind(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    ids_by_kind: dict[str, list[str]] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        command_hint = (action.command_hint or "").strip()
        if action.requires_human_review:
            kind = "human_review_with_command" if command_hint else "human_review_without_command"
        elif not command_hint:
            kind = "nonhuman_without_command"
        elif "<" in command_hint:
            kind = "placeholder_command"
        else:
            kind = "ready_to_run_command"
        ids_by_kind.setdefault(kind, []).append(requirement_id)
    return ids_by_kind


def _roadmap_next_action_ids_by_kind(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    ids_by_kind: dict[str, list[str]] = {}
    seen_requirement_ids_with_prior_action: set[str] = set()
    for action in actions:
        requirement_id = action.requirement_id.strip()
        command_hint = (action.command_hint or "").strip()
        action_text = action.action.strip()
        has_prior_prerequisite = requirement_id in seen_requirement_ids_with_prior_action
        if requirement_id and action_text:
            seen_requirement_ids_with_prior_action.add(requirement_id)
        if action.requires_human_review:
            kind = "human_review_with_command" if command_hint else "human_review_without_command"
        elif not command_hint:
            kind = "nonhuman_without_command"
        elif "<" in command_hint:
            kind = "placeholder_command"
        elif has_prior_prerequisite:
            kind = "prerequisite_gated_command"
        else:
            kind = "ready_to_run_command"
        ids_by_kind.setdefault(kind, []).append(requirement_id)
    return ids_by_kind


def _roadmap_next_action_counts_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        if not requirement_id:
            continue
        counts[requirement_id] = counts.get(requirement_id, 0) + 1
    return dict(sorted(counts.items()))


def _roadmap_next_action_texts_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    texts_by_requirement: dict[str, list[str]] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        action_text = action.action.strip()
        if not requirement_id or not action_text:
            continue
        texts_by_requirement.setdefault(requirement_id, []).append(action_text)
    return dict(sorted(texts_by_requirement.items()))


def _roadmap_next_action_command_hints_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    hints_by_requirement: dict[str, list[str]] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        command_hint = (action.command_hint or "").strip()
        if not requirement_id or not command_hint:
            continue
        hints_by_requirement.setdefault(requirement_id, []).append(command_hint)
    return dict(sorted(hints_by_requirement.items()))


def _roadmap_next_action_unresolved_placeholders_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    values_by_requirement: dict[str, list[str]] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        command_hint = (action.command_hint or "").strip()
        placeholders = [
            part
            for part in command_hint.split()
            if part.startswith("<") and part.endswith(">")
        ]
        if requirement_id and placeholders:
            values_by_requirement.setdefault(requirement_id, []).extend(placeholders)
    return dict(sorted(values_by_requirement.items()))


def _roadmap_next_action_unresolved_placeholder_counts_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    return {
        requirement_id: len(placeholders)
        for requirement_id, placeholders in _roadmap_next_action_unresolved_placeholders_by_requirement(
            actions
        ).items()
    }


def _roadmap_next_action_unresolved_placeholder_counts_by_placeholder(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for placeholders in _roadmap_next_action_unresolved_placeholders_by_requirement(
        actions
    ).values():
        for placeholder in placeholders:
            counts[placeholder] = counts.get(placeholder, 0) + 1
    return dict(sorted(counts.items()))


def _roadmap_next_action_kind_counts_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, dict[str, int]]:
    counts_by_requirement: dict[str, dict[str, int]] = {}
    for kind, requirement_ids in _roadmap_next_action_ids_by_kind(actions).items():
        for requirement_id in requirement_ids:
            requirement_id = requirement_id.strip()
            if not requirement_id:
                continue
            counts = counts_by_requirement.setdefault(requirement_id, {})
            counts[kind] = counts.get(kind, 0) + 1
    return {
        requirement_id: dict(sorted(counts.items()))
        for requirement_id, counts in sorted(counts_by_requirement.items())
    }


def _roadmap_next_action_ids_by_phase(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    ids_by_phase: dict[str, list[str]] = {}
    for action in actions:
        requirement_id = action.requirement_id.strip()
        if not requirement_id:
            continue
        phase = (action.phase or "unknown").strip() or "unknown"
        ids_by_phase.setdefault(phase, []).append(requirement_id)
    return dict(sorted(ids_by_phase.items()))


def _roadmap_next_action_kind_counts(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    return {
        kind: len(ids)
        for kind, ids in _roadmap_next_action_ids_by_kind(actions).items()
    }


def _roadmap_next_action_blocked_by_requirement_ids_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    values_by_requirement: dict[str, list[str]] = {}
    for action in actions:
        values = [
            item.strip()
            for item in action.blocked_by_requirement_ids
            if item.strip()
        ]
        if action.requirement_id and values:
            values_by_requirement.setdefault(action.requirement_id, []).extend(values)
    return dict(sorted(values_by_requirement.items()))


def _roadmap_next_action_blocked_by_requirement_counts(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for blocked_ids in _roadmap_next_action_blocked_by_requirement_ids_by_requirement(
        actions
    ).values():
        for requirement_id in blocked_ids:
            counts[requirement_id] = counts.get(requirement_id, 0) + 1
    return dict(sorted(counts.items()))


def _roadmap_next_action_blocked_by_requirement_unique_ids_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, list[str]]:
    unique_by_requirement: dict[str, list[str]] = {}
    for requirement_id, blocked_ids in (
        _roadmap_next_action_blocked_by_requirement_ids_by_requirement(actions).items()
    ):
        seen: set[str] = set()
        values: list[str] = []
        for blocked_id in blocked_ids:
            if blocked_id in seen:
                continue
            seen.add(blocked_id)
            values.append(blocked_id)
        if values:
            unique_by_requirement[requirement_id] = values
    return dict(sorted(unique_by_requirement.items()))


def _roadmap_next_action_blocked_by_requirement_unique_counts(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for blocked_ids in (
        _roadmap_next_action_blocked_by_requirement_unique_ids_by_requirement(
            actions
        ).values()
    ):
        for requirement_id in blocked_ids:
            counts[requirement_id] = counts.get(requirement_id, 0) + 1
    return dict(sorted(counts.items()))


def _roadmap_next_action_blocker_reasons_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
    *,
    missing_metric_inputs_by_requirement: dict[str, list[str]] | None = None,
    human_review_open_task_ids_by_requirement: dict[str, list[str]] | None = None,
) -> dict[str, list[str]]:
    missing_metric_inputs_by_requirement = missing_metric_inputs_by_requirement or {}
    human_review_open_task_ids_by_requirement = (
        human_review_open_task_ids_by_requirement or {}
    )
    values_by_requirement: dict[str, list[str]] = {}
    seen_requirement_ids_with_prior_action: set[str] = set()
    for action in actions:
        requirement_id = action.requirement_id.strip()
        if not requirement_id:
            continue
        command_hint = (action.command_hint or "").strip()
        action_text = action.action.strip()
        has_prior_prerequisite = requirement_id in seen_requirement_ids_with_prior_action
        if action_text:
            seen_requirement_ids_with_prior_action.add(requirement_id)
        if action.requires_human_review:
            kind = "human_review_with_command" if command_hint else "human_review_without_command"
        elif not command_hint:
            kind = "nonhuman_without_command"
        elif "<" in command_hint:
            kind = "placeholder_command"
        elif has_prior_prerequisite:
            kind = "prerequisite_gated_command"
        else:
            kind = "ready_to_run_command"
        reasons: list[str] = []
        if action.blocked_by_requirement_ids:
            reasons.append("blocked_by_requirement")
        if has_prior_prerequisite:
            reasons.append("prerequisite_gated")
        if action.requires_human_review:
            reasons.append("human_review_required")
        if human_review_open_task_ids_by_requirement.get(requirement_id):
            reasons.append("human_review_open_tasks")
        if missing_metric_inputs_by_requirement.get(requirement_id):
            reasons.append("missing_metric_inputs")
        if "<" in command_hint:
            reasons.append("unresolved_command_placeholders")
        if kind == "nonhuman_without_command" or (
            not command_hint and not action.requires_human_review
        ):
            reasons.append("missing_command_hint")
        if reasons:
            values_by_requirement.setdefault(requirement_id, []).extend(reasons)
    return dict(sorted(values_by_requirement.items()))


def _roadmap_next_action_blocker_reason_counts(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
    *,
    missing_metric_inputs_by_requirement: dict[str, list[str]] | None = None,
    human_review_open_task_ids_by_requirement: dict[str, list[str]] | None = None,
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for reasons in _roadmap_next_action_blocker_reasons_by_requirement(
        actions,
        missing_metric_inputs_by_requirement=missing_metric_inputs_by_requirement,
        human_review_open_task_ids_by_requirement=human_review_open_task_ids_by_requirement,
    ).values():
        for reason in reasons:
            counts[reason] = counts.get(reason, 0) + 1
    return dict(sorted(counts.items()))


def _roadmap_next_action_blocker_reason_counts_by_requirement(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
    *,
    missing_metric_inputs_by_requirement: dict[str, list[str]] | None = None,
    human_review_open_task_ids_by_requirement: dict[str, list[str]] | None = None,
) -> dict[str, dict[str, int]]:
    counts_by_requirement: dict[str, dict[str, int]] = {}
    for requirement_id, reasons in _roadmap_next_action_blocker_reasons_by_requirement(
        actions,
        missing_metric_inputs_by_requirement=missing_metric_inputs_by_requirement,
        human_review_open_task_ids_by_requirement=human_review_open_task_ids_by_requirement,
    ).items():
        requirement_counts: dict[str, int] = {}
        for reason in reasons:
            requirement_counts[reason] = requirement_counts.get(reason, 0) + 1
        if requirement_counts:
            counts_by_requirement[requirement_id] = dict(
                sorted(requirement_counts.items())
            )
    return dict(sorted(counts_by_requirement.items()))


def _roadmap_next_action_blocker_reason_counts_by_phase(
    actions: list[EvidenceGroundingRoadmapCompletionNextAction],
    *,
    missing_metric_inputs_by_requirement: dict[str, list[str]] | None = None,
    human_review_open_task_ids_by_requirement: dict[str, list[str]] | None = None,
) -> dict[str, dict[str, int]]:
    counts_by_phase: dict[str, dict[str, int]] = {}
    seen_requirement_ids_with_prior_action: set[str] = set()
    missing_metric_inputs_by_requirement = missing_metric_inputs_by_requirement or {}
    human_review_open_task_ids_by_requirement = (
        human_review_open_task_ids_by_requirement or {}
    )
    for action in actions:
        requirement_id = action.requirement_id.strip()
        if not requirement_id:
            continue
        command_hint = (action.command_hint or "").strip()
        action_text = action.action.strip()
        phase = (action.phase or "unknown").strip() or "unknown"
        has_prior_prerequisite = requirement_id in seen_requirement_ids_with_prior_action
        if action_text:
            seen_requirement_ids_with_prior_action.add(requirement_id)
        if action.requires_human_review:
            kind = "human_review_with_command" if command_hint else "human_review_without_command"
        elif not command_hint:
            kind = "nonhuman_without_command"
        elif "<" in command_hint:
            kind = "placeholder_command"
        elif has_prior_prerequisite:
            kind = "prerequisite_gated_command"
        else:
            kind = "ready_to_run_command"
        reasons: list[str] = []
        if action.blocked_by_requirement_ids:
            reasons.append("blocked_by_requirement")
        if has_prior_prerequisite:
            reasons.append("prerequisite_gated")
        if action.requires_human_review:
            reasons.append("human_review_required")
        if human_review_open_task_ids_by_requirement.get(requirement_id):
            reasons.append("human_review_open_tasks")
        if missing_metric_inputs_by_requirement.get(requirement_id):
            reasons.append("missing_metric_inputs")
        if "<" in command_hint:
            reasons.append("unresolved_command_placeholders")
        if kind == "nonhuman_without_command" or (
            not command_hint and not action.requires_human_review
        ):
            reasons.append("missing_command_hint")
        for reason in reasons:
            phase_counts = counts_by_phase.setdefault(phase, {})
            phase_counts[reason] = phase_counts.get(reason, 0) + 1
    return {
        phase: dict(sorted(counts.items()))
        for phase, counts in sorted(counts_by_phase.items())
    }


