def _roadmap_frontier_blocked_by_requirement_unique_ids_by_requirement(
    summaries: list[EvidenceGroundingRoadmapCompletionFrontierSummary],
) -> dict[str, list[str]]:
    unique_by_requirement: dict[str, list[str]] = {}
    for requirement_id, blocked_ids in (
        _roadmap_frontier_blocked_by_requirement_ids_by_requirement(
            summaries
        ).items()
    ):
        seen: set[str] = set()
        values: list[str] = []
        for blocked_id in blocked_ids:
            if blocked_id in seen:
                continue
            seen.add(blocked_id)
            values.append(blocked_id)
        if values:
            unique_by_requirement[requirement_id] = values
    return dict(sorted(unique_by_requirement.items()))


