def _roadmap_frontier_suggested_value_counts_by_requirement(
    summaries: list[EvidenceGroundingRoadmapCompletionFrontierSummary],
) -> dict[str, dict[str, int]]:
    values_by_requirement: dict[str, dict[str, int]] = {}
    for summary in summaries:
        requirement_id = summary.requirement_id.strip()
        if not requirement_id:
            continue
        fields = set(summary.human_review_open_csv_missing_value_counts_by_field) | set(
            summary.human_review_open_csv_missing_suggestion_counts_by_field
        )
        counts: dict[str, int] = {}
        for field_name in sorted(fields):
            count = (
                summary.human_review_open_csv_missing_value_counts_by_field.get(
                    field_name,
                    0,
                )
                - summary.human_review_open_csv_missing_suggestion_counts_by_field.get(
                    field_name,
                    0,
                )
            )
            if count > 0:
                counts[field_name] = count
        if counts:
            values_by_requirement[requirement_id] = counts
    return dict(sorted(values_by_requirement.items()))


