def _ready_gold_payload(paper_id: str) -> dict:
    evidence = {
        "page": 1,
        "quote": "Evidence sentence.",
        "section": "Results",
        "figure_id": "fig1",
    }
    return {
        "schema_version": "paper_understanding_gold.v1",
        "paper_id": paper_id,
        "citation": {
            "doi": f"10.1000/{paper_id}",
            "title": f"Gold {paper_id}",
        },
        "paper_type": "primary_research",
        "domain_tags": ["benchmark"],
        "important_figures": [{"figure_id": "fig1", "label": "Figure 1", "page": 1}],
        "gold_claims": [
            {
                "statement_id": f"claim-{index}",
                "kind": "claim",
                "text": f"Grounded claim {index}.",
                "evidence_refs": [evidence],
            }
            for index in range(1, 4)
        ],
        "gold_methods": [
            {
                "statement_id": "method-1",
                "kind": "method",
                "text": "A method was used.",
                "evidence_refs": [{**evidence, "section": "Methods"}],
            }
        ],
        "gold_results": [
            {
                "statement_id": "result-1",
                "kind": "result",
                "text": "A result was observed.",
                "evidence_refs": [evidence],
            }
        ],
        "gold_limitations": [
            {
                "statement_id": "limitation-1",
                "kind": "limitation",
                "text": "A limitation was reported.",
                "evidence_refs": [{**evidence, "section": "Discussion"}],
            }
        ],
    }


def _write_staged_gold_manifest(tmp_path: Path, *, paper_id: str = "paper-1") -> Path:
    stage_dir = tmp_path / "goldset" / "reviews" / "paper_understanding_gold_staged"
    stage_dir.mkdir(parents=True)
    gold_path = stage_dir / f"{paper_id}.json"
    gold_path.write_text(json.dumps(_ready_gold_payload(paper_id)), encoding="utf-8")
    staging_manifest_path = stage_dir / "staging_manifest.json"
    staging_manifest_path.write_text(
        json.dumps(
            {
                "schema_version": "paper_understanding_gold_staging_manifest.v1",
                "layer": "review_gate_artifact",
                "canonical_status": "non_canonical",
                "generated_at": datetime.now(timezone.utc).isoformat(),
                "source_draft_paths": [f"drafts/{paper_id}.candidate_draft.json"],
                "out_dir": str(stage_dir),
                "require_ready": True,
                "staged_count": 1,
                "staged_paths": [str(gold_path)],
                "readiness_summary": {"pass_count": 1, "warn_count": 0, "fail_count": 0},
            }
        ),
        encoding="utf-8",
    )
    return staging_manifest_path


def test_run_evidence_grounding_benchmark_from_manifest_path(tmp_path):
    _write_run_dir(
        tmp_path / "runs" / "paper-1" / "baseline",
        run_id="baseline",
        grounded_ratio=0.6,
        page_coverage_ratio=0.5,
        unsupported_claim_count=1,
        unresolved_span_count=1,
    )
    _write_run_dir(
        tmp_path / "runs" / "paper-1" / "candidate",
        run_id="candidate",
        grounded_ratio=0.8,
        page_coverage_ratio=0.7,
        unsupported_claim_count=0,
        unresolved_span_count=0,
    )
    manifest_path = tmp_path / "manifest.json"
    manifest_path.write_text(
        json.dumps(
            {
                "schema_version": "evidence_grounding_benchmark_manifest.v1",
                "benchmark_id": "bench-1",
                "goldset_id": "paper-understanding-seed",
                "goldset_split": "eval",
                "goldset_manifest_path": "goldset/manifest.json",
                "items": [
                    {"candidate_id": "baseline", "run_dir": "runs/paper-1/baseline"},
                    {
                        "candidate_id": "candidate",
                        "run_dir": "runs/paper-1/candidate",
                        "candidate_config": {
                            "parser_version": "parser-v2",
                            "llm_provider": "local",
                            "llm_model": "reader-model",
                            "llm_model_version": "reader-model-2026-05-22",
                            "prompt_version": "grounding-prompt-v2",
                            "reader_profile_version": "reader-profile-v2",
                        },
                    },
                ],
            }
        ),
        encoding="utf-8",
    )
    out = tmp_path / "benchmark.json"

    report = run_evidence_grounding_benchmark_from_manifest_path(manifest_path, out=out)

    assert out.exists()
    assert report.schema_version == "evidence_grounding_benchmark.v1"
    assert report.canonical_status == "non_canonical"
    assert report.goldset_id == "paper-understanding-seed"
    assert report.goldset_split == "eval"
    assert report.goldset_manifest_path == "goldset/manifest.json"
    assert report.item_count == 2
    assert report.candidate_configs[0].parser_version == "parser-v2"
    assert report.scorecards[1].candidate_config.llm_model_version == "reader-model-2026-05-22"
    assert report.scorecards[1].scorecard.candidate_config is not None
    assert report.scorecards[1].scorecard.candidate_config.prompt_version == "grounding-prompt-v2"
    assert report.aggregate_runtime_proxy_metrics["input_artifact_coverage_rate"].value == 1.0
    assert report.aggregate_runtime_proxy_metrics["missing_input_artifact_count"].value == 0.0
    assert report.aggregate_runtime_proxy_metrics["malformed_input_artifact_count"].value == 0.0
    assert report.aggregate_runtime_proxy_metrics["grounded_evidence_ratio"].value == 0.7
    assert report.aggregate_runtime_proxy_metrics["unsupported_claim_rate_proxy"].value == 0.125
    assert report.aggregate_runtime_proxy_metrics["visual_evidence_claim_link_rate"].value == 1.0
    assert report.aggregate_runtime_proxy_metrics["caption_only_figure_count"].value == 1.0
    assert report.aggregate_runtime_proxy_metrics["figure_table_conflict_count"].value == 0.0
    assert report.aggregate_runtime_proxy_metrics["downstream_traceability_rate"].value == 0.8
    assert report.aggregate_runtime_proxy_metrics["handoff_review_ready"].value == 1.0
    assert report.aggregate_runtime_proxy_metrics["review_burden_per_paper"].status == "not_available"
    assert report.aggregate_gold_scored_metrics["claim_precision"].status == "not_available"
    assert report.aggregate_failure_counts_by_code["UNSUPPORTED_CLAIM"] == 1
    assert report.aggregate_failure_counts_by_code["MISSING_CLAIM"] == 2
    assert report.aggregate_failure_counts_by_code["FIGURE_CAPTION_MISLINKED"] == 2
    stage_counts = {summary.stage: summary.failure_count for summary in report.aggregate_stage_failure_summary}
    assert stage_counts["extractor"] == 2
    assert stage_counts["grounding_checker"] == 5
    stage_metrics = {summary.stage: summary for summary in report.aggregate_stage_metric_summary}
    assert stage_metrics["unknown"].runtime_proxy_metrics["input_artifact_coverage_rate"].value == 1.0
    assert stage_metrics["unknown"].runtime_proxy_metrics["malformed_input_artifact_count"].value == 0.0
    assert stage_metrics["extractor"].runtime_proxy_metrics["claim_count"].value == 4.0
    assert stage_metrics["extractor"].runtime_proxy_metrics["missing_topic_signal_count"].value == 1.0
    assert stage_metrics["grounding_checker"].runtime_proxy_metrics["grounded_evidence_ratio"].value == 0.7
    assert stage_metrics["grounding_checker"].runtime_proxy_metrics["unsupported_claim_rate_proxy"].value == 0.125
    assert stage_metrics["parser"].runtime_proxy_metrics["caption_only_figure_count"].value == 1.0
    assert stage_metrics["formatter"].runtime_proxy_metrics["downstream_traceability_rate"].value == 0.8
    payload = json.loads(out.read_text(encoding="utf-8"))
    assert payload["scorecards"][1]["scorecard"]["candidate_config"]["reader_profile_version"] == "reader-profile-v2"


def test_run_evidence_grounding_benchmark_surfaces_failed_scorecard_readiness(tmp_path):
    run_dir = tmp_path / "runs" / "paper-1" / "candidate"
    _write_run_dir(
        run_dir,
        run_id="candidate",
        grounded_ratio=1.0,
        page_coverage_ratio=1.0,
        unsupported_claim_count=0,
        unresolved_span_count=0,
    )
    coverage_payload = json.loads((run_dir / "claimset_coverage.json").read_text(encoding="utf-8"))
    coverage_payload["paper_id"] = "paper-2"
    (run_dir / "claimset_coverage.json").write_text(json.dumps(coverage_payload), encoding="utf-8")
    manifest = EvidenceGroundingBenchmarkManifest(
        benchmark_id="bench-scorecard-fail",
        items=[
            EvidenceGroundingBenchmarkManifestItem(
                candidate_id="candidate",
                run_dir=str(run_dir),
            )
        ],
    )

    report = run_evidence_grounding_benchmark(manifest)

    assert report.scorecard_readiness_pass_count == 0
    assert report.scorecard_readiness_warn_count == 0
    assert report.scorecard_readiness_fail_count == 1
    assert report.scorecard_not_ready_candidate_ids == ["candidate"]
    assert any(
        warning == "scorecard_readiness_failures_present: count=1 candidate_ids=candidate"
        for warning in report.warnings
    )
    assert report.scorecards[0].scorecard.readiness_status == "fail"
    assert "input_paper_id_mismatch" in report.scorecards[0].scorecard.reason_codes


def test_run_evidence_grounding_benchmark_api(tmp_path):
    _write_run_dir(
        tmp_path / "runs" / "paper-1" / "candidate",
        run_id="candidate",
        grounded_ratio=0.8,
        page_coverage_ratio=0.7,
        unsupported_claim_count=0,
        unresolved_span_count=0,
    )
    manifest_path = tmp_path / "manifest.json"
    manifest_path.write_text(
        json.dumps(
            {
                "schema_version": "evidence_grounding_benchmark_manifest.v1",
                "benchmark_id": "bench-api",
                "goldset_id": "paper-understanding-seed",
                "goldset_split": "eval",
                "items": [
                    {
                        "candidate_id": "candidate",
                        "run_dir": "runs/paper-1/candidate",
                        "candidate_config": {
                            "parser_version": "parser-api-v2",
                            "llm_provider": "local",
                            "llm_model": "reader-model",
                            "llm_model_version": "reader-model-api-2026-05-22",
                            "prompt_version": "grounding-prompt-api-v2",
                            "reader_profile_version": "reader-profile-api-v2",
                        },
                    },
                ],
            }
        ),
        encoding="utf-8",
    )
    out = tmp_path / "benchmark_report.json"
    client = TestClient(api_main.app)

    response = client.post(
        "/evidence-grounding/benchmarks/run",
        json={
            "manifest_path": str(manifest_path),
            "out": str(out),
        },
    )

    assert response.status_code == 200
    payload = response.json()
    assert payload["schema_version"] == "evidence_grounding_benchmark.v1"
    assert payload["canonical_status"] == "non_canonical"
    assert payload["benchmark_id"] == "bench-api"
    assert payload["item_count"] == 1
    assert payload["candidate_configs"][0]["parser_version"] == "parser-api-v2"
    assert payload["scorecards"][0]["run_dir"] == ".../candidate"
    assert str(tmp_path) not in payload["scorecards"][0]["run_dir"]
    written = json.loads(out.read_text(encoding="utf-8"))
    assert written["scorecards"][0]["candidate_config"]["llm_model_version"] == "reader-model-api-2026-05-22"
    assert written["scorecards"][0]["run_dir"] == str(tmp_path / "runs" / "paper-1" / "candidate")


def test_evidence_grounding_benchmark_api_masks_local_path_errors(tmp_path, caplog):
    missing_manifest = tmp_path / "missing_manifest.json"
    client = TestClient(api_main.app)

    caplog.set_level(logging.ERROR, logger="paperpipe.backend")
    response = client.post(
        "/evidence-grounding/benchmarks/run",
        json={
            "manifest_path": str(missing_manifest),
            "out": str(tmp_path / "benchmark_report.json"),
        },
    )

    assert response.status_code == 500
    detail = response.json()["detail"]
    assert ".../missing_manifest.json" in detail
    assert str(tmp_path) not in detail
    log_text = "\n".join(record.getMessage() for record in caplog.records)
    assert ".../missing_manifest.json" in log_text
    assert str(tmp_path) not in log_text


def test_build_evidence_grounding_benchmark_manifest_from_goldset(tmp_path):
    gold_dir = tmp_path / "goldset" / "gold"
    manifest_dir = tmp_path / "goldset" / "manifests"
    run_root = tmp_path / "runs"
    out = tmp_path / "benchmarks" / "manifest.json"
    gold_dir.mkdir(parents=True)
    manifest_dir.mkdir(parents=True)
    (gold_dir / "paper-1.json").write_text(json.dumps(_ready_gold_payload("paper-1")), encoding="utf-8")
