    assert manifest.items[0].paper_id == "paper-1"
    assert manifest.items[0].run_dir == "../runs/paper-1"
    assert manifest.items[0].candidate_config.parser_version == "parser-v1"
    assert manifest.items[0].candidate_config.llm_model_version == "reader-model-2026-05-22"
    assert manifest.items[0].metadata["gold_readiness_status"] == "pass"


