def test_build_evidence_grounding_benchmark_manifest_package_accepts_explicit_run_dir_map(tmp_path):
    paths = _write_roadmap_completion_package_inputs(tmp_path)
    run_root = tmp_path / "unused_release_runs"
    out_dir = tmp_path / "release_benchmark_manifests"
    package_out = tmp_path / "release_benchmark_manifest_package.json"
    mapped_root = tmp_path / "mapped_runs"
    run_map = tmp_path / "run_dir_map.json"
    for split in ("seed", "eval", "holdout"):
        (mapped_root / f"{split}-run").mkdir(parents=True)
    run_map.write_text(
        json.dumps(
            {
                "paper-seed": "mapped_runs/seed-run",
                "paper-eval": "mapped_runs/eval-run",
                "paper-holdout": "mapped_runs/holdout-run",
            }
        ),
        encoding="utf-8",
    )

    package = build_evidence_grounding_benchmark_manifest_package_from_release_package(
        release_package_path=paths["gold_release_package"],
        run_root=run_root,
        out_dir=out_dir,
        package_id="release-benchmark-manifests",
        benchmark_id_prefix="release-benchmark",
        run_dir_map_path=run_map,
        out=package_out,
    )

    assert package.manifest_count == 3
    assert package.item_count == 3
    mapped_run_dirs = {
        Path(item.run_dir).name
        for manifest in package.benchmark_manifests
        for item in manifest.items
    }
    assert mapped_run_dirs == {"seed-run", "eval-run", "holdout-run"}
    assert all("unused_release_runs" not in item.run_dir for manifest in package.benchmark_manifests for item in manifest.items)
    written = json.loads(package_out.read_text(encoding="utf-8"))
    assert "mapped_runs" in json.dumps(written["benchmark_manifests"])


