def test_build_evidence_grounding_candidate_lineage_patch_template_from_manifest_package(tmp_path):
    paths = _write_roadmap_completion_package_inputs(tmp_path)
    run_root = tmp_path / "release_runs"
    out_dir = tmp_path / "release_benchmark_manifests"
    package_out = tmp_path / "release_benchmark_manifest_package.json"
    template_out = tmp_path / "candidate_lineage_patch_template.json"
    for split in ("seed", "eval", "holdout"):
        run_dir = run_root / f"paper-{split}"
        run_dir.mkdir(parents=True)
    prompts_snapshot = run_root / "paper-seed" / "profiles.yaml"
    prompts_snapshot.write_text("reader: test\n", encoding="utf-8")
    (run_root / "paper-seed" / "run_meta.json").write_text(
        json.dumps(
            {
                "prompts_snapshot": str(prompts_snapshot),
                "inference_lanes": {
                    "reader": {
                        "selected_backend": "local",
                        "provider_name": "ollama",
                        "provider_model": "llama3:latest",
                    }
                },
                "persona_id": "default",
            }
        ),
        encoding="utf-8",
    )
    build_evidence_grounding_benchmark_manifest_package_from_release_package(
        release_package_path=paths["gold_release_package"],
        run_root=run_root,
        out_dir=out_dir,
        benchmark_id_prefix="release-benchmark-lineage-template",
        candidate_config=EvidenceGroundingCandidateConfig(parser_version="parser-release-v1"),
        out=package_out,
    )

    template = build_evidence_grounding_candidate_lineage_patch_template_from_manifest_package(
        benchmark_manifest_package_path=package_out,
        out=template_out,
    )

    assert template.schema_version == "evidence_grounding_candidate_lineage_patch_template.v1"
    assert template.canonical_status == "non_canonical"
    assert template.target_count == 3
    assert template.records[0].patch_fields == {
        "llm_provider": "",
        "llm_model": "",
        "llm_model_version": "",
        "prompt_version": "",
        "reader_profile_version": "",
    }
    seed_record = next(record for record in template.records if record.paper_id == "paper-seed")
    assert seed_record.source_candidate_config == {"parser_version": "parser-release-v1"}
    assert seed_record.available_replay_context["candidate_config.parser_version"] == "parser-release-v1"
    assert seed_record.available_replay_context["run_meta.inference_lanes.reader.provider_model"] == (
        "llama3:latest"
    )
    prompt_ref = seed_record.available_replay_context["run_meta.prompts_snapshot_ref"]
    assert prompt_ref.startswith("profiles.yaml@sha256:")
    assert seed_record.suggested_lineage_values == {
        "llm_provider": "ollama",
        "llm_model": "llama3:latest",
        "prompt_version": prompt_ref,
    }
    assert json.loads(template_out.read_text(encoding="utf-8"))["target_count"] == 3


