    build_evidence_grounding_benchmark_manifest_package_from_release_package(
        release_package_path=paths["gold_release_package"],
        run_root=run_root,
        out_dir=out_dir,
        benchmark_id_prefix="release-benchmark-lineage-apply",
        candidate_config=EvidenceGroundingCandidateConfig(parser_version="parser-release-v1"),
        out=package_out,
    )
    build_evidence_grounding_candidate_lineage_patch_template_from_manifest_package(
        benchmark_manifest_package_path=package_out,
        out=template_out,
    )
    payload = json.loads(template_out.read_text(encoding="utf-8"))
    for record in payload["records"]:
        record["patch_fields"] |= {
            "llm_provider": "local",
            "llm_model": "llama3",
            "llm_model_version": "llama3:latest",
            "prompt_version": "grounding-prompt-v1",
            "reader_profile_version": "default-reader-profile-v1",
        }
    template_out.write_text(json.dumps(payload), encoding="utf-8")

    repaired_package = build_evidence_grounding_benchmark_manifest_package_from_candidate_lineage_patch_template(
        patch_template_path=template_out,
        out_dir=repaired_out_dir,
        out=repaired_package_out,
    )

    assert repaired_package.schema_version == "evidence_grounding_benchmark_manifest_package.v1"
    assert repaired_package.canonical_status == "non_canonical"
    assert repaired_package.manifest_count == 3
    assert repaired_package.item_count == 3
    for manifest in repaired_package.benchmark_manifests:
        for item in manifest.items:
            assert item.candidate_config is not None
            assert item.candidate_config.has_complete_replay_lineage()
            assert item.candidate_config.parser_version == "parser-release-v1"
            assert item.candidate_config.llm_provider == "local"
    assert repaired_package_out.exists()
    source_payload = json.loads(package_out.read_text(encoding="utf-8"))
    source_config = source_payload["benchmark_manifests"][0]["items"][0]["candidate_config"]
    assert source_config["parser_version"] == "parser-release-v1"
    assert source_config["llm_provider"] is None
    assert source_config["reader_profile_version"] is None


