def test_fill_task_review_evidence_hints_are_opt_in_evidence(
    tmp_path,
):
    template_path = tmp_path / "candidate_lineage_patch_template.json"
    readiness_path = tmp_path / "candidate_lineage_patch_template_fill_readiness.json"
    task_export_path = tmp_path / "candidate_lineage_patch_template_fill_tasks.json"
    reviewed_csv_path = tmp_path / "candidate_lineage_patch_template_fill_tasks_reviewed.csv"
    filled_out = tmp_path / "candidate_lineage_patch_template_filled.json"
    status_out = tmp_path / "candidate_lineage_patch_template_fill_review_status.json"
    cli_filled_out = tmp_path / "candidate_lineage_patch_template_filled_cli.json"
    fallback_reviewed_csv_path = (
        tmp_path / "candidate_lineage_patch_template_fill_tasks_reviewed_without_hint.csv"
    )
    fallback_filled_out = tmp_path / "candidate_lineage_patch_template_filled_from_context_hint.json"
    template_path.write_text(json.dumps(_candidate_lineage_patch_template_payload()), encoding="utf-8")
    build_evidence_grounding_patch_template_fill_readiness_report(
        patch_template_path=template_path,
        out=readiness_path,
    )
    build_evidence_grounding_patch_template_fill_task_export(
        fill_readiness_path=readiness_path,
        out=task_export_path,
    )
    _write_reviewed_fill_task_csv(
        task_export_path=task_export_path,
        out=reviewed_csv_path,
        values_by_field={
            "llm_provider": "provider-reviewed",
            "llm_model": "model-reviewed",
            "llm_model_version": "model-version-reviewed",
            "prompt_version": "prompt-reviewed",
            "reader_profile_version": "profile-reviewed",
        },
        include_evidence=False,
        include_evidence_hint=True,
    )

    with pytest.raises(ValueError, match="fill_task_review_evidence_missing"):
        build_evidence_grounding_patch_template_from_fill_task_reviews(
            task_export_path=task_export_path,
            reviewed_csv_path=reviewed_csv_path,
        )

    status = build_evidence_grounding_patch_template_fill_review_status_report(
        task_export_path=task_export_path,
        reviewed_csv_path=reviewed_csv_path,
        out=status_out,
        use_review_evidence_hints=True,
    )
    filled = build_evidence_grounding_patch_template_from_fill_task_reviews(
        task_export_path=task_export_path,
        reviewed_csv_path=reviewed_csv_path,
        out=filled_out,
        use_review_evidence_hints=True,
    )

    assert status.ready_for_apply is True
    assert status.missing_evidence_count == 0
    assert all(item.has_reviewer_evidence for item in status.items)
    assert filled.records[0].patch_fields["llm_provider"] == "provider-reviewed"
    assert filled.records[0].review_required is False

    _write_reviewed_fill_task_csv(
        task_export_path=task_export_path,
        out=fallback_reviewed_csv_path,
        values_by_field={
            "llm_provider": "provider-reviewed",
            "llm_model": "model-reviewed",
            "llm_model_version": "model-version-reviewed",
            "prompt_version": "prompt-reviewed",
            "reader_profile_version": "profile-reviewed",
        },
        include_evidence=False,
        include_evidence_hint=False,
    )
    with pytest.raises(ValueError, match="fill_task_review_evidence_missing"):
        build_evidence_grounding_patch_template_from_fill_task_reviews(
            task_export_path=task_export_path,
            reviewed_csv_path=fallback_reviewed_csv_path,
        )
    fallback_status = build_evidence_grounding_patch_template_fill_review_status_report(
        task_export_path=task_export_path,
        reviewed_csv_path=fallback_reviewed_csv_path,
        use_review_evidence_hints=True,
    )
    fallback_filled = build_evidence_grounding_patch_template_from_fill_task_reviews(
        task_export_path=task_export_path,
        reviewed_csv_path=fallback_reviewed_csv_path,
        out=fallback_filled_out,
        use_review_evidence_hints=True,
    )

    assert fallback_status.ready_for_apply is True
    assert fallback_status.missing_evidence_count == 0
    assert all(item.has_reviewer_evidence for item in fallback_status.items)
    assert fallback_filled.records[0].patch_fields["llm_provider"] == "provider-reviewed"

    result = subprocess.run(
        [
            sys.executable,
            "scripts/eval/apply_evidence_grounding_patch_template_fill_task_reviews.py",
            "--task-export",
            str(task_export_path),
            "--reviewed-csv",
            str(reviewed_csv_path),
            "--out",
            str(cli_filled_out),
            "--use-reviewer-evidence-hints",
        ],
        cwd=Path(__file__).resolve().parents[1],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr
    assert "remaining_blank_field_count=0" in result.stdout


