def test_build_evidence_grounding_patch_template_fill_review_status_report(tmp_path):
    template_path = tmp_path / "claim_evidence_correction_repair_patch_template.json"
    readiness_path = tmp_path / "claim_evidence_correction_repair_patch_template_fill_readiness.json"
    task_export_path = tmp_path / "claim_evidence_correction_repair_patch_template_fill_tasks.json"
    reviewed_csv_path = tmp_path / "claim_evidence_correction_repair_patch_template_fill_tasks_reviewed.csv"
    annotated_csv_path = (
        tmp_path / "claim_evidence_correction_repair_patch_template_fill_tasks_annotated.csv"
    )
    open_csv_path = tmp_path / "claim_evidence_correction_repair_patch_template_fill_tasks_open.csv"
    open_record_csv_path = (
        tmp_path / "claim_evidence_correction_repair_patch_template_fill_tasks_open_records.csv"
    )
    out = tmp_path / "claim_evidence_correction_repair_patch_template_fill_review_status.json"
    template_path.write_text(
        json.dumps(_claim_evidence_correction_repair_patch_template_payload()),
        encoding="utf-8",
    )
    build_evidence_grounding_patch_template_fill_readiness_report(
        patch_template_path=template_path,
        out=readiness_path,
    )
    build_evidence_grounding_patch_template_fill_task_export(
        fill_readiness_path=readiness_path,
        out=task_export_path,
    )
    _write_reviewed_fill_task_csv(
        task_export_path=task_export_path,
        out=reviewed_csv_path,
        values_by_field={"parser_version": "parser-reviewed", "llm_provider": "provider-reviewed"},
        missing_evidence_fields={"llm_provider"},
    )

    report = build_evidence_grounding_patch_template_fill_review_status_report(
        task_export_path=task_export_path,
        reviewed_csv_path=reviewed_csv_path,
        annotated_csv_path=annotated_csv_path,
        open_csv_path=open_csv_path,
        open_record_csv_path=open_record_csv_path,
        out=out,
    )

    assert report.schema_version == "evidence_grounding_patch_template_fill_review_status.v1"
    assert report.task_count == 6
    assert report.reviewed_value_count == 2
    assert report.missing_value_count == 4
    assert report.missing_evidence_count == 1
    assert report.pass_count == 1
    assert report.fail_count == 5
    assert report.open_csv_row_count == 5
    assert report.missing_value_count_by_field == {
        field: sum(1 for item in report.items if item.field_name == field and not item.has_reviewer_value)
        for field in sorted({item.field_name for item in report.items if not item.has_reviewer_value})
    }
    assert report.missing_evidence_count_by_field == {"llm_provider": 1}
    assert report.suggested_value_count_by_field == {
        field: sum(1 for item in report.items if item.field_name == field and item.suggested_value)
        for field in sorted({item.field_name for item in report.items if item.suggested_value})
    }
    assert report.missing_suggestion_count_by_field == {
        field: sum(1 for item in report.items if item.field_name == field and not item.suggested_value)
        for field in sorted({item.field_name for item in report.items if not item.suggested_value})
    }
    assert report.missing_suggestion_task_ids_by_field == {
        field: sorted(
            item.task_id
            for item in report.items
            if item.field_name == field and not item.suggested_value
        )
        for field in sorted({item.field_name for item in report.items if not item.suggested_value})
    }
    assert report.available_context_count_by_field == {
        field: sum(1 for item in report.items if item.field_name == field and item.available_context_values)
        for field in sorted({item.field_name for item in report.items if item.available_context_values})
    }
    assert report.missing_context_count_by_field == {
        field: sum(1 for item in report.items if item.field_name == field and not item.available_context_values)
        for field in sorted({item.field_name for item in report.items if not item.available_context_values})
    }
    assert report.missing_context_task_ids_by_field == {
        field: sorted(
            item.task_id
            for item in report.items
            if item.field_name == field and not item.available_context_values
        )
        for field in sorted({item.field_name for item in report.items if not item.available_context_values})
    }
    assert report.available_context_keys_by_field == {
        field: sorted(
            {
                key
                for item in report.items
                if item.field_name == field
                for key in item.available_context_values
            }
        )
        for field in sorted({item.field_name for item in report.items if item.available_context_values})
    }
    assert report.available_context_values_by_field == {
        field: sorted(
            {
                f"{key}={value}"
                for item in report.items
                if item.field_name == field
                for key, value in item.available_context_values.items()
            }
        )
        for field in sorted({item.field_name for item in report.items if item.available_context_values})
    }
    assert report.fail_count_by_field == {
        field: sum(1 for item in report.items if item.field_name == field and item.status == "fail")
        for field in sorted({item.field_name for item in report.items if item.status == "fail"})
    }
    assert report.open_task_ids == [
        item.task_id for item in report.items if item.status == "fail"
    ]
    assert report.open_task_ids_by_field == {
        field: sorted(
            item.task_id
            for item in report.items
            if item.field_name == field and item.status == "fail"
        )
        for field in sorted({item.field_name for item in report.items if item.status == "fail"})
    }
    assert report.open_record_count == len(
        {item.record_ref for item in report.items if item.status == "fail"}
    )
    assert report.open_record_refs == sorted(
        {item.record_ref for item in report.items if item.status == "fail"}
    )
    assert report.open_field_names_by_record_ref == {
        record_ref: sorted(
            {
                item.field_name
                for item in report.items
                if item.record_ref == record_ref and item.status == "fail"
            }
        )
        for record_ref in sorted(
            {item.record_ref for item in report.items if item.status == "fail"}
        )
    }
    assert report.open_task_ids_by_record_ref == {
        record_ref: sorted(
            item.task_id
            for item in report.items
            if item.record_ref == record_ref and item.status == "fail"
        )
        for record_ref in sorted(
            {item.record_ref for item in report.items if item.status == "fail"}
        )
    }
    expected_open_record_filled_patch_fields_by_record_ref = {
        record_ref: sorted(
            {
                field_name
                for item in report.items
                if item.record_ref == record_ref and item.status == "fail"
                for field_name in item.filled_patch_fields
            }
        )
        for record_ref in sorted(
            {
                item.record_ref
                for item in report.items
                if item.status == "fail" and item.filled_patch_fields
            }
        )
    }
    expected_open_record_filled_patch_field_counts_by_field: dict[str, int] = {}
    for field_names in expected_open_record_filled_patch_fields_by_record_ref.values():
        for field_name in field_names:
            expected_open_record_filled_patch_field_counts_by_field[field_name] = (
                expected_open_record_filled_patch_field_counts_by_field.get(field_name, 0) + 1
            )
    assert (
        report.open_record_filled_patch_fields_by_record_ref
        == expected_open_record_filled_patch_fields_by_record_ref
    )
    assert report.open_record_filled_patch_field_counts_by_field == dict(
        sorted(expected_open_record_filled_patch_field_counts_by_field.items())
    )
    assert report.ready_for_apply is False
    item_by_field = {item.field_name: item for item in report.items}
    task_payload = json.loads(task_export_path.read_text(encoding="utf-8"))
    task_by_field = {task["field_name"]: task for task in task_payload["tasks"]}
    assert item_by_field["parser_version"].status == "pass"
    assert item_by_field["parser_version"].available_context_values == task_by_field[
        "parser_version"
    ]["available_context_values"]
    assert item_by_field["parser_version"].filled_patch_fields == task_by_field[
        "parser_version"
    ]["filled_patch_fields"]
    assert item_by_field["llm_provider"].findings == ["fill_task_review_evidence_missing"]
    assert "patch_template_fill_review_status_not_ready" in report.warnings
    payload = json.loads(out.read_text(encoding="utf-8"))
    assert payload["ready_for_apply"] is False
    assert payload["annotated_csv_path"] == str(annotated_csv_path.resolve())
    assert payload["open_csv_path"] == str(open_csv_path.resolve())
    assert payload["open_record_csv_path"] == str(open_record_csv_path.resolve())
    assert payload["open_csv_row_count"] == 5
    assert payload["missing_evidence_count_by_field"] == {"llm_provider": 1}
    assert payload["suggested_value_count_by_field"] == report.suggested_value_count_by_field
    assert payload["missing_suggestion_count_by_field"] == report.missing_suggestion_count_by_field
    assert payload["missing_suggestion_task_ids_by_field"] == report.missing_suggestion_task_ids_by_field
    assert payload["available_context_count_by_field"] == report.available_context_count_by_field
    assert payload["available_context_keys_by_field"] == report.available_context_keys_by_field
    assert payload["available_context_values_by_field"] == report.available_context_values_by_field
    assert payload["open_task_ids"] == report.open_task_ids
    assert payload["open_task_ids_by_field"] == report.open_task_ids_by_field
    assert payload["open_record_count"] == report.open_record_count
    assert payload["open_record_refs"] == report.open_record_refs
    assert payload["open_field_names_by_record_ref"] == report.open_field_names_by_record_ref
    assert payload["open_task_ids_by_record_ref"] == report.open_task_ids_by_record_ref
    assert (
        payload["open_record_filled_patch_field_counts_by_field"]
        == report.open_record_filled_patch_field_counts_by_field
    )
    assert (
        payload["open_record_filled_patch_fields_by_record_ref"]
        == report.open_record_filled_patch_fields_by_record_ref
    )
    assert payload["missing_context_count_by_field"] == report.missing_context_count_by_field
    assert payload["missing_context_task_ids_by_field"] == report.missing_context_task_ids_by_field


def test_build_evidence_grounding_patch_template_fill_review_status_uses_reviewed_csv_hints(
    tmp_path,
):
    template_path = tmp_path / "candidate_lineage_patch_template.json"
    readiness_path = tmp_path / "candidate_lineage_patch_template_fill_readiness.json"
    task_export_path = tmp_path / "candidate_lineage_patch_template_fill_tasks.json"
    reviewed_csv_path = tmp_path / "candidate_lineage_patch_template_fill_tasks_reviewed.csv"
    template_path.write_text(json.dumps(_candidate_lineage_patch_template_payload()), encoding="utf-8")
    build_evidence_grounding_patch_template_fill_readiness_report(
        patch_template_path=template_path,
        out=readiness_path,
    )
    build_evidence_grounding_patch_template_fill_task_export(
        fill_readiness_path=readiness_path,
        out=task_export_path,
        csv_out=reviewed_csv_path,
    )

    with reviewed_csv_path.open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        fieldnames = list(reader.fieldnames or [])
        rows = list(reader)
    for row in rows:
        if row["field_name"] == "prompt_version":
            row["suggested_value"] = "prompt-v2"
            row["available_context_keys"] = "run_meta.prompts_snapshot_ref"
            row["available_context_values"] = "run_meta.prompts_snapshot_ref=prompt-v2"
            row["reviewer_value_hint"] = "prompt-v2"
            row["reviewer_evidence_hint"] = "run_meta.prompts_snapshot_ref=prompt-v2"
    with reviewed_csv_path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)

    report = build_evidence_grounding_patch_template_fill_review_status_report(
        task_export_path=task_export_path,
        reviewed_csv_path=reviewed_csv_path,
        use_review_evidence_hints=True,
    )

    item_by_field = {item.field_name: item for item in report.items}
    assert item_by_field["prompt_version"].suggested_value == "prompt-v2"
    assert item_by_field["prompt_version"].available_context_values == {
        "run_meta.prompts_snapshot_ref": "prompt-v2"
    }
    assert report.suggested_value_count_by_field["prompt_version"] == 1
    assert "prompt_version" not in report.missing_suggestion_count_by_field
    assert report.available_context_values_by_field["prompt_version"] == [
        "run_meta.prompts_snapshot_ref=prompt-v2"
    ]


