def test_audit_evidence_grounding_patch_template_fill_task_reviews_cli_restores_open_csv_context(
    tmp_path,
):
    template_path = tmp_path / "candidate_lineage_patch_template.json"
    readiness_path = tmp_path / "candidate_lineage_patch_template_fill_readiness.json"
    task_export_path = tmp_path / "candidate_lineage_patch_template_fill_tasks.json"
    reviewed_csv_path = tmp_path / "candidate_lineage_patch_template_fill_tasks_reviewed.csv"
    out = tmp_path / "candidate_lineage_patch_template_fill_review_status.json"
    open_csv_out = tmp_path / "candidate_lineage_patch_template_fill_tasks_reviewed_open.csv"
    template_path.write_text(json.dumps(_candidate_lineage_patch_template_payload()), encoding="utf-8")
    build_evidence_grounding_patch_template_fill_readiness_report(
        patch_template_path=template_path,
        out=readiness_path,
    )
    build_evidence_grounding_patch_template_fill_task_export(
        fill_readiness_path=readiness_path,
        out=task_export_path,
    )
    _write_reviewed_fill_task_csv(
        task_export_path=task_export_path,
        out=reviewed_csv_path,
        values_by_field={
            "llm_provider": "provider-reviewed",
            "llm_model_version": "model-version-reviewed",
            "prompt_version": "prompt-reviewed",
            "reader_profile_version": "profile-reviewed",
        },
    )
    with reviewed_csv_path.open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        fieldnames = list(reader.fieldnames or [])
        rows = list(reader)
    for row in rows:
        if row["field_name"] == "llm_model":
            row["suggested_value"] = ""
            row["available_context_keys"] = ""
            row["available_context_values"] = ""
            row["reviewer_value_hint"] = ""
            row["reviewer_evidence_hint"] = ""
    with reviewed_csv_path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)

    result = subprocess.run(
        [
            sys.executable,
            "scripts/eval/audit_evidence_grounding_patch_template_fill_task_reviews.py",
            "--task-export",
            str(task_export_path),
            "--reviewed-csv",
            str(reviewed_csv_path),
            "--out",
            str(out),
            "--open-csv-out",
            str(open_csv_out),
        ],
        cwd=Path(__file__).resolve().parents[1],
        capture_output=True,
        text=True,
        check=False,
    )

    assert result.returncode == 1
    with open_csv_out.open(newline="", encoding="utf-8") as handle:
        open_rows = list(csv.DictReader(handle))
    assert [row["field_name"] for row in open_rows] == ["llm_model"]
    row = open_rows[0]
    assert row["reviewer_value"] == ""
    assert row["suggested_value"] == "llama3:latest"
    assert row["available_context_keys"] == "run_meta.inference_lanes.reader.provider_model"
    assert (
        row["available_context_values"]
        == "run_meta.inference_lanes.reader.provider_model=llama3:latest"
    )
    assert (
        row["reviewer_evidence_hint"]
        == "run_meta.inference_lanes.reader.provider_model=llama3:latest"
    )


