def test_release_comparison_package_run_readiness_uses_manifest_run_dirs_from_map(tmp_path):
    paths = _write_roadmap_completion_package_inputs(tmp_path)
    package_paths: dict[str, Path] = {}
    mapped_roots = {"baseline": tmp_path / "baseline_mapped_runs", "candidate": tmp_path / "candidate_mapped_runs"}
    for lane, ratio, unsupported in (
        ("baseline", 0.7, 1),
        ("candidate", 0.8, 0),
    ):
        run_map_payload: dict[str, str] = {}
        for split in ("seed", "eval", "holdout"):
            run_dir = mapped_roots[lane] / f"{split}-custom-run"
            _write_run_dir(
                run_dir,
                run_id=f"{lane}-{split}",
                paper_id=f"paper-{split}",
                grounded_ratio=ratio,
                page_coverage_ratio=0.7,
                unsupported_claim_count=unsupported,
                unresolved_span_count=unsupported,
            )
            _write_matching_claimset_for_ready_gold(run_dir)
            run_map_payload[f"paper-{split}"] = str(run_dir)
        run_map = tmp_path / f"{lane}_run_dir_map.json"
        run_map.write_text(json.dumps(run_map_payload), encoding="utf-8")
        manifest_package_out = tmp_path / f"{lane}_manifest_package.json"
        build_evidence_grounding_benchmark_manifest_package_from_release_package(
            release_package_path=paths["gold_release_package"],
            run_root=tmp_path / f"{lane}_unused_run_root",
            out_dir=tmp_path / f"{lane}_manifests",
            package_id=f"{lane}-release-benchmark-manifests",
            benchmark_id_prefix=f"{lane}-release-benchmark",
            run_dir_map_path=run_map,
            out=manifest_package_out,
        )
        run_package_out = tmp_path / f"{lane}_run_package.json"
        run_evidence_grounding_benchmark_package_from_manifest_package(
            benchmark_manifest_package_path=manifest_package_out,
            out_dir=tmp_path / f"{lane}_reports",
            package_id=f"{lane}-release-benchmark-run-package",
            out=run_package_out,
        )
        package_paths[lane] = run_package_out

    comparison_package = run_evidence_grounding_fixed_goldset_comparison_suite_package_from_benchmark_run_packages(
        baseline_run_package_path=package_paths["baseline"],
        candidate_run_package_path=package_paths["candidate"],
        out_dir=tmp_path / "comparison_suites",
        package_id="release-comparison-suite-package",
        suite_id_prefix="release-comparison",
        out=tmp_path / "comparison_suite_package.json",
    )

    assert comparison_package.suite_count == 3
    for raw_path in comparison_package.run_readiness_report_paths:
        readiness = json.loads(Path(raw_path).read_text(encoding="utf-8"))
        for summary in readiness["lane_summaries"]:
            assert summary["missing_run_count"] == 0
            assert summary["missing_required_artifact_count"] == 0
            assert all("unused_run_root" not in item["run_dir"] for item in summary["items"])
            assert all("custom-run" in item["run_dir"] for item in summary["items"])


