    assert payload["manifest_count"] == 3
    assert payload["item_count"] == 3
    assert all(str(tmp_path) not in path for path in payload["benchmark_manifest_paths"])
    written = json.loads(repaired_package_out.read_text(encoding="utf-8"))
    assert any(str(tmp_path) in path for path in written["benchmark_manifest_paths"])
    assert (
        written["benchmark_manifests"][0]["items"][0]["candidate_config"]["reader_profile_version"]
        == "default-reader-profile-v1"
    )


