def test_threshold_package_contract_readiness_skips_incompatible_additional_review_artifacts(tmp_path):
    threshold_package = _write_ready_threshold_adoption_package(tmp_path)
    compatibility_out = tmp_path / "threshold_package_contract_compatibility_filtered.json"
    readiness_out = tmp_path / "threshold_package_contract_readiness_filtered.json"
    out = tmp_path / "threshold_package_roadmap_completion_filtered.json"
    review_docs = _write_contract_review_docs(tmp_path)
    scorecard_backfill = _write_scorecard_input_backfill_report(tmp_path)
    fill_review_artifacts = _write_roadmap_fill_review_status_artifacts(
        tmp_path / "in_progress_fill_review_artifacts"
    )
    stale_fill_readiness = next(
        path for path in fill_review_artifacts if path.name.endswith("_fill_readiness.json")
    )
    stale_payload = json.loads(stale_fill_readiness.read_text(encoding="utf-8"))
    stale_payload["warnings"] = ["human_review_still_open"]
    stale_fill_readiness.write_text(json.dumps(stale_payload), encoding="utf-8")

    report = build_evidence_grounding_roadmap_completion_audit_report_from_threshold_adoption_package(
        threshold_adoption_package_path=threshold_package,
        contract_compatibility_report_out=compatibility_out,
        contract_readiness_report_out=readiness_out,
        out=out,
        representative_split="eval",
        migration_plan_path=review_docs["migration"],
        backfill_plan_path=review_docs["backfill"],
        public_contract_doc_path=review_docs["public_contract"],
        contract_reviewer_approval_reference="contract-review-approval-123",
        allow_external_contract_ready=True,
        additional_artifact_paths=[scorecard_backfill, stale_fill_readiness],
        gold_release_package_path=tmp_path / "gold_release_package.json",
        correction_log_path=tmp_path / "claim_evidence_corrections.jsonl",
    )

    compatibility_payload = json.loads(compatibility_out.read_text(encoding="utf-8"))
    compatibility_paths = {item["path"] for item in compatibility_payload["items"]}
    contract_check = next(
        check for check in report.checks if check.requirement_id == "external_contract_readiness_reviewed"
    )

    assert report.additional_artifact_paths == [
        str(scorecard_backfill.resolve()),
        str(stale_fill_readiness.resolve()),
    ]
    assert compatibility_payload["fail_count"] == 0
    assert str(scorecard_backfill.resolve()) in compatibility_paths
    assert str(stale_fill_readiness.resolve()) not in compatibility_paths
    assert "contract_compatibility_fail_count=0" in contract_check.evidence


def test_threshold_package_contract_readiness_includes_workspace_scorecard_backfill(tmp_path):
    threshold_package = _write_ready_threshold_adoption_package(tmp_path)
    compatibility_out = tmp_path / "threshold_package_contract_compatibility_workspace_backfill.json"
    readiness_out = tmp_path / "threshold_package_contract_readiness_workspace_backfill.json"
    out = tmp_path / "threshold_package_roadmap_completion_workspace_backfill.json"
    review_docs = _write_contract_review_docs(tmp_path)
    run_root = tmp_path / "storage"
    run_root.mkdir()
    workspace_scorecard = run_root / "evidence_grounding_scorecard.json"
    workspace_scorecard.write_text(json.dumps(_scorecard_payload()), encoding="utf-8")
    workspace_backfill = run_root / "scorecard_input_backfill.json"
    workspace_backfill.write_text(json.dumps(_scorecard_input_backfill_payload()), encoding="utf-8")

    report = build_evidence_grounding_roadmap_completion_audit_report_from_threshold_adoption_package(
        threshold_adoption_package_path=threshold_package,
        contract_compatibility_report_out=compatibility_out,
        contract_readiness_report_out=readiness_out,
        out=out,
        representative_split="eval",
        migration_plan_path=review_docs["migration"],
        backfill_plan_path=review_docs["backfill"],
        public_contract_doc_path=review_docs["public_contract"],
        contract_reviewer_approval_reference="contract-review-approval-123",
        allow_external_contract_ready=True,
        gold_release_package_path=tmp_path / "gold_release_package.json",
        correction_log_path=tmp_path / "claim_evidence_corrections.jsonl",
        run_root=run_root,
        required_ready_run_count=0,
    )

    compatibility_payload = json.loads(compatibility_out.read_text(encoding="utf-8"))
    compatibility_paths = {item["path"] for item in compatibility_payload["items"]}
    contract_check = next(
        check for check in report.checks if check.requirement_id == "external_contract_readiness_reviewed"
    )
    missing_schemas = next(
        evidence for evidence in contract_check.evidence if evidence.startswith("missing_contract_schema_versions=")
    )
    missing_paths = next(
        evidence
        for evidence in contract_check.evidence
        if evidence.startswith("missing_contract_compatibility_artifact_paths=")
    )

    assert report.input_paths["scorecard_input_backfill_path"] == str(workspace_backfill.resolve())
    assert report.input_paths["scorecard_path"] == str(workspace_scorecard.resolve())
    assert compatibility_payload["fail_count"] == 0
    assert str(workspace_backfill.resolve()) in compatibility_paths
    assert str(workspace_scorecard.resolve()) in compatibility_paths
    assert "evidence_grounding_scorecard_input_backfill.v1" not in missing_schemas
    assert str(workspace_backfill.resolve()) not in missing_paths
    assert str(workspace_scorecard.resolve()) not in missing_paths


