    assert "--require-replayable" in export_candidates_action.command_hint

    repair_patch_template = tmp_path / "claim_evidence_correction_repair_patch_template.json"
    repair_patch_template_payload = _claim_evidence_correction_repair_patch_template_payload()
    repair_patch_template_payload["source_repair_plan_path"] = str(repair_plan)
