def test_build_evidence_grounding_roadmap_completion_from_threshold_adoption_package_requires_all_splits(tmp_path):
    threshold_package = _write_ready_threshold_adoption_package(tmp_path)
    package_payload = json.loads(threshold_package.read_text(encoding="utf-8"))
    comparison_suite_package_path = Path(package_payload["comparison_suite_package_path"])
    suite_payload = json.loads(comparison_suite_package_path.read_text(encoding="utf-8"))
    suite_payload["comparison_suite_paths"] = suite_payload["comparison_suite_paths"][:2]
    suite_payload["comparison_suites"] = suite_payload["comparison_suites"][:2]
    suite_payload["suite_count"] = 2
    comparison_suite_package_path.write_text(json.dumps(suite_payload), encoding="utf-8")
    compatibility_out = tmp_path / "threshold_package_missing_split_contract_compatibility.json"
    readiness_out = tmp_path / "threshold_package_missing_split_contract_readiness.json"
    out = tmp_path / "threshold_package_missing_split_roadmap_completion.json"
    review_docs = _write_contract_review_docs(tmp_path)

    report = build_evidence_grounding_roadmap_completion_audit_report_from_threshold_adoption_package(
        threshold_adoption_package_path=threshold_package,
        contract_compatibility_report_out=compatibility_out,
        contract_readiness_report_out=readiness_out,
        out=out,
        representative_split="eval",
        migration_plan_path=review_docs["migration"],
        backfill_plan_path=review_docs["backfill"],
        public_contract_doc_path=review_docs["public_contract"],
        contract_reviewer_approval_reference="contract-review-approval-123",
        allow_external_contract_ready=True,
        gold_release_package_path=tmp_path / "gold_release_package.json",
        correction_log_path=tmp_path / "claim_evidence_corrections.jsonl",
    )

    package_check = next(
        check for check in report.checks if check.requirement_id == "fixed_goldset_threshold_adoption_package_ready"
    )
    assert package_check.status == "fail"
    assert f"gold_release_package_path={(tmp_path / 'gold_release_package.json').resolve()}" in (
        package_check.evidence
    )
    assert "comparison_suite_count=2" in package_check.evidence
    assert "missing_splits=holdout" in package_check.evidence
    assert "fixed_goldset_threshold_adoption_package_ready" in report.blockers


