def test_compare_evidence_grounding_benchmark_reports_accepts_improvement(tmp_path):
    baseline = _benchmark_payload(
        benchmark_id="baseline",
        grounded_evidence_ratio=0.6,
        unresolved_grounding_rate=0.2,
        limitation_recall=0.4,
        figure_reference_precision=0.5,
        visual_evidence_unknown_rate=0.2,
        failure_counts_by_code={"UNSUPPORTED_CLAIM": 2},
        stage_failure_counts={"grounding_checker": 2},
        stage_runtime_metrics={"grounding_checker": {"grounded_evidence_ratio": 0.6}},
    )
    candidate = _benchmark_payload(
        benchmark_id="candidate",
        grounded_evidence_ratio=0.8,
        unresolved_grounding_rate=0.1,
        limitation_recall=0.6,
        figure_reference_precision=0.7,
        visual_evidence_unknown_rate=0.1,
        failure_counts_by_code={"UNSUPPORTED_CLAIM": 1},
        stage_failure_counts={"grounding_checker": 1},
        stage_runtime_metrics={
            "grounding_checker": {
                "grounded_evidence_ratio": 0.8,
                "correction_reuse_candidate_rate": 1.0,
                "reviewed_eval_fixture_count": 2.0,
            }
        },
    )

    report = compare_evidence_grounding_scorecard_reports(
        baseline=baseline,
        candidate=candidate,
        tolerance=0.0,
    )

    assert report.decision.passed is True
    assert report.decision.regressions == []
    assert report.correction_reuse_gain.status == "available"
    assert report.correction_reuse_gain.candidate_reuse_signal is True
    assert report.correction_reuse_gain.candidate_correction_reuse_candidate_rate == 1.0
    assert report.correction_reuse_gain.candidate_reviewed_eval_fixture_count == 2.0
    assert report.correction_reuse_gain.improved_p0_metric_count == 1
    assert report.correction_reuse_gain.regressed_p0_metric_count == 0
    assert report.correction_reuse_gain.metric_improvements["limitation_recall"] == 0.2
    assert "figure_reference_precision" not in report.correction_reuse_gain.metric_improvements
    assert report.correction_reuse_gain.net_p0_improvement == 0.2
    assert "gold_metrics_unavailable" not in report.decision.notes
    assert "failure_counts_unavailable" not in report.decision.notes
    assert "stage_metrics_unavailable" not in report.decision.notes
    assert "correction_reuse_gain_unavailable" not in report.decision.notes
    assert {comparison.name: comparison.delta for comparison in report.failure_count_comparisons} == {
        "UNSUPPORTED_CLAIM": -1,
        "grounding_checker": -1,
    }
    assert {
        (comparison.stage, comparison.metric_group, comparison.name): comparison.delta
        for comparison in report.stage_metric_comparisons
    } == {
        ("grounding_checker", "runtime_proxy_metrics", "grounded_evidence_ratio"): 0.2,
    }
    assert {comparison.name for comparison in report.comparisons} >= {
        "grounded_evidence_ratio",
        "unresolved_grounding_rate",
        "limitation_recall",
        "figure_reference_precision",
        "visual_evidence_unknown_rate",
    }


