def test_compare_evidence_grounding_benchmark_reports_can_gate_explicit_metric_subset(tmp_path):
    baseline = _benchmark_payload(
        benchmark_id="baseline",
        grounded_evidence_ratio=0.8,
        unresolved_grounding_rate=0.1,
        limitation_recall=0.6,
        figure_reference_precision=0.8,
        visual_evidence_unknown_rate=0.1,
    )
    candidate = _benchmark_payload(
        benchmark_id="candidate",
        grounded_evidence_ratio=0.8,
        unresolved_grounding_rate=0.1,
        limitation_recall=0.6,
        figure_reference_precision=0.5,
        visual_evidence_unknown_rate=0.1,
    )

    filtered = compare_evidence_grounding_scorecard_reports(
        baseline=baseline,
        candidate=candidate,
        tolerance=0.0,
        gate_metric_names=["limitation_recall"],
    )

    assert filtered.decision.passed is True
    assert filtered.gate_policy == "explicit"
    assert filtered.gate_metric_names == ["limitation_recall"]
    assert "metric_gate_filter_applied" in filtered.decision.notes
    figure_comparison = next(
        comparison for comparison in filtered.comparisons if comparison.name == "figure_reference_precision"
    )
    assert figure_comparison.regression is True
    assert "figure_reference_precision" not in filtered.decision.regressions

    promoted = compare_evidence_grounding_scorecard_reports(
        baseline=baseline,
        candidate=candidate,
        tolerance=0.0,
        gate_metric_names=["figure_reference_precision"],
    )

    assert promoted.decision.passed is False
    assert promoted.decision.regressions == ["figure_reference_precision"]


