def test_run_evidence_grounding_fixed_goldset_comparison_suite(tmp_path):
    gold_dir = tmp_path / "goldset" / "gold"
    manifest_dir = tmp_path / "goldset" / "manifests"
    baseline_root = tmp_path / "runs" / "baseline"
    candidate_root = tmp_path / "runs" / "candidate"
    out_dir = tmp_path / "comparison"
    gold_dir.mkdir(parents=True)
    manifest_dir.mkdir(parents=True)
    (gold_dir / "paper-1.json").write_text(json.dumps(_ready_gold_payload("paper-1")), encoding="utf-8")
    goldset_manifest = manifest_dir / "paper_understanding_eval.json"
    goldset_manifest.write_text(
        json.dumps(
            {
                "schema_version": "paper_understanding_gold_manifest.v1",
                "goldset_id": "paper-understanding-seed",
                "goldset_split": "eval",
                "items": [{"paper_id": "paper-1", "gold_path": "../gold/paper-1.json"}],
            }
        ),
        encoding="utf-8",
    )
    baseline_run = baseline_root / "paper-1"
    candidate_run = candidate_root / "paper-1"
    _write_run_dir(
        baseline_run,
        run_id="baseline",
        grounded_ratio=0.6,
        page_coverage_ratio=0.5,
        unsupported_claim_count=1,
        unresolved_span_count=1,
    )
    _write_matching_claimset_for_ready_gold(baseline_run)
    _write_run_dir(
        candidate_run,
        run_id="candidate",
        grounded_ratio=0.8,
        page_coverage_ratio=0.7,
        unsupported_claim_count=0,
        unresolved_span_count=0,
    )
    _write_matching_claimset_for_ready_gold(candidate_run)

    report = run_evidence_grounding_fixed_goldset_comparison_suite(
        goldset_manifest_path=goldset_manifest,
        baseline_run_root=baseline_root,
        candidate_run_root=candidate_root,
        out_dir=out_dir,
        gate_preset="p0_gold",
        baseline_candidate_config=EvidenceGroundingCandidateConfig(
            parser_version="baseline-parser-v1",
            llm_provider="local",
            llm_model="reader-model",
            llm_model_version="baseline-reader-model-2026-05-22",
            prompt_version="baseline-grounding-prompt-v1",
            reader_profile_version="baseline-reader-profile-v1",
        ),
        candidate_candidate_config=EvidenceGroundingCandidateConfig(
            parser_version="candidate-parser-v2",
            llm_provider="local",
            llm_model="reader-model",
            llm_model_version="candidate-reader-model-2026-05-22",
            prompt_version="candidate-grounding-prompt-v2",
            reader_profile_version="candidate-reader-profile-v2",
        ),
    )

    assert report.decision.passed is True
    assert (out_dir / "baseline_benchmark_manifest.json").exists()
    assert (out_dir / "candidate_benchmark_manifest.json").exists()
    assert (out_dir / "baseline_benchmark_report.json").exists()
    assert (out_dir / "candidate_benchmark_report.json").exists()
    assert (out_dir / "run_readiness_report.json").exists()
    assert (out_dir / "comparison_report.json").exists()
    suite_payload = json.loads((out_dir / "comparison_suite.json").read_text(encoding="utf-8"))
    suite = EvidenceGroundingFixedGoldsetComparisonSuite.model_validate(suite_payload)
    assert suite_payload["schema_version"] == "evidence_grounding_fixed_goldset_comparison_suite.v1"
    assert suite.canonical_status == "non_canonical"
    assert suite_payload["comparison_passed"] is True
    assert suite_payload["run_readiness_report_path"] == "run_readiness_report.json"
    assert suite_payload["comparison_run_ready"] is True
    run_readiness_payload = json.loads((out_dir / "run_readiness_report.json").read_text(encoding="utf-8"))
    assert run_readiness_payload["schema_version"] == "evidence_grounding_fixed_goldset_run_readiness.v1"
    assert run_readiness_payload["comparison_run_ready"] is True
    baseline_report = json.loads((out_dir / "baseline_benchmark_report.json").read_text(encoding="utf-8"))
    assert baseline_report["aggregate_gold_scored_metrics"]["claim_recall"]["status"] == "available"
    candidate_manifest = json.loads((out_dir / "candidate_benchmark_manifest.json").read_text(encoding="utf-8"))
    assert candidate_manifest["items"][0]["candidate_config"]["parser_version"] == "candidate-parser-v2"
    candidate_report = json.loads((out_dir / "candidate_benchmark_report.json").read_text(encoding="utf-8"))
    assert candidate_report["candidate_configs"][0]["prompt_version"] == "candidate-grounding-prompt-v2"


