def test_build_evidence_grounding_threshold_calibration_report_from_benchmark_reports(tmp_path):
    report_a = tmp_path / "candidate-a.json"
    report_b = tmp_path / "candidate-b.json"
    out = tmp_path / "threshold_calibration.json"
    report_a.write_text(
        json.dumps(
            _benchmark_payload(
                benchmark_id="candidate-a",
                claim_precision=0.82,
                evidence_support_precision=0.84,
                locator_precision=0.78,
                unsupported_claim_rate=0.04,
                overstatement_rate=0.03,
                limitation_recall=0.7,
                method_result_confusion_rate=0.02,
            )
        ),
        encoding="utf-8",
    )
    report_b.write_text(
        json.dumps(
            _benchmark_payload(
                benchmark_id="candidate-b",
                claim_precision=0.9,
                evidence_support_precision=0.81,
                locator_precision=0.8,
                unsupported_claim_rate=0.05,
                overstatement_rate=0.01,
                limitation_recall=0.62,
                method_result_confusion_rate=0.04,
            )
        ),
        encoding="utf-8",
    )

    report = build_evidence_grounding_threshold_calibration_report(
        report_paths=[report_a, report_b],
        out=out,
    )

    assert out.exists()
    assert report.schema_version == "evidence_grounding_threshold_calibration.v1"
    assert report.canonical_status == "non_canonical"
    assert report.metric_preset == "p0_gold"
    assert report.report_count == 2
    recommendations = {recommendation.name: recommendation for recommendation in report.recommendations}
    assert recommendations["claim_precision"].threshold_kind == "minimum"
    assert recommendations["claim_precision"].recommended_threshold == 0.82
    assert recommendations["unsupported_claim_rate"].threshold_kind == "maximum"
    assert recommendations["unsupported_claim_rate"].recommended_threshold == 0.05
    assert recommendations["limitation_recall"].observed_values == [0.7, 0.62]
    assert all(recommendation.status == "available" for recommendation in recommendations.values())
    threshold_values = threshold_metric_values_from_calibration_report(report)
    assert threshold_values["gold_scored_metrics.claim_precision"] == 0.82
    assert threshold_values["gold_scored_metrics.unsupported_claim_rate"] == 0.05


def test_build_evidence_grounding_threshold_calibration_report_marks_missing_metrics_not_available(tmp_path):
    report_path = tmp_path / "candidate.json"
    report_path.write_text(
        json.dumps(_benchmark_payload(benchmark_id="candidate", limitation_recall=0.7)),
        encoding="utf-8",
    )

    report = build_evidence_grounding_threshold_calibration_report(
        report_paths=[report_path],
        metric_names=["claim_precision", "limitation_recall"],
        metric_preset="explicit",
    )

    recommendations = {recommendation.name: recommendation for recommendation in report.recommendations}
    assert recommendations["claim_precision"].status == "not_available"
    assert recommendations["claim_precision"].recommended_threshold is None
    assert recommendations["limitation_recall"].status == "available"
    assert recommendations["limitation_recall"].recommended_threshold == 0.7


