def test_build_evidence_grounding_contract_compatibility_report_from_comparison_suite_covers_schema_family(tmp_path):
    paths = _write_threshold_adoption_inputs(tmp_path)
    threshold_adoption_path = tmp_path / "threshold_adoption.json"
    out = tmp_path / "compatibility_from_suite.json"
    for key, benchmark_id, claim_precision in (
        ("baseline", "baseline", 0.9),
        ("candidate", "candidate", 0.91),
    ):
        paths[key].write_text(
            json.dumps(
                _benchmark_payload(
                    benchmark_id=benchmark_id,
                    claim_precision=claim_precision,
                    evidence_support_precision=claim_precision,
                    locator_precision=claim_precision,
                    unsupported_claim_rate=0.01,
                    overstatement_rate=0.01,
                    limitation_recall=claim_precision,
                    method_result_confusion_rate=0.01,
                    input_artifact_coverage_rate=1.0,
                    missing_input_artifact_count=0.0,
                    include_scorecard=True,
                )
            ),
            encoding="utf-8",
        )
    build_evidence_grounding_threshold_adoption_review_report(
        calibration_report_path=paths["calibration"],
        comparison_suite_path=paths["comparison_suite"],
        reviewer_approval_reference="threshold-review-approval-123",
        allow_production_threshold_ready=True,
        out=threshold_adoption_path,
    )

    report = build_evidence_grounding_contract_compatibility_report_from_comparison_suite(
        comparison_suite_path=paths["comparison_suite"],
        threshold_calibration_report_path=paths["calibration"],
        threshold_adoption_review_path=threshold_adoption_path,
        out=out,
    )

    schema_versions = {item.schema_version for item in report.items}
    assert out.exists()
    assert report.schema_version == "evidence_grounding_contract_compatibility.v1"
    assert report.artifact_count == 9
    assert report.fail_count == 0
    assert report.warnings == []
    assert {
        "evidence_grounding_benchmark.v1",
        "evidence_grounding_fixed_goldset_comparison_suite.v1",
        "evidence_grounding_fixed_goldset_run_readiness.v1",
        "evidence_grounding_scorecard.v1",
        "evidence_grounding_scorecard_comparison.v1",
        "evidence_grounding_threshold_adoption_review.v1",
        "evidence_grounding_threshold_calibration.v1",
    } <= schema_versions
    assert any("#scorecards[0].scorecard" in item.path for item in report.items)


def test_contract_compatibility_from_comparison_suite_rejects_embedded_stale_scorecard_input_summary(
    tmp_path,
):
    paths = _write_threshold_adoption_inputs(tmp_path)
    threshold_adoption_path = tmp_path / "threshold_adoption.json"
    baseline_payload = _benchmark_payload(
        benchmark_id="baseline",
        claim_precision=0.9,
        evidence_support_precision=0.9,
        locator_precision=0.9,
        unsupported_claim_rate=0.01,
        overstatement_rate=0.01,
        limitation_recall=0.9,
        method_result_confusion_rate=0.01,
        input_artifact_coverage_rate=1.0,
        missing_input_artifact_count=0.0,
        include_scorecard=True,
    )
    baseline_payload["scorecards"][0]["scorecard"]["input_artifact_summary"] = {
        "source_artifact_count": 99,
        "input_artifact_diagnostic_count": 4,
        "core_input_artifact_count": 4,
        "loaded_core_input_artifact_count": 4,
        "missing_core_input_artifact_count": 0,
        "load_failed_core_input_artifact_count": 0,
        "non_core_input_artifact_count": 0,
    }
    paths["baseline"].write_text(json.dumps(baseline_payload), encoding="utf-8")
    paths["candidate"].write_text(
        json.dumps(
            _benchmark_payload(
                benchmark_id="candidate",
                claim_precision=0.91,
                evidence_support_precision=0.91,
                locator_precision=0.91,
                unsupported_claim_rate=0.01,
                overstatement_rate=0.01,
                limitation_recall=0.91,
                method_result_confusion_rate=0.01,
                input_artifact_coverage_rate=1.0,
                missing_input_artifact_count=0.0,
                include_scorecard=True,
            )
        ),
        encoding="utf-8",
    )
    build_evidence_grounding_threshold_adoption_review_report(
        calibration_report_path=paths["calibration"],
        comparison_suite_path=paths["comparison_suite"],
        reviewer_approval_reference="threshold-review-approval-123",
        allow_production_threshold_ready=True,
        out=threshold_adoption_path,
    )

    report = build_evidence_grounding_contract_compatibility_report_from_comparison_suite(
        comparison_suite_path=paths["comparison_suite"],
        threshold_calibration_report_path=paths["calibration"],
        threshold_adoption_review_path=threshold_adoption_path,
        out=tmp_path / "compatibility_from_suite.json",
    )

    embedded_item = next(
        item
        for item in report.items
        if item.path.endswith("#scorecards[0].scorecard")
        and item.schema_version == "evidence_grounding_scorecard.v1"
    )
    benchmark_item = next(
        item
        for item in report.items
        if item.path == str(paths["baseline"].resolve())
        and item.schema_version == "evidence_grounding_benchmark.v1"
    )
    assert report.fail_count == 2
    assert benchmark_item.status == "fail"
    assert any(
        finding.startswith("benchmark_schema_validation_failed:")
        and "input_artifact_summary" in finding
        for finding in benchmark_item.findings
    )
    assert embedded_item.status == "fail"
    assert (
        "scorecard_input_artifact_summary_mismatch: source_artifact_count"
        in embedded_item.findings
    )


