def test_build_evidence_grounding_contract_compatibility_report_rejects_scorecard_pass_with_missing_reader_input(
    tmp_path,
):
    artifact_path = tmp_path / "scorecard.json"
    stale_payload = _scorecard_payload()
    stale_payload["readiness_status"] = "pass"
    stale_payload["recommended_next_action"] = "none"
    for diagnostic in stale_payload["input_artifact_diagnostics"]:
        if diagnostic["artifact"] == "reader_eval.json":
            diagnostic["status"] = "load_failed"
