    linked_review_path = Path(payload["threshold_adoption_review_paths"][0]).resolve()
    linked_review = json.loads(linked_review_path.read_text(encoding="utf-8"))
    linked_review["production_threshold_ready"] = False
    linked_review_path.write_text(json.dumps(linked_review), encoding="utf-8")

    report = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[artifact_path],
    )

    assert report.fail_count == 1
    assert report.items[0].status == "fail"
    assert {
        "threshold_adoption_package_linked_review_ready_count_mismatch",
        "threshold_adoption_package_linked_review_blocked_count_mismatch",
        "threshold_adoption_package_linked_review_threshold_adoption_not_ready_without_failures",
    } <= set(report.items[0].findings)


