def test_build_evidence_grounding_contract_compatibility_report_rejects_stale_fill_review_suggestion_counts(
    tmp_path,
):
    template_path = tmp_path / "candidate_lineage_patch_template.json"
    readiness_path = tmp_path / "candidate_lineage_patch_template_fill_readiness.json"
    task_export_path = tmp_path / "candidate_lineage_patch_template_fill_tasks.json"
    reviewed_csv_path = tmp_path / "candidate_lineage_patch_template_fill_tasks_reviewed.csv"
    artifact_path = tmp_path / "candidate_lineage_patch_template_fill_review_status.json"
    template_path.write_text(json.dumps(_candidate_lineage_patch_template_payload()), encoding="utf-8")
    build_evidence_grounding_patch_template_fill_readiness_report(
        patch_template_path=template_path,
        out=readiness_path,
    )
    build_evidence_grounding_patch_template_fill_task_export(
        fill_readiness_path=readiness_path,
        out=task_export_path,
    )
    _write_reviewed_fill_task_csv(
        task_export_path=task_export_path,
        out=reviewed_csv_path,
        values_by_field={"llm_provider": "provider-reviewed"},
    )
    review_status = build_evidence_grounding_patch_template_fill_review_status_report(
        task_export_path=task_export_path,
        reviewed_csv_path=reviewed_csv_path,
    )
    payload = review_status.model_dump(mode="json")
    payload["suggested_value_count_by_field"] = {"llm_provider": 1}
    payload["missing_suggestion_count_by_field"] = {}
    payload["missing_suggestion_task_ids_by_field"] = {
        "llm_provider": ["unexpected-task"],
    }
    payload["available_context_count_by_field"] = {}
    payload["available_context_keys_by_field"] = {"llm_provider": ["stale.context"]}
    payload["missing_context_count_by_field"] = {"llm_provider": 1}
    payload["missing_context_task_ids_by_field"] = {
        "llm_provider": ["unexpected-task"],
    }
    payload["open_record_count"] = 999
    payload["open_record_refs"] = ["unexpected-record"]
    payload["open_field_names_by_record_ref"] = {
        "unexpected-record": ["unexpected-field"],
    }
    payload["open_task_ids"] = ["unexpected-task"]
    payload["open_task_ids_by_field"] = {"llm_provider": ["unexpected-task"]}
    payload["open_task_ids_by_record_ref"] = {
        "unexpected-record": ["unexpected-task"],
    }
    artifact_path.write_text(json.dumps(payload), encoding="utf-8")

    report = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[artifact_path],
    )

    assert report.fail_count == 1
    assert report.warnings == ["compatibility_failures_present"]
    assert report.items[0].status == "fail"
    assert {
        "patch_template_fill_review_status_suggested_value_count_by_field_mismatch",
        "patch_template_fill_review_status_missing_suggestion_count_by_field_mismatch",
        "patch_template_fill_review_status_missing_suggestion_task_ids_by_field_mismatch",
        "patch_template_fill_review_status_available_context_count_by_field_mismatch",
        "patch_template_fill_review_status_available_context_keys_by_field_mismatch",
        "patch_template_fill_review_status_missing_context_count_by_field_mismatch",
        "patch_template_fill_review_status_missing_context_task_ids_by_field_mismatch",
        "patch_template_fill_review_status_open_record_count_mismatch",
        "patch_template_fill_review_status_open_record_refs_mismatch",
        "patch_template_fill_review_status_open_field_names_by_record_ref_mismatch",
        "patch_template_fill_review_status_open_task_ids_mismatch",
        "patch_template_fill_review_status_open_task_ids_by_field_mismatch",
        "patch_template_fill_review_status_open_task_ids_by_record_ref_mismatch",
    } <= set(report.items[0].findings)


