def test_evidence_grounding_roadmap_completion_report_requires_inherited_blocked_by_requirement_ids():
    export_action_text = (
        "Export replayable claim/evidence eval candidates from repaired or replayable "
        "claim/evidence corrections before intake import."
    )
    actions = [
        EvidenceGroundingRoadmapCompletionNextAction(
            requirement_id="p0_metrics_reported",
            action=export_action_text,
            phase="fixed_goldset_run",
            command_hint=(
                ".venv/bin/python scripts/eval/export_claim_evidence_eval_candidates.py "
                "--log-path <repaired.jsonl> --out <candidates.json>"
            ),
            blocked_by_requirement_ids=["structured_correction_log"],
        ),
        EvidenceGroundingRoadmapCompletionNextAction(
            requirement_id="p0_metrics_reported",
            action=(
                "Import replayable claim/evidence eval candidates into the "
                "reviewed-fixture intake queue."
            ),
            phase="fixed_goldset_run",
            command_hint=(
                ".venv/bin/python scripts/eval/import_claim_evidence_eval_candidates.py "
                "--export <candidates.json> --goldset-root goldset --require-replayable"
            ),
        ),
    ]
    with pytest.raises(
        ValueError,
        match="next_actions blocked_by_requirement_ids must match failed checks",
    ):
        EvidenceGroundingRoadmapCompletionAuditReport(
            generated_at=datetime.now(timezone.utc),
            audit_id="roadmap-inherited-blocked-by-contract",
            fail_count=2,
            blockers=["structured_correction_log", "p0_metrics_reported"],
            warnings=["roadmap_completion_blocked"],
            checks=[
                EvidenceGroundingRoadmapCompletionCheck(
                    requirement_id="structured_correction_log",
                    requirement="Structured correction log is replayable.",
                    status="fail",
                    next_actions=["Fix the structured correction log."],
                ),
                EvidenceGroundingRoadmapCompletionCheck(
                    requirement_id="p0_metrics_reported",
                    requirement="P0 metrics are reported.",
                    status="fail",
                    evidence=["missing_p0_metrics=overstatement_rate"],
                    next_actions=[export_action_text],
                ),
            ],
            next_actions=actions,
            next_action_count=2,
            next_action_phase_counts={"fixed_goldset_run": 2},
            **_roadmap_frontier_kwargs(
                *actions,
                failed_requirement_ids={
                    "structured_correction_log",
                    "p0_metrics_reported",
                },
            ),
        )


