def test_roadmap_frontier_command_counts_exclude_blocked_actions():
    blocked_placeholder = EvidenceGroundingRoadmapCompletionNextAction(
        requirement_id="fixed_goldset_threshold_adoption_package_ready",
        action=(
            "Export replayable claim/evidence eval candidates from repaired or replayable "
            "claim/evidence corrections before intake import."
        ),
        phase="threshold_package",
        kind="placeholder_command",
        command_hint=(
            ".venv/bin/python scripts/eval/export_claim_evidence_eval_candidates.py "
            "--log-path ./storage/claim_evidence_corrections.jsonl "
            "--out <claim_evidence_eval_candidates.json> --require-replayable"
        ),
        blocked_by_requirement_ids=["structured_correction_log"],
        blocker_reasons=[
            "blocked_by_requirement",
            "unresolved_command_placeholders",
        ],
    )
    blocked_ready = EvidenceGroundingRoadmapCompletionNextAction(
        requirement_id="external_contract_readiness_reviewed",
        action="Re-run contract compatibility over the required evidence-grounding artifacts.",
        phase="contract_readiness",
        kind="ready_to_run_command",
        command_hint=(
            ".venv/bin/python scripts/eval/check_evidence_grounding_contract_compatibility.py "
            "--artifact artifact.json --out compatibility.json"
        ),
        blocked_by_requirement_ids=["structured_correction_log"],
        blocker_reasons=["blocked_by_requirement"],
    )
    unblocked_placeholder = EvidenceGroundingRoadmapCompletionNextAction(
        requirement_id="candidate_configuration_lineage",
        action="Apply the filled candidate lineage patch template.",
        phase="fixed_goldset_run",
        kind="placeholder_command",
        command_hint=(
            ".venv/bin/python scripts/eval/apply_evidence_grounding_candidate_lineage_patch_template.py "
            "--patch-template <candidate_lineage_patch_template_filled.json>"
        ),
        blocker_reasons=["unresolved_command_placeholders"],
    )

    assert _roadmap_frontier_placeholder_command_next_action_count(
        [blocked_placeholder, unblocked_placeholder]
    ) == 1
    assert _roadmap_frontier_ready_to_run_next_action_count([blocked_ready]) == 0


