def test_evidence_grounding_roadmap_completion_report_rejects_stale_warning_markers():
    failed_checks = [
        EvidenceGroundingRoadmapCompletionCheck(
            requirement_id="candidate_configuration_lineage",
            requirement="Candidate benchmark carries replay lineage.",
            status="fail",
            next_actions=["Fix the candidate lineage reviewed fill-task CSV."],
        )
    ]
    warn_checks = [
        EvidenceGroundingRoadmapCompletionCheck(
            requirement_id="external_contract_readiness_reviewed",
            requirement="External contract readiness has review evidence.",
            status="warn",
        )
    ]

    with pytest.raises(
        ValueError,
        match="warnings must include roadmap_completion_blocked when failures are present",
    ):
        EvidenceGroundingRoadmapCompletionAuditReport(
            generated_at=datetime.now(timezone.utc),
            audit_id="roadmap-blocked-warning-contract",
            checks=failed_checks,
            fail_count=1,
            blockers=["candidate_configuration_lineage"],
        )

    with pytest.raises(
        ValueError,
        match="warnings must include roadmap_completion_warnings_present when warnings are present",
    ):
        EvidenceGroundingRoadmapCompletionAuditReport(
            generated_at=datetime.now(timezone.utc),
            audit_id="roadmap-warn-warning-contract",
            checks=warn_checks,
            warn_count=1,
            roadmap_complete=True,
        )


def test_build_evidence_grounding_contract_compatibility_report_rejects_stale_claim_evidence_eval_candidate_export(
    tmp_path,
):
    artifact_path = tmp_path / "claim_evidence_eval_candidates.json"
    payload = _claim_evidence_eval_candidate_export_payload()
    payload["candidate_count"] = 2
    payload["candidates"][0]["after_evidence_refs"] = []
    artifact_path.write_text(json.dumps(payload), encoding="utf-8")

    report = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[artifact_path],
    )

    assert report.fail_count == 1
    assert report.warnings == ["compatibility_failures_present"]
    assert report.items[0].status == "fail"
    assert {
        "claim_evidence_eval_candidate_export_candidate_count_mismatch",
        "claim_evidence_eval_candidate_export_nonreplayable_candidates",
        "claim_evidence_eval_candidate_export_no_replayable_candidates",
    } <= set(report.items[0].findings)


