def _roadmap_completion_compatibility_required_field_names() -> set[str]:
    root = Path(__file__).resolve().parents[1]
    service_source = (root / "src/services/evidence_grounding_benchmark.py").read_text(
        encoding="utf-8"
    )
    compatibility_block = re.search(
        r'if schema_version == "evidence_grounding_roadmap_completion_audit\.v1":'
        r".*?for field_name in \((.*?)\):\n\s+if field_name not in payload:",
        service_source,
        flags=re.S,
    )

    assert compatibility_block is not None
    return set(re.findall(r'"([a-zA-Z0-9_]+)"', compatibility_block.group(1)))


