def test_build_evidence_grounding_contract_compatibility_report_rejects_stale_roadmap_completion_without_p0_gold_path_probe(
    tmp_path,
):
    paths = _write_roadmap_completion_package_inputs(tmp_path)
    candidate_payload = json.loads(paths["candidate"].read_text(encoding="utf-8"))
    candidate_payload["aggregate_gold_scored_metrics"].pop("overstatement_rate")
    candidate_payload["scorecards"][0]["scorecard"]["gold_scored_metrics"]["overstatement_rate"] = {
        "status": "not_available",
        "source": "paper_understanding_gold.review_failure_codes",
        "detail": "Requires explicit OVERSTATED_RESULT labels or structured human review.",
    }
    paths["candidate"].write_text(json.dumps(candidate_payload), encoding="utf-8")

    roadmap_report = build_evidence_grounding_roadmap_completion_audit_report(
        comparison_suite_path=paths["comparison_suite"],
        gold_release_package_path=paths["gold_release_package"],
        gold_release_readiness_report_path=paths["gold_release_readiness"],
    )
    stale_payload = roadmap_report.model_dump(mode="json")
    p0_check = next(
        item for item in stale_payload["checks"] if item["requirement_id"] == "p0_metrics_reported"
    )
    p0_check["evidence"] = [
        item
        for item in p0_check["evidence"]
        if not item.startswith("gold_release_gold_path_count=")
        and not item.startswith("gold_release_gold_paths_sample=")
        and not item.startswith("gold_release_overstated_result_gold_paths_sample=")
    ]
    artifact_path = tmp_path / "roadmap_completion_stale_p0_probe.json"
    artifact_path.write_text(json.dumps(stale_payload), encoding="utf-8")

    report = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[artifact_path],
    )

    assert report.fail_count == 1
    assert report.items[0].status == "fail"
    assert {
        "roadmap_completion_p0_gold_path_count_missing",
        "roadmap_completion_p0_gold_paths_sample_missing",
        "roadmap_completion_p0_overstated_result_gold_paths_sample_missing",
    } <= set(report.items[0].findings)


