def test_build_evidence_grounding_contract_compatibility_report_rejects_stale_roadmap_next_action_metadata(
    tmp_path,
):
    artifact_path = tmp_path / "roadmap_completion.json"
    roadmap_report = build_evidence_grounding_roadmap_completion_audit_report()
    stale_payload = roadmap_report.model_dump(mode="json")
    action = stale_payload["next_actions"][0]
    original_phase = action["phase"]
    action["phase"] = "ghost_phase"
    stale_payload["next_action_phase_counts"][original_phase] -= 1
    if stale_payload["next_action_phase_counts"][original_phase] == 0:
        stale_payload["next_action_phase_counts"].pop(original_phase)
    stale_payload["next_action_phase_counts"]["ghost_phase"] = 1
    artifact_path.write_text(json.dumps(stale_payload), encoding="utf-8")

    report = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[artifact_path],
    )

    assert report.fail_count == 1
    assert report.warnings == ["compatibility_failures_present"]
    assert report.items[0].status == "fail"
    assert any(
        finding.startswith("roadmap_completion_next_action_phase_mismatch:")
        and action["requirement_id"] in finding
        for finding in report.items[0].findings
    )


def test_build_evidence_grounding_contract_compatibility_report_rejects_missing_roadmap_next_action_metadata(
    tmp_path,
):
    artifact_path = tmp_path / "roadmap_completion.json"
    roadmap_report = build_evidence_grounding_roadmap_completion_audit_report()
    stale_payload = roadmap_report.model_dump(mode="json")
    action = next(item for item in stale_payload["next_actions"] if item["requires_human_review"] is False)
    original_phase = action.pop("phase")
    action.pop("requires_human_review")
    stale_payload["next_action_phase_counts"][original_phase] -= 1
    if stale_payload["next_action_phase_counts"][original_phase] == 0:
        stale_payload["next_action_phase_counts"].pop(original_phase)
    stale_payload["next_action_phase_counts"]["unknown"] = (
        stale_payload["next_action_phase_counts"].get("unknown", 0) + 1
    )
    artifact_path.write_text(json.dumps(stale_payload), encoding="utf-8")

    report = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[artifact_path],
    )

    assert report.fail_count == 1
    assert report.warnings == ["compatibility_failures_present"]
    assert report.items[0].status == "fail"
    assert any(
        finding.startswith("roadmap_completion_next_action_phase_mismatch:")
        and action["requirement_id"] in finding
        for finding in report.items[0].findings
    )
    assert any(
        finding.startswith("roadmap_completion_next_action_review_flag_mismatch:")
        and action["requirement_id"] in finding
        for finding in report.items[0].findings
    )


