def test_build_evidence_grounding_contract_compatibility_report_rejects_unmasked_roadmap_next_action_path(
    tmp_path,
):
    artifact_path = tmp_path / "roadmap_completion.json"
    roadmap_report = build_evidence_grounding_roadmap_completion_audit_report()
    stale_payload = roadmap_report.model_dump(mode="json")
    action = next(item for item in stale_payload["next_actions"] if item.get("action"))
    local_path = tmp_path / "private-action-detail.json"
    action["action"] = f"{action['action']} See {local_path}."
    source_check = next(
        check
        for check in stale_payload["checks"]
        if check["requirement_id"] == action["requirement_id"]
        and action["action"].removesuffix(f" See {local_path}.") in check["next_actions"]
    )
    source_check["next_actions"] = [
        action["action"] if item == action["action"].removesuffix(f" See {local_path}.") else item
        for item in source_check["next_actions"]
    ]
    artifact_path.write_text(json.dumps(stale_payload), encoding="utf-8")

    report = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[artifact_path],
    )

    assert report.fail_count == 1
    assert report.warnings == ["compatibility_failures_present"]
    assert report.items[0].status == "fail"
    assert any(
        finding.startswith("roadmap_completion_next_action_unmasked_local_path:")
        and action["requirement_id"] in finding
        for finding in report.items[0].findings
    )


