def test_evidence_grounding_contract_compatibility_api_returns_noncanonical_report(tmp_path):
    artifact_path = tmp_path / "benchmark.json"
    out = tmp_path / "compatibility.json"
    artifact_path.write_text(
        json.dumps(_benchmark_payload(benchmark_id="candidate", claim_precision=0.84)),
        encoding="utf-8",
    )
    client = TestClient(api_main.app)

    response = client.post(
        "/evidence-grounding/contract-compatibility/audit",
        json={
            "artifact_paths": [str(artifact_path)],
            "out": str(out),
        },
    )

    assert response.status_code == 200
    payload = response.json()
    assert payload["schema_version"] == "evidence_grounding_contract_compatibility.v1"
    assert payload["canonical_status"] == "non_canonical"
    assert payload["external_contract_ready"] is False
    assert payload["artifact_count"] == 1
    assert payload["pass_count"] == 1
    assert payload["fail_count"] == 0
    assert payload["items"][0]["path"] == f".../{artifact_path.name}"
    assert str(tmp_path) not in json.dumps(payload)
    assert out.exists()
    written_payload = json.loads(out.read_text(encoding="utf-8"))
    assert written_payload["items"][0]["path"] == str(artifact_path.resolve())


