def test_build_evidence_grounding_contract_readiness_report_rejects_stale_compatibility_summary(
    tmp_path,
):
    artifact_path = tmp_path / "benchmark.json"
    compatibility_path = tmp_path / "compatibility.json"
    migration_plan = tmp_path / "migration.md"
    backfill_plan = tmp_path / "backfill.md"
    public_contract_doc = tmp_path / "contract.md"
    artifact_path.write_text(
        json.dumps({"schema_version": "not-a-supported-schema"}),
        encoding="utf-8",
    )
    migration_plan.write_text("Migration review complete.", encoding="utf-8")
    backfill_plan.write_text("Backfill review complete.", encoding="utf-8")
    public_contract_doc.write_text("Public contract reviewed.", encoding="utf-8")
    build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[artifact_path],
        out=compatibility_path,
    )
    payload = json.loads(compatibility_path.read_text(encoding="utf-8"))
    payload["pass_count"] = 1
    payload["fail_count"] = 0
    payload["warnings"] = []
    compatibility_path.write_text(json.dumps(payload), encoding="utf-8")

    report = build_evidence_grounding_contract_readiness_report(
        compatibility_report_path=compatibility_path,
        migration_plan_path=migration_plan,
        backfill_plan_path=backfill_plan,
        public_contract_doc_path=public_contract_doc,
        reviewer_approval_reference="review-approval-123",
        allow_external_contract_ready=True,
    )

    compatibility_check = next(check for check in report.checks if check.name == "compatibility_report_passes")
    findings = next(
        evidence
        for evidence in compatibility_check.evidence
        if evidence.startswith("compatibility_consistency_findings=")
    )
    assert report.external_contract_ready is False
    assert "compatibility_report_passes" in report.blockers
    assert "contract_compatibility_pass_count_mismatch" in findings
    assert "contract_compatibility_fail_count_mismatch" in findings
    assert "contract_compatibility_failure_warning_mismatch" in findings


