    assert payload["schema_version"] == "evidence_grounding_contract_readiness.v1"
    assert payload["external_contract_ready"] is True
    assert payload["compatibility_report_path"] == f".../{compatibility_path.name}"
    assert payload["migration_plan_path"] == f".../{migration_plan.name}"
    assert payload["backfill_plan_path"] == f".../{backfill_plan.name}"
    assert payload["public_contract_doc_path"] == f".../{public_contract_doc.name}"
    assert str(tmp_path) not in json.dumps(payload)
    assert compatibility_path.exists()
    assert readiness_path.exists()
    readiness_payload = json.loads(readiness_path.read_text(encoding="utf-8"))
    assert readiness_payload["compatibility_report_path"] == str(compatibility_path.resolve())
    assert readiness_payload["migration_plan_path"] == str(migration_plan.resolve())
    compatibility_payload = json.loads(compatibility_path.read_text(encoding="utf-8"))
    assert "claim_evidence_eval_candidate_export.v1" in {
        item["schema_version"] for item in compatibility_payload["items"]
    }


