    baseline_path.write_text(
        json.dumps(_benchmark_payload(benchmark_id="baseline", grounded_evidence_ratio=0.8)),
        encoding="utf-8",
    )
    candidate_path.write_text(
        json.dumps(_benchmark_payload(benchmark_id="candidate", grounded_evidence_ratio=0.7)),
        encoding="utf-8",
    )
    client = TestClient(api_main.app)

    response = client.post(
        "/evidence-grounding/scorecards/compare",
        json={
            "baseline_path": str(baseline_path),
            "candidate_path": str(candidate_path),
            "out": str(out),
        },
    )

