def test_build_evidence_grounding_roadmap_completion_audit_requires_matched_gold_run_inventory(tmp_path):
    goldset_root = tmp_path / "goldset" / "accepted"
    run_root = tmp_path / "storage" / "artifacts"
    goldset_root.mkdir(parents=True)
    out = tmp_path / "roadmap_completion.json"

    (goldset_root / "paper-1.json").write_text(json.dumps(_ready_gold_payload("paper-1")), encoding="utf-8")
    mismatched_run_dir = run_root / "paper-2" / "run-1"
    mismatched_run_dir.mkdir(parents=True)
    for artifact_name in (
        "reader_eval.json",
        "claimset_coverage.json",
        "evidence_extraction_bundle.json",
        "claimset.resolved.json",
    ):
        (mismatched_run_dir / artifact_name).write_text("{}", encoding="utf-8")

    report = build_evidence_grounding_roadmap_completion_audit_report(
        goldset_root=goldset_root,
        run_root=run_root,
        out=out,
    )

    inventory_check = next(check for check in report.checks if check.requirement_id == "workspace_evidence_inventory_ready")
    assert inventory_check.status == "fail"
    assert "ready_paper_understanding_gold_count=1" in inventory_check.evidence
    assert "ready_gold_paper_ids_sample=paper-1" in inventory_check.evidence
    assert "ready_run_dir_count=1" in inventory_check.evidence
    assert "ready_run_declared_paper_id_count=0" in inventory_check.evidence
    assert "ready_run_declared_paper_ids_sample=-" in inventory_check.evidence
    assert "ready_run_missing_identity_count=1" in inventory_check.evidence
    assert "matched_ready_gold_run_count=0" in inventory_check.evidence
    assert (
        "Regenerate scorecards or run metadata so complete run directories declare a single paper_id before matching fixed gold."
        in inventory_check.next_actions
    )
    assert (
        "Create or identify run directories whose declared paper_id matches the ready gold records and contains the required grounding sidecars."
        in inventory_check.next_actions
    )
    assert any(item.requirement_id == "fixed_goldset_candidate_run" for item in report.next_actions)
    assert "workspace_evidence_inventory_ready" in report.blockers

    matched_run_dir = run_root / "paper-1" / "run-1"
    matched_run_dir.mkdir(parents=True)
    for artifact_name in (
        "reader_eval.json",
        "claimset_coverage.json",
        "evidence_extraction_bundle.json",
        "claimset.resolved.json",
    ):
        (matched_run_dir / artifact_name).write_text("{}", encoding="utf-8")

    matched_report = build_evidence_grounding_roadmap_completion_audit_report(
        goldset_root=goldset_root,
        run_root=run_root,
        out=tmp_path / "roadmap_completion_matched.json",
    )

    matched_inventory_check = next(
        check for check in matched_report.checks if check.requirement_id == "workspace_evidence_inventory_ready"
    )
    assert matched_inventory_check.status == "pass"
    assert "ready_run_dir_count=2" in matched_inventory_check.evidence
    assert "ready_run_declared_paper_id_count=0" in matched_inventory_check.evidence
    assert "ready_run_missing_identity_count=2" in matched_inventory_check.evidence
    assert "ready_run_paper_id_count=1" in matched_inventory_check.evidence
    assert "ready_run_paper_ids_sample=paper-1" in matched_inventory_check.evidence
    assert "matched_ready_gold_run_count=1" in matched_inventory_check.evidence


