def test_build_evidence_grounding_roadmap_completion_audit_surfaces_missing_scorecard_inputs(tmp_path):
    paths = _write_roadmap_completion_package_inputs(tmp_path)
    payload = json.loads(paths["run_readiness"].read_text(encoding="utf-8"))
    candidate_lane = next(lane for lane in payload["lane_summaries"] if lane["lane"] == "candidate")
    candidate_item = candidate_lane["items"][0]
    candidate_lane["pass_count"] = 0
    candidate_lane["fail_count"] = 1
    candidate_lane["missing_required_artifact_count"] = 3
    candidate_item["status"] = "fail"
    candidate_item["present_required_artifacts"] = ["claimset.resolved.json"]
    candidate_item["missing_required_artifacts"] = [
        "reader_eval.json",
        "claimset_coverage.json",
        "evidence_extraction_bundle.json",
    ]
    candidate_item["present_optional_artifacts"] = []
    candidate_item["missing_optional_artifacts"] = ["visual_evidence_ledger.json"]
    payload["pass_count"] = 1
    payload["fail_count"] = 1
    payload["comparison_run_ready"] = False
    paths["run_readiness"].write_text(json.dumps(payload), encoding="utf-8")

    report = build_evidence_grounding_roadmap_completion_audit_report(
        candidate_benchmark_report_path=paths["candidate"],
        run_readiness_report_path=paths["run_readiness"],
        gold_release_package_path=paths["gold_release_package"],
        out=tmp_path / "roadmap_completion_missing_scorecard_inputs.json",
    )

    fixed_check = next(check for check in report.checks if check.requirement_id == "fixed_goldset_candidate_run")
    assert "run_readiness_missing_required_artifact_names=claimset_coverage.json,evidence_extraction_bundle.json,reader_eval.json" in fixed_check.evidence
    assert "run_readiness_missing_core_scorecard_input_names=claimset_coverage.json,evidence_extraction_bundle.json,reader_eval.json,visual_evidence_ledger.json" in fixed_check.evidence
    assert "run_readiness_items_missing_all_core_scorecard_inputs=1" in fixed_check.evidence
    assert fixed_check.next_actions[0] == (
        "Regenerate or identify scorecard-aware baseline/candidate run directories for the fixed goldset; "
        "at least one run-readiness item is missing all core scorecard sidecars "
        "(claimset_coverage.json,evidence_extraction_bundle.json,reader_eval.json,visual_evidence_ledger.json)."
    )
    source_repair_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "fixed_goldset_candidate_run"
        and item.action.startswith("Regenerate or identify scorecard-aware baseline/candidate run directories")
    )
    assert source_repair_action.command_hint is not None
    assert "discover_evidence_grounding_benchmark_run_dir_map_from_release_package.py" in (
        source_repair_action.command_hint
    )
    assert "build_evidence_grounding_benchmark_manifests_from_release_package.py" in (
        source_repair_action.command_hint
    )
    assert "backfill_evidence_grounding_scorecard_inputs.py" in source_repair_action.command_hint
    assert "audit_evidence_grounding_fixed_goldset_run_readiness.py" in source_repair_action.command_hint
    assert f"--release-package .../{paths['gold_release_package'].name}" in source_repair_action.command_hint
    assert "--out <baseline_run_dir_map.json>" in source_repair_action.command_hint
    assert "--out <candidate_run_dir_map.json>" in source_repair_action.command_hint
    assert "--run-dir-map <baseline_run_dir_map.json>" in source_repair_action.command_hint
    assert "--run-dir-map <candidate_run_dir_map.json>" in source_repair_action.command_hint
    assert "--run-dir-map-out <baseline_repaired_run_dir_map.json>" in source_repair_action.command_hint
    assert "--run-dir-map-out <candidate_repaired_run_dir_map.json>" in source_repair_action.command_hint
    assert "--baseline-run-dir-map <baseline_repaired_run_dir_map.json>" in source_repair_action.command_hint
    assert "--candidate-run-dir-map <candidate_repaired_run_dir_map.json>" in source_repair_action.command_hint
    assert str(paths["gold_release_package"].resolve()) not in source_repair_action.command_hint
    assert "fixed_goldset_candidate_run" in report.blockers


