def test_build_evidence_grounding_roadmap_completion_audit_skips_contract_rerun_when_only_human_readiness_blocks(
    tmp_path,
):
    paths = _write_standalone_roadmap_completion_ready_paths(tmp_path)
    payload = json.loads(paths["package_contract_readiness"].read_text(encoding="utf-8"))
    payload["checks"] = [
        check
        for check in payload["checks"]
        if check["name"] not in {"reviewer_approval_reference_present", "explicit_external_contract_opt_in"}
    ]
    payload["checks"].extend(
        [
            {
                "name": "reviewer_approval_reference_present",
                "status": "fail",
                "detail": "Missing reviewer approval reference.",
                "evidence": [],
            },
            {
                "name": "explicit_external_contract_opt_in",
                "status": "fail",
                "detail": "Missing explicit external-contract opt-in.",
                "evidence": [],
            },
        ]
    )
    payload["pass_count"] = sum(1 for check in payload["checks"] if check["status"] == "pass")
    payload["fail_count"] = 2
    payload["blockers"] = ["reviewer_approval_reference_present", "explicit_external_contract_opt_in"]
    payload["external_contract_ready"] = False
    paths["package_contract_readiness"].write_text(json.dumps(payload), encoding="utf-8")

    report = build_evidence_grounding_roadmap_completion_audit_report(
        comparison_suite_path=paths["comparison_suite"],
        threshold_calibration_report_path=paths["package_threshold_calibration"],
        threshold_adoption_review_path=paths["package_threshold_adoption"],
        contract_readiness_report_path=paths["package_contract_readiness"],
        gold_release_package_path=paths["gold_release_package"],
        correction_log_path=paths["correction_log"],
        out=tmp_path / "roadmap_completion_only_contract_human_readiness.json",
    )

    contract_check = next(
        check for check in report.checks if check.requirement_id == "external_contract_readiness_reviewed"
    )
    assert contract_check.status == "fail"
    assert "contract_compatibility_fail_count=0" in contract_check.evidence
    assert any(
        item.startswith("contract_compatibility_report_path=")
        and paths["package_contract_compatibility"].name in item
        for item in contract_check.evidence
    )
    assert any(
        item.startswith("contract_readiness_report_path=")
        and paths["package_contract_readiness"].name in item
        for item in contract_check.evidence
    )
    assert any(
        item.startswith("migration_plan_path=") and paths["migration"].name in item
        for item in contract_check.evidence
    )
    assert any(
        item.startswith("backfill_plan_path=") and paths["backfill"].name in item
        for item in contract_check.evidence
    )
    assert any(
        item.startswith("public_contract_doc_path=") and paths["public_contract"].name in item
        for item in contract_check.evidence
    )
    assert "failed_contract_schema_versions=-" in contract_check.evidence
    assert "missing_contract_schema_versions=-" in contract_check.evidence
    assert "missing_contract_compatibility_artifact_paths=-" in contract_check.evidence
    assert not any(
        item.requirement_id == "external_contract_readiness_reviewed"
        and item.action.startswith("Run contract compatibility over")
        for item in report.next_actions
    )
    contract_approval_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "external_contract_readiness_reviewed"
        and item.requires_human_review
    )
    assert contract_approval_action.action.startswith(
        "Complete human approval reference and explicit opt-in before external contract readiness is marked ready"
    )
    assert contract_approval_action.command_hint is not None
    assert "audit_evidence_grounding_contract_readiness.py" in contract_approval_action.command_hint
    assert "audit_evidence_grounding_contract_readiness_from_threshold_adoption_package.py" not in (
        contract_approval_action.command_hint
    )
    assert "--additional-artifact" not in contract_approval_action.command_hint
    assert f"--compatibility-report .../{paths['package_contract_compatibility'].name}" in (
        contract_approval_action.command_hint
    )
    assert f"--out .../{paths['package_contract_readiness'].name}" in (
        contract_approval_action.command_hint
    )
    assert "--out <contract_readiness.json>" not in contract_approval_action.command_hint
    assert f"--migration-plan .../{paths['migration'].name}" in contract_approval_action.command_hint
    assert f"--backfill-plan .../{paths['backfill'].name}" in contract_approval_action.command_hint
    assert f"--public-contract-doc .../{paths['public_contract'].name}" in contract_approval_action.command_hint
    assert "--reviewer-approval-reference <approval_ref>" in contract_approval_action.command_hint
    assert "--allow-external-contract-ready" in contract_approval_action.command_hint


def test_build_evidence_grounding_roadmap_completion_audit_rejects_contract_compatibility_for_different_artifact(
    tmp_path,
):
    paths = _write_standalone_roadmap_completion_ready_paths(tmp_path)
    payload = json.loads(paths["package_contract_compatibility"].read_text(encoding="utf-8"))
    expected_path = str(paths["package_threshold_calibration"].resolve())
    replacement_path = tmp_path / "other_threshold_calibration.json"
    for item in payload["items"]:
        if item["path"] == expected_path:
            item["path"] = str(replacement_path.resolve())
            break
    else:
        raise AssertionError("expected threshold calibration compatibility item")
    paths["package_contract_compatibility"].write_text(json.dumps(payload), encoding="utf-8")

    report = build_evidence_grounding_roadmap_completion_audit_report(
        comparison_suite_path=paths["comparison_suite"],
        threshold_calibration_report_path=paths["package_threshold_calibration"],
        threshold_adoption_review_path=paths["package_threshold_adoption"],
        contract_readiness_report_path=paths["package_contract_readiness"],
        gold_release_package_path=paths["gold_release_package"],
        correction_log_path=paths["correction_log"],
        out=tmp_path / "roadmap_completion_wrong_contract_artifact.json",
    )

    contract_check = next(
        check for check in report.checks if check.requirement_id == "external_contract_readiness_reviewed"
    )
    missing_paths = next(
        evidence
        for evidence in contract_check.evidence
        if evidence.startswith("missing_contract_compatibility_artifact_paths=")
    )
    assert contract_check.status == "fail"
    assert expected_path in missing_paths
    assert "external_contract_readiness_reviewed" in report.blockers


