    stale_scorecard.pop("input_artifact_diagnostics", None)
    stale_scorecard["runtime_proxy_metrics"].pop("input_artifact_coverage_rate", None)
    stale_scorecard["runtime_proxy_metrics"].pop("missing_input_artifact_count", None)
