def test_build_evidence_grounding_roadmap_completion_audit_guides_existing_workspace_correction_log(
    tmp_path,
):
    run_root = tmp_path / "storage" / "artifacts"
    run_root.mkdir(parents=True)
    correction_log = tmp_path / "storage" / "claim_evidence_corrections.jsonl"
    correction_log.write_text(
        json.dumps(
            {
                "paper_id": "paper-1",
                "run_id": "run-1",
                "claim_id": "c1",
                "field_path": "claims[0].text",
                "before_claim_text": "Treatment proves broad benefit.",
                "after_claim_text": "Treatment improved survival in the measured cohort.",
                "before_evidence_refs": [{"page": 1, "quote": "Broad benefit."}],
                "after_evidence_refs": [{"page": 2, "quote": "Treatment improved survival."}],
                "reason_codes": ["OVERSTATED_RESULT"],
                "reviewer_id": "reviewer-1",
                "parser_version": "",
                "llm_provider": "",
                "llm_model": "",
                "llm_model_version": "",
                "prompt_version": "",
                "reader_profile_version": "",
                "created_at": datetime.now(timezone.utc).isoformat(),
                "accepted_for_eval": True,
            }
        )
        + "\n",
        encoding="utf-8",
    )
    out = tmp_path / "roadmap_completion_existing_correction_log.json"

    report = build_evidence_grounding_roadmap_completion_audit_report(
        run_root=run_root,
        out=out,
    )

    inventory_check = next(
        item for item in report.checks if item.requirement_id == "workspace_evidence_inventory_ready"
    )
    assert "workspace_structured_correction_evidence_count=1" in inventory_check.evidence
    assert "workspace_replayable_correction_evidence_count=0" in inventory_check.evidence
    assert "workspace_nonreplayable_correction_evidence_count=1" in inventory_check.evidence
    assert f"workspace_structured_correction_evidence_paths_sample={correction_log.resolve()}" in inventory_check.evidence
    check = next(item for item in report.checks if item.requirement_id == "structured_correction_log")
    assert check.status == "fail"
    assert report.input_paths["correction_log_path"] == str(correction_log.resolve())
    assert "correction_log_path_selected_from_workspace" in report.warnings
    assert f"correction_evidence_path={correction_log.resolve()}" in check.evidence
    assert "correction_evidence_kind=raw_correction_jsonl" in check.evidence
    assert "valid_count=0" in check.evidence
    assert "invalid_count=1" in check.evidence
    assert "source_record_count=1" in check.evidence
    assert "source_valid_record_count=0" in check.evidence
    assert "replayable_candidate_count=0" in check.evidence
    assert "source_nonreplayable_valid_record_count=0" in check.evidence
    assert "source_invalid_record_count=1" in check.evidence
    assert "repair_target_count=1" in check.evidence
    assert "source_reason_code_counts=OVERSTATED_RESULT:1" in check.evidence
    assert "source_invalid_record_lines=1" in check.evidence
    assert "source_invalid_record_details=line_1:Value error, accepted_for_eval requires parser_version" in check.evidence
    assert (
        "source_invalid_record_missing_replay_fields="
        "line_1:parser_version,llm_provider,llm_model,llm_model_version,prompt_version,reader_profile_version"
        in check.evidence
    )
    assert (
        "source_invalid_record_repair_targets=line_1:paper_id=paper-1,run_id=run-1,claim_id=c1"
        in check.evidence
    )
    export_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "structured_correction_log"
        and item.action.startswith("Export a claim/evidence correction repair plan")
    )
    assert export_action.requires_human_review is False
    assert export_action.command_hint is not None
    assert f"--log-path .../{correction_log.name}" in export_action.command_hint
    assert "--out .../claim_evidence_correction_repair_plan.json" in export_action.command_hint
    assert str(correction_log.resolve()) not in export_action.command_hint
    assert "export_claim_evidence_correction_repair_plan.py" in export_action.command_hint
    assert "<claim_evidence_correction_repair_plan.json>" not in export_action.command_hint
    correction_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "structured_correction_log"
        and item.action.startswith("Repair the listed claim/evidence correction log records")
    )
    assert "Repair the listed claim/evidence correction log records" in correction_action.action
    assert "source records: 1" in correction_action.action
    assert "repair targets: 1" in correction_action.action
    assert "reason codes: OVERSTATED_RESULT:1" in correction_action.action
    assert "1 invalid accepted record" in correction_action.action
    assert "line_1:paper_id=paper-1,run_id=run-1,claim_id=c1" in correction_action.action
    assert (
        "line_1:parser_version,llm_provider,llm_model,llm_model_version,prompt_version,reader_profile_version"
        in correction_action.action
    )
    assert correction_action.requires_human_review is True
    assert correction_action.command_hint is None


