def test_build_evidence_grounding_roadmap_completion_audit_recognizes_repair_plan_as_noncanonical_handoff(
    tmp_path,
):
    paths = _write_standalone_roadmap_completion_ready_paths(tmp_path)
    repair_plan = tmp_path / "claim_evidence_correction_repair_plan.json"
    payload = _claim_evidence_correction_repair_plan_payload()
    payload["source_correction_log_path"] = str(tmp_path / "claim_evidence_corrections.jsonl")
    repair_plan.write_text(json.dumps(payload), encoding="utf-8")

    report = build_evidence_grounding_roadmap_completion_audit_report(
        comparison_suite_path=paths["comparison_suite"],
        threshold_calibration_report_path=paths["package_threshold_calibration"],
        threshold_adoption_review_path=paths["package_threshold_adoption"],
        contract_readiness_report_path=paths["package_contract_readiness"],
        gold_release_package_path=paths["gold_release_package"],
        correction_log_path=repair_plan,
        out=tmp_path / "standalone_repair_plan_correction_handoff.json",
    )

    check = next(item for item in report.checks if item.requirement_id == "structured_correction_log")
    assert check.status == "fail"
    assert "correction_evidence_kind=claim_evidence_correction_repair_plan.v1" in check.evidence
    assert "correction_evidence_posture=review_gate_artifact_non_canonical" in check.evidence
    assert f"source_correction_log_path={payload['source_correction_log_path']}" in check.evidence
    assert "valid_count=0" in check.evidence
    assert "invalid_count=1" in check.evidence
    assert "source_record_count=1" in check.evidence
    assert "source_valid_record_count=0" in check.evidence
    assert "source_invalid_record_count=1" in check.evidence
    assert "repair_target_count=1" in check.evidence
    assert "source_reason_code_counts=OVERSTATED_RESULT:1" in check.evidence
    assert "source_invalid_record_lines=1" in check.evidence
    assert "source_invalid_record_details=line_1:parser_version: accepted_for_eval requires parser_version" in check.evidence
    assert (
        "source_invalid_record_missing_replay_fields="
        "line_1:parser_version,llm_provider,llm_model,llm_model_version,prompt_version,reader_profile_version"
        in check.evidence
    )
    assert (
        "source_invalid_record_repair_targets="
        "line_1:correction_id=correction-1,paper_id=paper-1,run_id=run-1,claim_id=c1"
        in check.evidence
    )
    assert (
        "source_invalid_record_available_replay_context="
        "line_1:run_meta.inference_lanes.clinical_extraction.provider_model=gpt-test,"
        "run_meta.inference_lanes.clinical_extraction.provider_name=openai"
        in check.evidence
    )
    structured_actions = [
        item for item in report.next_actions if item.requirement_id == "structured_correction_log"
    ]
    export_template_action = next(
        item
        for item in structured_actions
        if item.action.startswith("Export a claim/evidence correction repair patch template")
    )
    assert export_template_action.requires_human_review is False
    assert export_template_action.command_hint is not None
    assert (
        "export_claim_evidence_correction_repair_patch_template.py"
        in export_template_action.command_hint
    )
    assert "--repair-plan .../claim_evidence_correction_repair_plan.json" in (
        export_template_action.command_hint
    )
    assert "--out .../claim_evidence_correction_repair_patch_template.json" in (
        export_template_action.command_hint
    )
    assert "<claim_evidence_correction_repair_patch_template.json>" not in (
        export_template_action.command_hint
    )
    assert "--require-replayable" not in export_template_action.command_hint
    assert payload["source_correction_log_path"] not in export_template_action.command_hint
    assert f"repair plan: .../{repair_plan.name}" in export_template_action.action
    assert str(repair_plan) not in export_template_action.action

    fill_action = next(
        item
        for item in structured_actions
        if item.action.startswith("Fill the claim/evidence correction repair patch template")
    )
    assert fill_action.requires_human_review is True
    assert fill_action.command_hint is None
    assert str(repair_plan) not in fill_action.action
    assert payload["source_correction_log_path"] not in fill_action.action
    assert "source records: 1" in fill_action.action
    assert "repair targets: 1" in fill_action.action
    assert "reason codes: OVERSTATED_RESULT:1" in fill_action.action
    assert (
        "available run context: "
        "line_1:run_meta.inference_lanes.clinical_extraction.provider_model=gpt-test,"
        "run_meta.inference_lanes.clinical_extraction.provider_name=openai"
        in fill_action.action
    )

    draft_action = next(
        item
        for item in structured_actions
        if item.action.startswith("Draft a repaired claim/evidence correction JSONL")
    )
    assert draft_action.requires_human_review is False
    assert draft_action.command_hint is not None
    assert "draft_claim_evidence_correction_repaired_log.py" in draft_action.command_hint
    assert (
        "--patch-template <claim_evidence_correction_repair_patch_template_filled.json>"
        in draft_action.command_hint
    )
    assert "--out-log <repaired_claim_evidence_corrections.jsonl>" in draft_action.command_hint
    assert (
        "--summary-out <claim_evidence_correction_repaired_log_draft.json>"
        in draft_action.command_hint
    )

    export_candidates_action = next(
        item
        for item in structured_actions
        if item.action.startswith("Export replayable claim/evidence eval candidates")
    )
    assert export_candidates_action.requires_human_review is False
    assert export_candidates_action.command_hint is not None
    assert "export_claim_evidence_eval_candidates.py" in export_candidates_action.command_hint
    assert "--log-path <repaired_claim_evidence_corrections.jsonl>" in (
        export_candidates_action.command_hint
    )
    assert "--require-replayable" in export_candidates_action.command_hint
    assert "structured_correction_log" in report.blockers
    compatibility = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[tmp_path / "standalone_repair_plan_correction_handoff.json"],
    )
    assert compatibility.fail_count == 0


