def test_build_evidence_grounding_roadmap_completion_audit_discovers_workspace_repair_patch_review_chain(
    tmp_path,
):
    paths = _write_standalone_roadmap_completion_ready_paths(tmp_path)
    storage_root = tmp_path / "storage"
    goldset_root = tmp_path / "goldset"
    run_root = tmp_path / "runs"
    storage_root.mkdir()
    goldset_root.mkdir()
    run_root.mkdir()
    correction_log = storage_root / "claim_evidence_corrections.jsonl"
    correction_log.write_text("{\"accepted_for_eval\": true}\n", encoding="utf-8")
    repair_plan = storage_root / "claim_evidence_correction_repair_plan.json"
    repair_payload = _claim_evidence_correction_repair_plan_payload()
    repair_payload["source_correction_log_path"] = str(correction_log.resolve())
    repair_plan.write_text(json.dumps(repair_payload), encoding="utf-8")
    repair_patch_template = storage_root / "claim_evidence_correction_repair_patch_template.json"
    template_payload = _claim_evidence_correction_repair_patch_template_payload()
    template_payload["source_repair_plan_path"] = str(repair_plan.resolve())
    template_payload["source_correction_log_path"] = str(correction_log.resolve())
    repair_patch_template.write_text(json.dumps(template_payload), encoding="utf-8")
    fill_readiness = storage_root / "claim_evidence_correction_repair_patch_template_fill_readiness.json"
    fill_tasks = storage_root / "claim_evidence_correction_repair_patch_template_fill_tasks.json"
    reviewed_csv = storage_root / "claim_evidence_correction_repair_patch_template_fill_tasks_reviewed.csv"
    fill_review_status = storage_root / "claim_evidence_correction_repair_patch_template_fill_review_status.json"
    open_csv = storage_root / "claim_evidence_correction_repair_patch_template_fill_tasks_reviewed_open.csv"
    open_record_csv = storage_root / "claim_evidence_correction_repair_patch_template_fill_tasks_reviewed_open_records.csv"
    annotated_csv = storage_root / "claim_evidence_correction_repair_patch_template_fill_tasks_reviewed_annotated.csv"
    build_evidence_grounding_patch_template_fill_readiness_report(
        patch_template_path=repair_patch_template,
        out=fill_readiness,
    )
    build_evidence_grounding_patch_template_fill_task_export(
        fill_readiness_path=fill_readiness,
        out=fill_tasks,
    )
    _write_reviewed_fill_task_csv(
        task_export_path=fill_tasks,
        out=reviewed_csv,
        values_by_field={"llm_provider": "provider-reviewed"},
    )
    build_evidence_grounding_patch_template_fill_review_status_report(
        task_export_path=fill_tasks,
        reviewed_csv_path=reviewed_csv,
        annotated_csv_path=annotated_csv,
        open_csv_path=open_csv,
        open_record_csv_path=open_record_csv,
        out=fill_review_status,
    )

    report = build_evidence_grounding_roadmap_completion_audit_report(
        comparison_suite_path=paths["comparison_suite"],
        threshold_calibration_report_path=paths["package_threshold_calibration"],
        threshold_adoption_review_path=paths["package_threshold_adoption"],
        contract_readiness_report_path=paths["package_contract_readiness"],
        gold_release_package_path=paths["gold_release_package"],
        correction_log_path=repair_plan,
        goldset_root=goldset_root,
        run_root=run_root,
        out=tmp_path / "roadmap_workspace_repair_patch_chain.json",
    )

    assert "correction_repair_patch_template_path_selected_from_workspace" in report.warnings
    structured_check = next(
        check for check in report.checks if check.requirement_id == "structured_correction_log"
    )
    assert "correction_evidence_kind=claim_evidence_correction_repair_plan.v1" in (
        structured_check.evidence
    )
    assert f"claim_evidence_correction_repair_patch_template_path={repair_patch_template.resolve()}" in (
        structured_check.evidence
    )
    assert (
        f"claim_evidence_correction_repair_patch_template_fill_readiness_path={fill_readiness.resolve()}"
        in structured_check.evidence
    )
    assert (
        f"claim_evidence_correction_repair_patch_template_fill_task_export_path={fill_tasks.resolve()}"
        in structured_check.evidence
    )
    assert (
        f"claim_evidence_correction_repair_patch_template_fill_review_status_path={fill_review_status.resolve()}"
        in structured_check.evidence
    )
    assert report.human_review_open_csv_row_count > 0
    structured_actions = [
        action for action in report.next_actions if action.requirement_id == "structured_correction_log"
    ]
    assert len(structured_actions) == 2
    assert structured_actions[0].action == (
        "Prefill the claim/evidence correction repair patch template from available suggested values before finishing human review."
    )
    assert structured_actions[0].requires_human_review is False
    assert "prefill_evidence_grounding_patch_template_from_suggestions.py" in (
        structured_actions[0].command_hint or ""
    )
    assert structured_actions[1].requires_human_review is True
    assert structured_actions[1].command_hint is not None
    assert "audit_evidence_grounding_patch_template_fill_task_reviews.py" in (
        structured_actions[1].command_hint
    )
    assert not any(
        action.action.startswith("Export a claim/evidence correction repair patch template")
        for action in structured_actions
    )
    assert not any(
        action.action.startswith("Audit the claim/evidence correction repair patch template fill readiness")
        for action in structured_actions
    )
    compatibility = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[tmp_path / "roadmap_workspace_repair_patch_chain.json"],
    )
    assert compatibility.fail_count == 0


