def test_build_evidence_grounding_roadmap_completion_audit_accepts_default_correction_export_cli_output(
    tmp_path,
):
    paths = _write_standalone_roadmap_completion_ready_paths(tmp_path)
    correction_log = tmp_path / "claim_evidence_corrections.jsonl"
    correction_export = tmp_path / "claim_evidence_eval_candidates.json"
    correction_log.write_text(
        json.dumps(
            {
                "paper_id": "paper-1",
                "run_id": "run-1",
                "claim_id": "c1",
                "field_path": "claims[0].text",
                "before_claim_text": "Treatment proves broad benefit.",
                "after_claim_text": "Treatment improved survival in the measured cohort.",
                "before_evidence_refs": [{"page": 2, "quote": "Treatment improved survival."}],
                "after_evidence_refs": [{"page": 2, "quote": "Treatment improved survival."}],
                "reason_codes": ["OVERSTATED_RESULT"],
                "reviewer_id": "reviewer-1",
                "parser_version": "parser-v2",
                "llm_provider": "local",
                "llm_model": "reader-model",
                "llm_model_version": "reader-model-2026-05-22",
                "prompt_version": "grounding-prompt-v2",
                "reader_profile_version": "reader-profile-v2",
                "created_at": datetime.now(timezone.utc).isoformat(),
                "accepted_for_eval": True,
            }
        )
        + "\n",
        encoding="utf-8",
    )
    result = subprocess.run(
        [
            sys.executable,
            "scripts/eval/export_claim_evidence_eval_candidates.py",
            "--log-path",
            str(correction_log),
            "--out",
            str(correction_export),
        ],
        cwd=Path(__file__).resolve().parents[1],
        text=True,
        capture_output=True,
        check=False,
    )
    assert result.returncode == 0, result.stderr

    report = build_evidence_grounding_roadmap_completion_audit_report(
        comparison_suite_path=paths["comparison_suite"],
        threshold_calibration_report_path=paths["package_threshold_calibration"],
        threshold_adoption_review_path=paths["package_threshold_adoption"],
        contract_readiness_report_path=paths["package_contract_readiness"],
        gold_release_package_path=paths["gold_release_package"],
        correction_log_path=correction_export,
        out=tmp_path / "standalone_default_correction_export_cli.json",
    )

    check = next(item for item in report.checks if item.requirement_id == "structured_correction_log")
    assert check.status == "pass"
    assert "valid_count=1" in check.evidence
    assert "invalid_count=0" in check.evidence


def test_build_evidence_grounding_roadmap_completion_audit_rejects_failed_scorecard_readiness(tmp_path):
    paths = _write_standalone_roadmap_completion_ready_paths(tmp_path)
    candidate_payload = json.loads(paths["candidate"].read_text(encoding="utf-8"))
    candidate_payload["scorecard_readiness_pass_count"] = 0
    candidate_payload["scorecard_readiness_warn_count"] = 1
    candidate_payload["scorecard_readiness_fail_count"] = 1
    candidate_payload["scorecard_not_ready_candidate_ids"] = ["candidate", "candidate-followup"]
    candidate_payload["scorecards"][0]["scorecard"]["readiness_status"] = "fail"
    candidate_payload["scorecards"][0]["scorecard"]["reason_codes"] = [
        "coverage_low_grounded_evidence_ratio",
        "coverage_missing_major_topic_signals",
        "gold_metrics_scored",
    ]
    candidate_payload["scorecards"][0]["scorecard"]["runtime_proxy_metrics"].update(
        {
            "page_coverage_ratio": {
                "value": 0.1,
                "status": "available",
                "source": "claimset_coverage.metrics.page_coverage_ratio",
            },
            "missing_topic_signal_count": {
                "value": 3,
                "status": "available",
                "source": "claimset_coverage.metrics.missing_topic_signal_count",
            },
            "duplicate_cluster_count": {
                "value": 1,
                "status": "available",
                "source": "claimset_coverage.metrics.duplicate_cluster_count",
            },
        }
    )
    followup_scorecard = copy.deepcopy(candidate_payload["scorecards"][0])
    followup_scorecard["candidate_id"] = "candidate-followup"
    followup_scorecard["scorecard"]["readiness_status"] = "warn"
    followup_scorecard["scorecard"]["reason_codes"] = [
        "coverage_missing_major_topic_signals",
        "gold_metrics_scored",
    ]
    followup_scorecard["scorecard"]["runtime_proxy_metrics"]["grounded_evidence_ratio"] = {
        "value": 0.62,
        "status": "available",
        "source": "claimset_coverage.metrics.grounded_evidence_ratio",
    }
    followup_scorecard["scorecard"]["runtime_proxy_metrics"]["page_coverage_ratio"] = {
        "value": 0.2,
        "status": "available",
        "source": "claimset_coverage.metrics.page_coverage_ratio",
    }
    followup_scorecard["scorecard"]["runtime_proxy_metrics"]["missing_topic_signal_count"] = {
        "value": 4,
        "status": "available",
        "source": "claimset_coverage.metrics.missing_topic_signal_count",
    }
    followup_scorecard["scorecard"]["runtime_proxy_metrics"]["duplicate_cluster_count"] = {
        "value": 0,
        "status": "available",
        "source": "claimset_coverage.metrics.duplicate_cluster_count",
    }
    candidate_payload["scorecards"].append(followup_scorecard)
    candidate_payload["item_count"] = 2
    paths["candidate"].write_text(json.dumps(candidate_payload), encoding="utf-8")
    out = tmp_path / "standalone_failed_scorecard_readiness.json"

    report = build_evidence_grounding_roadmap_completion_audit_report(
        comparison_suite_path=paths["comparison_suite"],
        threshold_calibration_report_path=paths["package_threshold_calibration"],
        threshold_adoption_review_path=paths["package_threshold_adoption"],
        contract_readiness_report_path=paths["package_contract_readiness"],
        gold_release_package_path=paths["gold_release_package"],
        correction_log_path=paths["correction_log"],
        out=out,
    )

    assert report.roadmap_complete is False
    assert "per_run_and_aggregate_scorecards" in report.blockers
    check = next(item for item in report.checks if item.requirement_id == "per_run_and_aggregate_scorecards")
    assert check.status == "fail"
    assert "candidate_scorecard_readiness_fail_count=1" in check.evidence
    assert "candidate_scorecard_fail_candidate_ids=candidate" in check.evidence
    assert "candidate_scorecard_fail_reason_codes=coverage_low_grounded_evidence_ratio:1,coverage_missing_major_topic_signals:1" in check.evidence
    assert "candidate_scorecard_not_ready_candidate_ids=candidate,candidate-followup" in check.evidence
    assert (
        "candidate_scorecard_not_ready_reason_codes=coverage_low_grounded_evidence_ratio:1,coverage_missing_major_topic_signals:2"
        in check.evidence
    )
    assert (
        "candidate_scorecard_not_ready_proxy_metrics="
        "candidate_id:candidate,grounded_evidence_ratio:0.8,page_coverage_ratio:0.1,"
        "missing_topic_signal_count:3,duplicate_cluster_count:1;"
        "candidate_id:candidate-followup,grounded_evidence_ratio:0.62,page_coverage_ratio:0.2,"
        "missing_topic_signal_count:4,duplicate_cluster_count:0"
        in check.evidence
    )
    assert (
        "candidate_scorecard_fail_proxy_metrics="
        "candidate_id:candidate,grounded_evidence_ratio:0.8,page_coverage_ratio:0.1,"
        "missing_topic_signal_count:3,duplicate_cluster_count:1"
        in check.evidence
    )
    assert (
        "candidate_scorecard_first_not_ready_proxy_metrics="
        "candidate_id:candidate,grounded_evidence_ratio:0.8,page_coverage_ratio:0.1,"
        "missing_topic_signal_count:3,duplicate_cluster_count:1"
        in check.evidence
    )
    assert check.next_actions[0] == (
        "Repair or regenerate failing scorecard source run sidecars before rebuilding scorecards "
        "(candidate fail_count=1 fail_reason_codes=coverage_low_grounded_evidence_ratio:1,coverage_missing_major_topic_signals:1 "
        "reason_codes=coverage_low_grounded_evidence_ratio:1,coverage_missing_major_topic_signals:2 "
        "fail_ids=candidate non_pass_ids=candidate,candidate-followup fail_proxy_metrics=candidate_id:candidate,"
        "grounded_evidence_ratio:0.8,page_coverage_ratio:0.1,missing_topic_signal_count:3,duplicate_cluster_count:1 "
        "proxy_metrics=candidate_id:candidate,grounded_evidence_ratio:0.8,"
        "page_coverage_ratio:0.1,missing_topic_signal_count:3,duplicate_cluster_count:1;"
        "candidate_id:candidate-followup,grounded_evidence_ratio:0.62,page_coverage_ratio:0.2,"
        "missing_topic_signal_count:4,duplicate_cluster_count:0)."
    )
    assert check.next_actions[1] == "Re-run scorecard input backfill after failing source run sidecars are repaired."
    source_repair_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "per_run_and_aggregate_scorecards"
        and item.action.startswith("Repair or regenerate failing scorecard source run sidecars")
    )
    assert source_repair_action.command_hint is not None
    assert "backfill_evidence_grounding_scorecard_inputs.py" in source_repair_action.command_hint
    assert "--benchmark-manifest <baseline_or_candidate_benchmark_manifest.json>" in (
        source_repair_action.command_hint
    )
    assert "--out-run-root <baseline_or_candidate_runs_with_repaired_scorecard_inputs>" in (
        source_repair_action.command_hint
    )
    assert "--out <scorecard_input_backfill.json>" in source_repair_action.command_hint
    assert source_repair_action.requires_human_review is False
    scorecard_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "per_run_and_aggregate_scorecards"
        and item.action.startswith("Re-run scorecard input backfill")
    )
    assert scorecard_action.command_hint is not None
    assert "backfill_evidence_grounding_scorecard_inputs.py" in scorecard_action.command_hint
    assert "--benchmark-manifest <baseline_or_candidate_benchmark_manifest.json>" in scorecard_action.command_hint
    assert "--out-run-root <baseline_or_candidate_runs_with_repaired_scorecard_inputs>" in (
        scorecard_action.command_hint
    )
    assert "--reviewed-fixtures-dir" not in scorecard_action.command_hint
    assert scorecard_action.requires_human_review is False
    assert report.next_actions[0].requirement_id == "per_run_and_aggregate_scorecards"
    assert report.next_actions[0].action.startswith(
        "Repair or regenerate failing scorecard source run sidecars"
    )


