def test_evidence_grounding_roadmap_completion_from_comparison_suite_package_api(tmp_path):
    paths = _write_roadmap_completion_package_inputs(tmp_path)
    calibration_out = tmp_path / "package_threshold_calibration.json"
    threshold_checked_comparison_out = tmp_path / "package_threshold_checked_comparison.json"
    threshold_adoption_out = tmp_path / "package_threshold_adoption.json"
    contract_compatibility_out = tmp_path / "package_contract_compatibility.json"
    contract_readiness_out = tmp_path / "package_contract_readiness.json"
    gold_release_readiness_out = tmp_path / "package_gold_release_readiness.json"
    repair_plan = tmp_path / "claim_evidence_correction_repair_plan.json"
    out = tmp_path / "package_roadmap_completion.json"
    repair_plan.write_text(json.dumps(_claim_evidence_correction_repair_plan_payload()), encoding="utf-8")
    client = TestClient(api_main.app)

    response = client.post(
        "/evidence-grounding/roadmap-completion/audit-from-comparison-suite-package",
        json={
            "comparison_suite_path": str(paths["comparison_suite"]),
            "threshold_calibration_report_out": str(calibration_out),
            "threshold_checked_comparison_report_out": str(threshold_checked_comparison_out),
            "threshold_adoption_review_out": str(threshold_adoption_out),
            "contract_compatibility_report_out": str(contract_compatibility_out),
            "contract_readiness_report_out": str(contract_readiness_out),
            "correction_log_path": str(paths["correction_log"]),
            "migration_plan_path": str(paths["migration"]),
            "backfill_plan_path": str(paths["backfill"]),
            "public_contract_doc_path": str(paths["public_contract"]),
            "gold_release_manifest_paths": [str(path) for path in paths["gold_release_manifests"]],
            "gold_release_readiness_report_out": str(gold_release_readiness_out),
            "threshold_reviewer_approval_reference": "threshold-review-approval-123",
            "allow_production_threshold_ready": True,
            "contract_reviewer_approval_reference": "contract-review-approval-123",
            "allow_external_contract_ready": True,
            "additional_artifact_paths": [str(repair_plan)],
            "out": str(out),
        },
    )

    assert response.status_code == 200
    payload = response.json()
    assert payload["schema_version"] == "evidence_grounding_roadmap_completion_audit.v1"
    assert payload["roadmap_complete"] is False
    assert "fixed_goldset_threshold_adoption_package_ready" in payload["blockers"]
    assert payload["additional_artifact_paths"] == [f".../{repair_plan.name}"]
    assert payload["additional_artifact_count"] == 1
    assert str(repair_plan.resolve()) not in json.dumps(payload)
    _assert_blocked_without_next_action_summary(payload)
    assert calibration_out.exists()
    assert threshold_checked_comparison_out.exists()
    assert gold_release_readiness_out.exists()
    assert threshold_adoption_out.exists()
    assert contract_compatibility_out.exists()
    assert contract_readiness_out.exists()
    assert out.exists()
    persisted_payload = json.loads(out.read_text(encoding="utf-8"))
    assert persisted_payload["additional_artifact_paths"] == [str(repair_plan.resolve())]
    assert persisted_payload["additional_artifact_count"] == 1


