def test_threshold_package_threshold_adoption_actions_include_package_rebuild_steps(tmp_path):
    threshold_package = _write_ready_threshold_adoption_package(tmp_path)
    package_payload = json.loads(threshold_package.read_text(encoding="utf-8"))
    comparison_suite_package_path = Path(package_payload["comparison_suite_package_path"])
    suite_package_payload = json.loads(comparison_suite_package_path.read_text(encoding="utf-8"))
    candidate_run_package_path = Path(suite_package_payload["candidate_run_package_path"])
    candidate_run_package_payload = json.loads(candidate_run_package_path.read_text(encoding="utf-8"))
    candidate_manifest_package_path = Path(candidate_run_package_payload["benchmark_manifest_package_path"])
    calibration_path = Path(package_payload["calibration_report_path"])
    calibration_payload = json.loads(calibration_path.read_text(encoding="utf-8"))
    for recommendation in calibration_payload["recommendations"]:
        if recommendation["name"] == "overstatement_rate":
            recommendation["status"] = "not_available"
            recommendation["observed_values"] = []
            recommendation["available_count"] = 0
            recommendation["recommended_threshold"] = None
            recommendation["detail"] = "No loaded report had an available numeric value for this metric."
    calibration_path.write_text(json.dumps(calibration_payload), encoding="utf-8")
    for review_path_raw in package_payload["threshold_adoption_review_paths"]:
        review_path = Path(review_path_raw)
        review_payload = json.loads(review_path.read_text(encoding="utf-8"))
        review_payload["threshold_metric_values"].pop("gold_scored_metrics.overstatement_rate", None)
        review_payload["production_threshold_ready"] = False
        review_payload["blockers"] = ["p0_threshold_recommendations_available"]
        review_path.write_text(json.dumps(review_payload), encoding="utf-8")

    review_docs = _write_contract_review_docs(tmp_path)
    report = build_evidence_grounding_roadmap_completion_audit_report_from_threshold_adoption_package(
        threshold_adoption_package_path=threshold_package,
        contract_compatibility_report_out=tmp_path / "contract_compatibility.json",
        contract_readiness_report_out=tmp_path / "contract_readiness.json",
        out=tmp_path / "roadmap_threshold_package_missing_threshold_metric.json",
        representative_split="eval",
        migration_plan_path=review_docs["migration"],
        backfill_plan_path=review_docs["backfill"],
        public_contract_doc_path=review_docs["public_contract"],
        contract_reviewer_approval_reference="contract-review-approval-123",
        allow_external_contract_ready=True,
        gold_release_package_path=tmp_path / "gold_release_package.json",
        correction_log_path=tmp_path / "claim_evidence_corrections.jsonl",
    )

    threshold_check = next(
        check for check in report.checks if check.requirement_id == "production_threshold_adoption_reviewed"
    )
    assert threshold_check.status == "fail"
    assert f"candidate_benchmark_manifest_package_path={candidate_manifest_package_path.resolve()}" in (
        threshold_check.evidence
    )
    assert f"gold_release_package_path={(tmp_path / 'gold_release_package.json').resolve()}" in (
        threshold_check.evidence
    )
    assert "missing_p0_calibration_metrics=overstatement_rate" in threshold_check.evidence
    assert "missing_p0_adoption_metrics=overstatement_rate" in threshold_check.evidence
    manifest_package_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "production_threshold_adoption_reviewed"
        and item.action
        == "Build a reviewed-fixture candidate benchmark manifest package that points at the reviewed-fixture run root."
    )
    assert manifest_package_action.requires_human_review is False
    assert manifest_package_action.command_hint is not None
    assert "build_evidence_grounding_benchmark_manifests_from_release_package.py" in (
        manifest_package_action.command_hint
    )
    assert f"--release-package .../{(tmp_path / 'gold_release_package.json').name}" in (
        manifest_package_action.command_hint
    )
    assert str((tmp_path / "gold_release_package.json").resolve()) not in manifest_package_action.command_hint
    assert "--run-root <candidate_runs_with_reviewed_fixtures>" in manifest_package_action.command_hint
    assert "--run-dir-map <candidate_reviewed_fixture_run_dir_map.json>" in (
        manifest_package_action.command_hint
    )
    run_package_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "production_threshold_adoption_reviewed"
        and item.action
        == "Build a reviewed-fixture candidate benchmark run package before re-running threshold calibration."
    )
    assert run_package_action.requires_human_review is False
    assert run_package_action.command_hint is not None
    assert "run_evidence_grounding_benchmark_package.py" in run_package_action.command_hint
    assert "--manifest-package <candidate_benchmark_manifest_package_with_reviewed_fixtures.json>" in (
        run_package_action.command_hint
    )
    comparison_package_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "production_threshold_adoption_reviewed"
        and item.action
        == "Re-run the scorecard-aware fixed-goldset comparison suite package after reviewed threshold evidence is available."
    )
    assert comparison_package_action.requires_human_review is False
    assert comparison_package_action.command_hint is not None
    assert "run_evidence_grounding_fixed_goldset_comparison_from_benchmark_run_packages.py" in (
        comparison_package_action.command_hint
    )
    recalibration_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "production_threshold_adoption_reviewed"
        and item.action
        == "Re-run threshold calibration from real fixed-goldset benchmark evidence after every P0 grounding metric is available."
    )
    assert recalibration_action.command_hint is not None
    assert "review_evidence_grounding_threshold_adoption_from_comparison_suite_package.py" in (
        recalibration_action.command_hint
    )
    assert "--out-dir .../threshold_adoption_review_with_reviewed_fixtures" in (
        recalibration_action.command_hint
    )
    assert "--calibration-report-out .../threshold_calibration.json" in recalibration_action.command_hint
    assert "--out .../threshold_adoption_package_without_production_opt_in.json" in (
        recalibration_action.command_hint
    )
    assert "<threshold_adoption_out_dir>" not in recalibration_action.command_hint
    assert "<threshold_calibration.json>" not in recalibration_action.command_hint
    adoption_review_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "production_threshold_adoption_reviewed"
        and item.action == "Run threshold-adoption review with explicit human approval and production-threshold opt-in."
    )
    assert adoption_review_action.command_hint is not None
    assert "--comparison-suite-package <comparison_suite_package_with_reviewed_fixtures.json>" in (
        adoption_review_action.command_hint
    )
    assert "--reviewer-approval-reference <approval_ref>" in adoption_review_action.command_hint
    assert "--allow-production-threshold-ready" in adoption_review_action.command_hint
    assert "--out .../threshold_adoption_package.json" in adoption_review_action.command_hint


def test_threshold_adoption_actions_use_incomplete_p0_summary_before_reviewed_fixture_lane(tmp_path):
    threshold_package = _write_ready_threshold_adoption_package(tmp_path)
    package_payload = json.loads(threshold_package.read_text(encoding="utf-8"))
    calibration_path = Path(package_payload["calibration_report_path"])
    calibration_payload = json.loads(calibration_path.read_text(encoding="utf-8"))
    for recommendation in calibration_payload["recommendations"]:
        if recommendation["name"] == "overstatement_rate":
            recommendation["status"] = "not_available"
            recommendation["observed_values"] = []
            recommendation["available_count"] = 0
            recommendation["recommended_threshold"] = None
            recommendation["detail"] = "No loaded report had an available numeric value for this metric."
    calibration_path.write_text(json.dumps(calibration_payload), encoding="utf-8")
    for review_path_raw in package_payload["threshold_adoption_review_paths"]:
        review_path = Path(review_path_raw)
        review_payload = json.loads(review_path.read_text(encoding="utf-8"))
        review_payload["threshold_metric_values"].pop("gold_scored_metrics.overstatement_rate", None)
        review_payload["production_threshold_ready"] = False
        review_payload["blockers"] = ["p0_threshold_recommendations_available"]
        review_path.write_text(json.dumps(review_payload), encoding="utf-8")

    packet_run_dir = tmp_path / "runs" / "paper-1" / "run-1"
    _write_p0_overstatement_packet_source_run(packet_run_dir)
    packet_report = tmp_path / "p0_packet_source_benchmark.json"
    packet_report.write_text(
        json.dumps(_benchmark_payload(benchmark_id="bench-seed", goldset_split="seed", include_scorecard=True)),
        encoding="utf-8",
    )
    packet = build_evidence_grounding_p0_overstatement_review_packet_from_benchmark_reports([packet_report])
    packet_out = tmp_path / "packet.json"
    packet_out.write_text(packet.model_dump_json(indent=2), encoding="utf-8")
    packet_markdown = tmp_path / "packet.md"
    packet_markdown.write_text("# P0 packet\n", encoding="utf-8")
    summary = build_evidence_grounding_p0_overstatement_review_summary(packet_path=packet_out)
    open_issue_csv = tmp_path / "open_issues.csv"
    write_evidence_grounding_p0_overstatement_review_summary_open_issue_csv(summary, open_issue_csv)
    summary_out = tmp_path / "p0_overstatement_review_summary.json"
    summary_out.write_text(summary.model_dump_json(indent=2), encoding="utf-8")

    review_docs = _write_contract_review_docs(tmp_path)
    report = build_evidence_grounding_roadmap_completion_audit_report_from_threshold_adoption_package(
        threshold_adoption_package_path=threshold_package,
        contract_compatibility_report_out=tmp_path / "contract_compatibility.json",
        contract_readiness_report_out=tmp_path / "contract_readiness.json",
        out=tmp_path / "roadmap_threshold_package_missing_threshold_metric_with_p0_summary.json",
        representative_split="eval",
        migration_plan_path=review_docs["migration"],
        backfill_plan_path=review_docs["backfill"],
        public_contract_doc_path=review_docs["public_contract"],
        contract_reviewer_approval_reference="contract-review-approval-123",
        allow_external_contract_ready=True,
        gold_release_package_path=tmp_path / "gold_release_package.json",
        correction_log_path=tmp_path / "claim_evidence_corrections.jsonl",
        additional_artifact_paths=[summary_out],
    )

    threshold_check = next(
        check for check in report.checks if check.requirement_id == "production_threshold_adoption_reviewed"
    )
    assert threshold_check.status == "fail"
    assert f"p0_overstatement_review_summary_path={summary_out.resolve()}" in threshold_check.evidence
    assert "p0_overstatement_review_summary_ready_for_p0_metric=false" in threshold_check.evidence
    threshold_actions = [
        item.action
        for item in report.next_actions
        if item.requirement_id == "production_threshold_adoption_reviewed"
    ]
    assert any(
        action.startswith("Complete the P0 overstatement review packet decisions and rationales")
        and "open issue CSV: " in action
        and "then re-summarize it before threshold recalibration." in action
        for action in threshold_actions
    )
    assert not any("reviewed claim/evidence fixtures" in action for action in threshold_actions)
    complete_summary_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "production_threshold_adoption_reviewed"
        and item.action.startswith("Complete the P0 overstatement review packet decisions and rationales")
    )
    assert complete_summary_action.command_hint is not None
    assert "summarize_p0_overstatement_review_packet.py" in complete_summary_action.command_hint
    assert f"--packet .../{packet_out.name}" in complete_summary_action.command_hint
    assert "--reviewed-csv <p0_overstatement_review_rows_reviewed.csv>" in complete_summary_action.command_hint
    assert f"--out .../{summary_out.name}" in complete_summary_action.command_hint
    assert f"--open-issue-csv-out .../{open_issue_csv.name}" in complete_summary_action.command_hint
    assert "review_evidence_grounding_threshold_adoption" not in complete_summary_action.command_hint
    assert str(packet_out.resolve()) not in complete_summary_action.command_hint
    assert str(summary_out.resolve()) not in complete_summary_action.command_hint
    assert str(open_issue_csv.resolve()) not in complete_summary_action.command_hint


def test_build_evidence_grounding_roadmap_completion_audit_requires_gold_release_readiness(tmp_path):
    out = tmp_path / "roadmap_completion.json"

    report = build_evidence_grounding_roadmap_completion_audit_report(out=out)

    check = next(item for item in report.checks if item.requirement_id == "fixed_goldset_release_readiness")
    assert check.status == "fail"
    assert "gold_release_readiness_loaded=false" in check.evidence
    assert check.next_actions == [
        "Curate ready paper_understanding_gold.v1 records and publish seed/eval/holdout manifests.",
        "Run the gold release-readiness audit and provide the resulting paper_understanding_gold_release_readiness.v1 report.",
    ]
    candidate_config_check = next(
        item for item in report.checks if item.requirement_id == "candidate_configuration_lineage"
    )
    assert "candidate_benchmark_loaded=false" in candidate_config_check.evidence
    p0_metrics_check = next(item for item in report.checks if item.requirement_id == "p0_metrics_reported")
    assert "candidate_benchmark_loaded=false" in p0_metrics_check.evidence
    p0_gate_check = next(item for item in report.checks if item.requirement_id == "p0_regression_gate")
    assert "comparison_report_loaded=false" in p0_gate_check.evidence
    structured_check = next(item for item in report.checks if item.requirement_id == "structured_correction_log")
    assert "correction_evidence_loaded=false" in structured_check.evidence
    assert "correction_evidence_kind=missing" in structured_check.evidence
    assert "correction_evidence_posture=unsafe_or_unknown" in structured_check.evidence
    stage_check = next(item for item in report.checks if item.requirement_id == "stage_failure_attribution")
    assert "candidate_benchmark_loaded=false" in stage_check.evidence
    first_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "fixed_goldset_release_readiness"
        and item.action == "Curate ready paper_understanding_gold.v1 records and publish seed/eval/holdout manifests."
    )
    assert first_action.phase == "gold_curation_and_release"
    assert first_action.requires_human_review is True
    assert "package_paper_understanding_gold_reviewer_handoff.py" in first_action.command_hint
    release_readiness_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "fixed_goldset_release_readiness"
        and item.action
        == "Run the gold release-readiness audit and provide the resulting paper_understanding_gold_release_readiness.v1 report."
    )
    assert release_readiness_action.command_hint is not None
    assert "audit_paper_understanding_gold_release_readiness.py" in release_readiness_action.command_hint
    assert release_readiness_action.requires_human_review is False
    assert report.next_action_phase_counts["gold_curation_and_release"] >= 2
    assert report.human_review_next_action_count >= 1
    assert "fixed_goldset_release_readiness" in report.blockers
    assert report.roadmap_complete is False


