def test_build_evidence_grounding_roadmap_completion_audit_names_failed_contract_schema_coverage(
    tmp_path,
):
    candidate_path = tmp_path / "candidate_benchmark.json"
    scorecard_backfill_path = tmp_path / "scorecard_input_backfill_no_scorecards.json"
    compatibility_path = tmp_path / "compatibility.json"
    contract_readiness_path = tmp_path / "contract_readiness.json"
    migration_plan = tmp_path / "migration.md"
    backfill_plan = tmp_path / "backfill.md"
    public_contract_doc = tmp_path / "public-contract.md"
    out = tmp_path / "roadmap_completion.json"
    candidate_path.write_text(
        json.dumps(_benchmark_payload(benchmark_id="candidate", claim_precision=0.9)),
        encoding="utf-8",
    )
    stale_backfill = _scorecard_input_backfill_payload()
    stale_backfill["scorecard_pass_count"] = 0
    stale_backfill["items"][0]["generated_artifacts"] = [
        artifact
        for artifact in stale_backfill["items"][0]["generated_artifacts"]
        if artifact != "evidence_grounding_scorecard.json"
    ]
    stale_backfill["items"][0]["scorecard_readiness_status"] = None
    scorecard_backfill_path.write_text(json.dumps(stale_backfill), encoding="utf-8")
    migration_plan.write_text("Migration review complete.", encoding="utf-8")
    backfill_plan.write_text("Backfill review complete.", encoding="utf-8")
    public_contract_doc.write_text("Public contract reviewed.", encoding="utf-8")
    build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[candidate_path, scorecard_backfill_path],
        out=compatibility_path,
    )
    build_evidence_grounding_contract_readiness_report(
        compatibility_report_path=compatibility_path,
        migration_plan_path=migration_plan,
        backfill_plan_path=backfill_plan,
        public_contract_doc_path=public_contract_doc,
        reviewer_approval_reference="contract-review-approval-123",
        allow_external_contract_ready=True,
        out=contract_readiness_path,
    )

    report = build_evidence_grounding_roadmap_completion_audit_report(
        contract_readiness_report_path=contract_readiness_path,
        out=out,
    )

    contract_check = next(
        check for check in report.checks if check.requirement_id == "external_contract_readiness_reviewed"
    )
    missing_schemas = next(
        evidence for evidence in contract_check.evidence if evidence.startswith("missing_contract_schema_versions=")
    )
    assert contract_check.status == "fail"
    assert any(
        item.startswith("contract_compatibility_observed_schema_versions=")
        and "evidence_grounding_scorecard_input_backfill.v1" in item
        for item in contract_check.evidence
    )
    assert "failed_contract_schema_versions=evidence_grounding_scorecard_input_backfill.v1" in (
        contract_check.evidence
    )
    assert any(
        item.startswith("failed_contract_schema_findings=")
        and "evidence_grounding_scorecard_input_backfill.v1:scorecard_input_backfill_scorecard_coverage_mismatch"
        in item
        for item in contract_check.evidence
    )
    assert "evidence_grounding_scorecard_input_backfill.v1" not in missing_schemas
    contract_audit_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "external_contract_readiness_reviewed"
        and item.action.startswith("Regenerate external-contract scorecard input backfill artifacts")
    )
    assert "with scorecard generation enabled" in contract_audit_action.action
    assert "--no-scorecards" in contract_audit_action.action
    assert "failing schema versions: evidence_grounding_scorecard_input_backfill.v1" in (
        contract_audit_action.action
    )
    assert "compatibility fail_count: 1" in contract_audit_action.action
    assert (
        "failed schema findings: "
        "evidence_grounding_scorecard_input_backfill.v1:scorecard_input_backfill_scorecard_coverage_mismatch"
        in contract_audit_action.action
    )
    assert contract_audit_action.command_hint is not None
    assert "backfill_evidence_grounding_scorecard_inputs.py" in contract_audit_action.command_hint
    assert "--benchmark-manifest-package <baseline_or_candidate_benchmark_manifest_package.json>" in (
        contract_audit_action.command_hint
    )
    assert "--reviewed-fixtures-dir <goldset/reviews/claim_evidence_eval_candidates/reviewed>" in (
        contract_audit_action.command_hint
    )
    assert "--require-reviewed-fixtures" in contract_audit_action.command_hint
    contract_rerun_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "external_contract_readiness_reviewed"
        and item.action.startswith("Re-run contract compatibility over")
    )
    assert contract_rerun_action.command_hint is not None
    assert "check_evidence_grounding_contract_compatibility.py" in contract_rerun_action.command_hint
    assert not any(
        item.requirement_id == "external_contract_readiness_reviewed" and item.requires_human_review
        for item in report.next_actions
    )


def test_build_evidence_grounding_roadmap_completion_audit_splits_external_contract_source_sidecar_repair(
    tmp_path,
):
    candidate_path = tmp_path / "candidate_benchmark.json"
    scorecard_backfill_path = tmp_path / "scorecard_input_backfill_failed_scorecard.json"
    compatibility_path = tmp_path / "compatibility.json"
    contract_readiness_path = tmp_path / "contract_readiness.json"
    migration_plan = tmp_path / "migration.md"
    backfill_plan = tmp_path / "backfill.md"
    public_contract_doc = tmp_path / "public-contract.md"
    out = tmp_path / "roadmap_completion.json"
    candidate_path.write_text(
        json.dumps(_benchmark_payload(benchmark_id="candidate", claim_precision=0.9)),
        encoding="utf-8",
    )
    failed_backfill = _scorecard_input_backfill_payload()
    failed_backfill["scorecard_pass_count"] = 0
    failed_backfill["scorecard_fail_count"] = 1
    failed_backfill["items"][0]["scorecard_readiness_status"] = "fail"
    failed_backfill["items"][0]["scorecard_reason_codes"] = [
        "coverage_low_grounded_evidence_ratio",
        "gold_labels_missing",
    ]
    failed_backfill["warnings"] = ["scorecard_input_backfill_scorecard_failures_present"]
    scorecard_backfill_path.write_text(json.dumps(failed_backfill), encoding="utf-8")
    migration_plan.write_text("Migration review complete.", encoding="utf-8")
    backfill_plan.write_text("Backfill review complete.", encoding="utf-8")
    public_contract_doc.write_text("Public contract reviewed.", encoding="utf-8")
    build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[candidate_path, scorecard_backfill_path],
        out=compatibility_path,
    )
    build_evidence_grounding_contract_readiness_report(
        compatibility_report_path=compatibility_path,
        migration_plan_path=migration_plan,
        backfill_plan_path=backfill_plan,
        public_contract_doc_path=public_contract_doc,
        reviewer_approval_reference="contract-review-approval-123",
        allow_external_contract_ready=True,
        out=contract_readiness_path,
    )

    report = build_evidence_grounding_roadmap_completion_audit_report(
        contract_readiness_report_path=contract_readiness_path,
        out=out,
    )

    source_repair_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "external_contract_readiness_reviewed"
        and item.action.startswith("Repair or regenerate failing external-contract scorecard source run sidecars")
    )
    assert "evidence_grounding_scorecard_input_backfill.v1" in source_repair_action.action
    assert "scorecard_input_backfill_scorecard_failure_details" in source_repair_action.action
    assert "coverage_low_grounded_evidence_ratio" in source_repair_action.action
    assert "gold_labels_missing" in source_repair_action.action
    assert "and attach missing gold/review labels" in source_repair_action.action
    assert source_repair_action.command_hint is not None
    assert "backfill_evidence_grounding_scorecard_inputs.py" in source_repair_action.command_hint
    assert "--benchmark-manifest-package <baseline_or_candidate_benchmark_manifest_package.json>" in (
        source_repair_action.command_hint
    )
    assert "--reviewed-fixtures-dir <goldset/reviews/claim_evidence_eval_candidates/reviewed>" in (
        source_repair_action.command_hint
    )
    assert "--require-reviewed-fixtures" in source_repair_action.command_hint
    assert "--out <scorecard_input_backfill.json>" in source_repair_action.command_hint
    assert source_repair_action.requires_human_review is False
    backfill_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "external_contract_readiness_reviewed"
        and item.action
        == (
            "Re-run scorecard input backfill for external-contract required artifacts after failing "
            "source run sidecars and reviewed fixtures are repaired."
        )
    )
    assert backfill_action.command_hint is not None
    assert "backfill_evidence_grounding_scorecard_inputs.py" in backfill_action.command_hint
    assert "--benchmark-manifest-package <baseline_or_candidate_benchmark_manifest_package.json>" in (
        backfill_action.command_hint
    )
    assert "--reviewed-fixtures-dir <goldset/reviews/claim_evidence_eval_candidates/reviewed>" in (
        backfill_action.command_hint
    )
    assert "--require-reviewed-fixtures" in backfill_action.command_hint
    assert backfill_action.requires_human_review is False
    assert not any(
        item.requirement_id == "external_contract_readiness_reviewed"
        and item.action.startswith("Repair failing required evidence-grounding artifacts")
        for item in report.next_actions
    )
    contract_rerun_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "external_contract_readiness_reviewed"
        and item.action.startswith("Re-run contract compatibility over")
    )
    assert "check_evidence_grounding_contract_compatibility.py" in contract_rerun_action.command_hint


