def test_build_evidence_grounding_roadmap_completion_audit_requires_candidate_config_lineage(tmp_path):
    candidate_path = tmp_path / "candidate_benchmark.json"
    out = tmp_path / "roadmap_completion.json"
    run_dir = tmp_path / "runs" / "paper-1" / "run-1"
    run_dir.mkdir(parents=True)
    (run_dir / "run_meta.json").write_text(
        json.dumps(
            {
                "parser_backend": "fitz_pdfplumber",
                "selected_backend": "local",
                "inference_lanes": {
                    "reader": {
                        "provider_name": "ollama",
                        "provider_model": "llama3:latest",
                    }
                },
                "models_used": {"reader": "llama3:latest"},
                "prompts_snapshot": str(tmp_path / "snapshots" / "profiles.yaml"),
            }
        ),
        encoding="utf-8",
    )
    payload = _benchmark_payload(
        benchmark_id="candidate",
        goldset_id="paper-understanding-seed",
        goldset_split="eval",
        goldset_item_count=1,
        goldset_covered_paper_count=1,
        claim_precision=0.9,
        evidence_support_precision=0.9,
        locator_precision=0.9,
        unsupported_claim_rate=0.01,
        overstatement_rate=0.01,
        limitation_recall=0.9,
        method_result_confusion_rate=0.01,
        include_scorecard=True,
    )
    payload["scorecards"][0]["run_dir"] = str(run_dir)
    candidate_path.write_text(json.dumps(payload), encoding="utf-8")

    report = build_evidence_grounding_roadmap_completion_audit_report(
        candidate_benchmark_report_path=candidate_path,
        out=out,
    )

    assert report.roadmap_complete is False
    assert "candidate_configuration_lineage" in report.blockers
    check = next(item for item in report.checks if item.requirement_id == "candidate_configuration_lineage")
    assert check.status == "fail"
    assert "candidate_benchmark_manifest_path=-" in check.evidence
    assert "gold_release_package_path=-" in check.evidence
    assert "candidate_config_count=0" in check.evidence
    assert (
        "candidate_config_missing_replay_fields="
        "candidate:parser_version,llm_provider,llm_model,llm_model_version,prompt_version,reader_profile_version"
        in check.evidence
    )
    context = next(item for item in check.evidence if item.startswith("candidate_config_available_replay_context="))
    assert "candidate:run_meta.inference_lanes.reader.provider_model=llama3:latest" in context
    assert "run_meta.inference_lanes.reader.provider_name=ollama" in context
    assert "run_meta.parser_backend=fitz_pdfplumber" in context
    assert str(tmp_path) not in context
    lineage_action = next(
        item for item in report.next_actions if item.requirement_id == "candidate_configuration_lineage"
    )
    assert lineage_action.requires_human_review is False
    assert lineage_action.command_hint is not None
    assert "run_evidence_grounding_fixed_goldset_comparison.py" in lineage_action.command_hint
    assert "--candidate-parser-version <candidate_parser_version>" in lineage_action.command_hint
    assert "--candidate-llm-provider <candidate_llm_provider>" in lineage_action.command_hint
