def test_evidence_grounding_roadmap_completion_api_accepts_standalone_scorecard(tmp_path):
    scorecard = tmp_path / "evidence_grounding_scorecard.json"
    correction_export = tmp_path / "claim_evidence_eval_candidates.json"
    out = tmp_path / "roadmap_completion_scorecard_api.json"
    scorecard.write_text(json.dumps(_scorecard_payload()), encoding="utf-8")
    correction_export.write_text(
        json.dumps(_claim_evidence_eval_candidate_export_payload()),
        encoding="utf-8",
    )
    client = TestClient(api_main.app)

    response = client.post(
        "/evidence-grounding/roadmap-completion/audit",
        json={
            "scorecard_path": str(scorecard),
            "additional_artifact_paths": [str(correction_export)],
            "out": str(out),
        },
    )

    assert response.status_code == 200
    payload = response.json()
    assert payload["roadmap_complete"] is False
    assert payload["input_paths"]["scorecard_path"] == f".../{scorecard.name}"
    assert payload["additional_artifact_paths"] == [f".../{correction_export.name}"]
    assert payload["additional_artifact_count"] == 1
    assert str(scorecard.resolve()) not in json.dumps(payload)
    assert str(correction_export.resolve()) not in json.dumps(payload)
    persisted_payload = json.loads(out.read_text(encoding="utf-8"))
    assert persisted_payload["input_paths"]["scorecard_path"] == str(scorecard.resolve())
    assert persisted_payload["additional_artifact_paths"] == [str(correction_export.resolve())]
    assert persisted_payload["additional_artifact_count"] == 1
    noncanonical_check = next(
        item for item in payload["checks"] if item["requirement_id"] == "additive_noncanonical_artifacts"
    )
    assert noncanonical_check["status"] == "pass"
    assert "loaded_reports=scorecard" in noncanonical_check["evidence"]


