def test_evidence_grounding_roadmap_completion_package_clis_keep_queue_split_stdout_parity():
    root = Path(__file__).resolve().parents[1]
    scripts = [
        root / "scripts/eval/audit_evidence_grounding_roadmap_completion.py",
        root / "scripts/eval/audit_evidence_grounding_roadmap_completion_from_comparison_suite_package.py",
        root / "scripts/eval/audit_evidence_grounding_roadmap_completion_from_threshold_adoption_package.py",
    ]

    labels_by_script = {
        script.name: {
            match.group(1)
            for line in script.read_text(encoding="utf-8").splitlines()
            if (
                match := re.search(
                    r'"(frontier_(?:unblocked_)?human_review_queue_split_[a-zA-Z0-9_]+)="',
                    line,
                )
            )
        }
        for script in scripts
    }
    standalone_labels = labels_by_script["audit_evidence_grounding_roadmap_completion.py"]

    assert standalone_labels
    assert (
        labels_by_script[
            "audit_evidence_grounding_roadmap_completion_from_comparison_suite_package.py"
        ]
        == standalone_labels
    )
    assert (
        labels_by_script[
            "audit_evidence_grounding_roadmap_completion_from_threshold_adoption_package.py"
        ]
        == standalone_labels
    )


def test_evidence_grounding_roadmap_completion_queue_split_fields_are_exposed():
    root = Path(__file__).resolve().parents[1]
    schema_labels = {
        field_name
        for field_name in EvidenceGroundingRoadmapCompletionAuditReport.model_fields
        if field_name.startswith("frontier_human_review_queue_split_")
        or field_name.startswith("frontier_unblocked_human_review_queue_split_")
    }
    standalone_script = root / "scripts/eval/audit_evidence_grounding_roadmap_completion.py"
    standalone_labels = {
        match.group(1)
        for line in standalone_script.read_text(encoding="utf-8").splitlines()
        if (
            match := re.search(
                r'"(frontier_(?:unblocked_)?human_review_queue_split_[a-zA-Z0-9_]+)="',
                line,
            )
        )
    }
    service_source = (root / "src/services/evidence_grounding_benchmark.py").read_text(
        encoding="utf-8"
    )
    compatibility_block = re.search(
        r'if schema_version == "evidence_grounding_roadmap_completion_audit\.v1":'
        r".*?for field_name in \((.*?)\):\n\s+if field_name not in payload:",
        service_source,
        flags=re.S,
    )

    assert compatibility_block is not None
    compatibility_labels = set(
        re.findall(
            r'"(frontier_(?:unblocked_)?human_review_queue_split_[a-zA-Z0-9_]+)"',
            compatibility_block.group(1),
        )
    )

    assert schema_labels
    assert standalone_labels == schema_labels
    assert compatibility_labels == schema_labels


