def test_evidence_grounding_roadmap_completion_api_accepts_workspace_inventory_fields(tmp_path):
    goldset_root = tmp_path / "goldset"
    run_root = tmp_path / "runs"
    goldset_root.mkdir()
    run_root.mkdir()
    (goldset_root / "accepted_teacher.json").write_text(
        json.dumps(
            {
                "schema_version": "teacher_verification.v1",
                "paper_id": "paper-1",
                "claims": [],
            }
        ),
        encoding="utf-8",
    )
    client = TestClient(api_main.app)

    response = client.post(
        "/evidence-grounding/roadmap-completion/audit",
        json={
            "goldset_root": str(goldset_root),
            "run_root": str(run_root),
            "required_ready_gold_count": 1,
            "required_ready_run_count": 1,
        },
    )

    assert response.status_code == 200
    payload = response.json()
    assert payload["roadmap_complete"] is False
    assert "workspace_evidence_inventory_ready" in payload["blockers"]
    inventory_check = next(
        check for check in payload["checks"] if check["requirement_id"] == "workspace_evidence_inventory_ready"
    )
    assert f"goldset_root=.../{goldset_root.name}" in inventory_check["evidence"]
    assert f"run_root=.../{run_root.name}" in inventory_check["evidence"]
    assert str(goldset_root.resolve()) not in json.dumps(payload)
    assert str(run_root.resolve()) not in json.dumps(payload)
    assert (
        "Package legacy teacher_verification.v1 files into a reviewer handoff before curating fixed gold."
        in inventory_check["next_actions"]
    )
    assert (
        "Create or identify run directories whose declared paper_id matches the ready gold records and contains the required grounding sidecars."
        not in inventory_check["next_actions"]
    )
    workspace_actions = [
        item
        for item in payload["next_actions"]
        if item["requirement_id"] == "workspace_evidence_inventory_ready"
    ]
    assert any(
        item["action"]
        == "Package legacy teacher_verification.v1 files into a reviewer handoff before curating fixed gold."
        for item in workspace_actions
    )
    assert any(
        item["command_hint"] is not None
        and "package_paper_understanding_gold_reviewer_handoff.py" in item["command_hint"]
        for item in workspace_actions
    )
    assert not any(
        item["action"]
        == "Create or identify run directories whose declared paper_id matches the ready gold records and contains the required grounding sidecars."
        for item in workspace_actions
    )
    assert not any(
        item["action"] == "Build a ready seed/eval/holdout gold release package once enough staged gold records exist."
        for item in workspace_actions
    )
    assert any(item["phase"] == "gold_curation_and_release" for item in workspace_actions)
    assert any(item["requires_human_review"] is True for item in workspace_actions)
    assert payload["next_action_phase_counts"]["gold_curation_and_release"] >= 1
    assert payload["human_review_next_action_count"] >= 1


def test_evidence_grounding_roadmap_completion_workspace_actions_advance_existing_handoff(tmp_path):
    goldset_root = tmp_path / "goldset"
    run_root = tmp_path / "runs"
    goldset_root.mkdir()
    run_root.mkdir()
    out = tmp_path / "roadmap_completion.json"
    (goldset_root / "accepted_teacher.json").write_text(
        json.dumps(
            {
                "schema_version": "teacher_verification.v1",
                "paper_id": "paper-1",
                "claims": [],
            }
        ),
        encoding="utf-8",
    )
    (goldset_root / "reviewer_guide.md").write_text("# reviewer guide\n", encoding="utf-8")
    (goldset_root / "reviewer_handoff.json").write_text(
        json.dumps(
            {
                "schema_version": "paper_understanding_gold_reviewer_handoff_package.v1",
                "layer": "review_gate_artifact",
                "canonical_status": "non_canonical",
                "generated_at": datetime.now(timezone.utc).isoformat(),
                "package_id": "paper-understanding-gold-reviewer-handoff",
                "source_paths": ["accepted_teacher.json"],
                "curation_package_path": "curation_package.json",
                "patch_template_manifest_path": "patch_templates/manifest.json",
                "curation_progress_report_path": "curation_progress.json",
                "curation_task_export_path": "curation_tasks.json",
                "reviewer_guide_path": "reviewer_guide.md",
                "draft_count": 1,
                "open_task_count": 1,
            }
        ),
        encoding="utf-8",
    )
    patch_template_dir = goldset_root / "patch_templates"
    patch_template_dir.mkdir()
    patch_template = patch_template_dir / "paper-1.patch_template.json"
    patch_template.write_text("{}", encoding="utf-8")
    (patch_template_dir / "manifest.json").write_text(
        json.dumps(
            {
                "schema_version": "paper_understanding_gold_candidate_draft_patch_template_manifest.v1",
                "template_paths": [patch_template.name],
            }
        ),
        encoding="utf-8",
    )

    report = build_evidence_grounding_roadmap_completion_audit_report(
        goldset_root=goldset_root,
        run_root=run_root,
        required_ready_gold_count=1,
        required_ready_run_count=1,
        out=out,
    )

    inventory_check = next(check for check in report.checks if check.requirement_id == "workspace_evidence_inventory_ready")
    handoff_action_prefix = (
        "Edit reviewer handoff patch templates, then apply the saved reviewer handoff package "
        "to produce patch results"
    )
    assert any(
        action.startswith(handoff_action_prefix)
        and "1 patch template" in action
        and str(patch_template.resolve()) in action
        for action in inventory_check.next_actions
    )
    assert "gold_reviewer_handoff_patch_template_path_count=1" in inventory_check.evidence
    assert f"gold_reviewer_handoff_patch_template_paths_sample={patch_template.resolve()}" in inventory_check.evidence
    workspace_actions = [
        item
        for item in report.next_actions
        if item.requirement_id == "workspace_evidence_inventory_ready"
    ]
    apply_action = next(
        item
        for item in workspace_actions
        if "apply the saved reviewer handoff package" in item.action
    )
    assert apply_action.command_hint is not None
    assert "apply_paper_understanding_gold_reviewer_handoff.py" in apply_action.command_hint
    assert apply_action.requires_human_review is True
    fixed_gold_action = next(
        item
        for item in report.next_actions
        if item.requirement_id == "fixed_goldset_release_readiness"
        and item.action.startswith(handoff_action_prefix)
    )
    assert "1 patch template" in fixed_gold_action.action
    assert str(patch_template.resolve()) in fixed_gold_action.action
    assert fixed_gold_action.command_hint is not None
    assert "apply_paper_understanding_gold_reviewer_handoff.py" in fixed_gold_action.command_hint
    assert "--require-edited" in fixed_gold_action.command_hint
    assert report.next_actions[0].requirement_id == "fixed_goldset_release_readiness"
    assert report.next_actions[0].action.startswith(handoff_action_prefix)
    assert "1 patch template" in report.next_actions[0].action
    assert str(patch_template.resolve()) in report.next_actions[0].action
    assert not any(
        item.requirement_id == "fixed_goldset_release_readiness"
        and item.action
        == "Run the gold release-readiness audit and provide the resulting paper_understanding_gold_release_readiness.v1 report."
        for item in report.next_actions
    )
    assert not any(
        item.phase in {
            "fixed_goldset_run",
            "threshold_adoption",
            "threshold_package",
            "contract_readiness",
        }
        for item in report.next_actions
    )
    assert "fixed_goldset_candidate_run" in report.blockers
    assert "external_contract_readiness_reviewed" in report.blockers
    assert report.human_review_unique_next_action_count < report.human_review_next_action_count
    assert len(report.human_review_unique_next_actions) == report.human_review_unique_next_action_count


