def test_evidence_grounding_roadmap_completion_api_accepts_gold_release_package(tmp_path):
    paths = _write_standalone_roadmap_completion_ready_paths(tmp_path)
    out = tmp_path / "standalone_api_with_release_package.json"
    client = TestClient(api_main.app)

    response = client.post(
        "/evidence-grounding/roadmap-completion/audit",
        json={
            "comparison_suite_path": str(paths["comparison_suite"]),
            "threshold_calibration_report_path": str(paths["package_threshold_calibration"]),
            "threshold_adoption_review_path": str(paths["package_threshold_adoption"]),
            "contract_readiness_report_path": str(paths["package_contract_readiness"]),
            "gold_release_package_path": str(paths["gold_release_package"]),
            "correction_log_path": str(paths["correction_log"]),
            "out": str(out),
        },
    )

    assert response.status_code == 200
    payload = response.json()
    assert payload["roadmap_complete"] is False
    assert "fixed_goldset_threshold_adoption_package_ready" in payload["blockers"]
    assert payload["input_paths"]["gold_release_package_path"] == f".../{paths['gold_release_package'].name}"
    assert payload["input_paths"]["gold_release_readiness_report_path"] == f".../{paths['gold_release_readiness'].name}"
    assert str(paths["gold_release_package"].resolve()) not in json.dumps(payload)
    persisted_payload = json.loads(out.read_text(encoding="utf-8"))
    assert persisted_payload["input_paths"]["gold_release_package_path"] == str(paths["gold_release_package"].resolve())
    assert persisted_payload["input_paths"]["gold_release_readiness_report_path"] == str(paths["gold_release_readiness"].resolve())


def test_build_p0_overstatement_review_packet_from_benchmark_report(tmp_path):
    run_dir = tmp_path / "runs" / "paper-1" / "run-1"
    _write_p0_overstatement_packet_source_run(run_dir)
    report_path = tmp_path / "benchmark.json"
