def test_active_review_readiness_contract_compatibility_rejects_inconsistent_counts(tmp_path):
    readiness = tmp_path / "active_review_readiness.json"
    payload = {
        "schema_version": "evidence_grounding_active_review_readiness.v1",
        "layer": "review_gate_artifact",
        "canonical_status": "non_canonical",
        "generated_at": "2026-05-31T00:00:00+00:00",
        "ready_for_downstream_review_steps": False,
        "structured_correction": {
            "fill_review_status_path": "structured.fill_review_status.json",
            "ready_for_apply": False,
            "open_csv_row_count": 2,
            "open_record_count": 1,
            "missing_value_count": 2,
            "missing_evidence_count": 0,
        },
        "p0_overstatement": {
            "summary_path": "p0_summary.json",
            "ready_for_p0_metric": True,
            "claim_review_row_count": 1,
            "missing_decision_count": 0,
            "invalid_decision_count": 0,
            "uncertain_claim_count": 0,
            "missing_rationale_count": 0,
        },
        "active_brief_audit": {
            "audit_path": "active_brief_audit.json",
            "all_passed": True,
            "fail_count": 0,
        },
        "blocker_count": 1,
        "blockers": [{"blocker_id": "structured_correction_not_ready_for_apply"}],
    }
    readiness.write_text(json.dumps(payload), encoding="utf-8")

    compatibility = build_evidence_grounding_contract_compatibility_report(artifact_paths=[readiness])
    assert compatibility.fail_count == 0

    payload["blocker_count"] = 0
    readiness.write_text(json.dumps(payload), encoding="utf-8")
    stale_compatibility = build_evidence_grounding_contract_compatibility_report(artifact_paths=[readiness])

    assert stale_compatibility.fail_count == 1
    assert any(
        finding.startswith("active_review_readiness_schema_validation_failed:")
        for finding in stale_compatibility.items[0].findings
    )

    work_item_payload = copy.deepcopy(payload)
    work_item_payload["blocker_count"] = 1
    work_item_payload["reviewer_work_items"] = [
        {
            "item_id": "structured_correction_metadata_review",
            "label": "Structured correction metadata review",
            "reviewer_action": "Fill reviewer_value and reviewer_evidence.",
            "expected_paper_reading": "no",
            "primary_review_source": "full context packet and reviewed/open-record CSVs",
            "open_item_count": 2,
            "open_record_count": 1,
            "blocked_roadmap_requirement_ids": ["structured_correction_log"],
        }
    ]
    work_item_payload["reviewer_work_item_count"] = 1
    work_item_payload["reviewer_open_item_counts_by_expected_paper_reading"] = {"no": 2}
    work_item_payload["reviewer_open_paper_counts_by_expected_paper_reading"] = {}
    readiness.write_text(json.dumps(work_item_payload), encoding="utf-8")
    work_item_compatibility = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[readiness],
    )
    assert work_item_compatibility.fail_count == 0

    stale_work_item_summary_expectations = {
        "reviewer_work_item_count": (
            2,
            "reviewer_work_item_count must match reviewer_work_items length",
        ),
        "reviewer_open_item_counts_by_expected_paper_reading": (
            {"no": 1},
            "reviewer_open_item_counts_by_expected_paper_reading must match reviewer_work_items",
        ),
        "reviewer_open_paper_counts_by_expected_paper_reading": (
            {"no": 1},
            "reviewer_open_paper_counts_by_expected_paper_reading must match reviewer_work_items",
        ),
    }
    for stale_field, (stale_value, expected_finding) in (
        stale_work_item_summary_expectations.items()
    ):
        stale_work_item_payload = copy.deepcopy(work_item_payload)
        stale_work_item_payload[stale_field] = stale_value
        readiness.write_text(json.dumps(stale_work_item_payload), encoding="utf-8")
        stale_work_item_compatibility = build_evidence_grounding_contract_compatibility_report(
            artifact_paths=[readiness],
        )

        assert stale_work_item_compatibility.fail_count == 1
        assert any(
            finding.startswith("active_review_readiness_schema_validation_failed:")
            and expected_finding in finding
            for finding in stale_work_item_compatibility.items[0].findings
        )


