def test_refresh_evidence_grounding_active_reviewer_handoff_cli(tmp_path):
    roadmap_audit = tmp_path / "roadmap_audit.json"
    roadmap_audit.write_text(
        json.dumps(
            {
                "roadmap_complete": False,
                "pass_count": 9,
                "fail_count": 5,
                "human_review_open_csv_row_count": 1,
                "human_review_open_record_count": 1,
                "frontier_human_review_open_csv_row_counts_by_requirement": {
                    "structured_correction_log": 1,
                },
            }
        ),
        encoding="utf-8",
    )
    structured_status = tmp_path / "structured.reviewed.fill_review_status.json"
    structured_status.write_text(
        json.dumps(
            {
                "ready_for_apply": False,
                "open_record_count": 1,
                "open_csv_row_count": 1,
                "missing_value_count": 1,
                "missing_evidence_count": 0,
            }
        ),
        encoding="utf-8",
    )
    structured_reviewed = tmp_path / "structured.reviewed.csv"
    structured_reviewed.write_text("task_id,reviewer_value\n", encoding="utf-8")
    structured_reviewed_before = structured_reviewed.read_text(encoding="utf-8")
    structured_task_export = tmp_path / "structured_fill_tasks.json"
    structured_task_export.write_text(json.dumps({"schema_version": "fill_tasks.v1"}), encoding="utf-8")
    structured_open_records = tmp_path / "structured.reviewed.open_records.csv"
    with structured_open_records.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(
            handle,
            fieldnames=[
                "record_ref",
                "open_field_names",
                "filled_patch_fields",
                "reviewer_evidence_hint",
            ],
        )
        writer.writeheader()
        writer.writerow(
            {
                "record_ref": "record-1",
                "open_field_names": "parser_version",
                "filled_patch_fields": "",
                "reviewer_evidence_hint": "source context",
            }
        )
    split_manifest = tmp_path / "split_manifest.json"
    split_manifest.write_text(
        json.dumps(
            {
                "sources": [
                    {
                        "reviewed_csv_path": str(structured_reviewed),
                        "source_task_export_path": str(structured_task_export),
                        "fill_review_audit_command_hint": (
                            ".venv/bin/python "
                            "scripts/eval/audit_evidence_grounding_patch_template_fill_task_reviews.py "
                            f"--task-export {structured_task_export} "
                            f"--reviewed-csv {structured_reviewed} "
                            f"--out {structured_status} "
                            f"--open-record-csv-out {structured_open_records}"
                        ),
                        "requirement_ids": ["structured_correction_log"],
                    }
                ]
            }
        ),
        encoding="utf-8",
    )

    run_dir = tmp_path / "runs" / "paper-1" / "run-1"
    _write_p0_overstatement_packet_source_run(run_dir)
    report_path = tmp_path / "benchmark.json"
    report_path.write_text(
        json.dumps(_benchmark_payload(benchmark_id="bench-seed", goldset_split="seed", include_scorecard=True)),
        encoding="utf-8",
    )
    p0_packet = build_evidence_grounding_p0_overstatement_review_packet_from_benchmark_reports([report_path])
    p0_packet_out = tmp_path / "p0_packet.json"
    p0_packet_out.write_text(p0_packet.model_dump_json(indent=2), encoding="utf-8")
    p0_reviewed = tmp_path / "p0_reviewed.csv"
    _write_p0_overstatement_reviewed_csv(p0_reviewed, decision="", rationale="")
    p0_reviewed_before = p0_reviewed.read_text(encoding="utf-8")
    p0_summary = build_evidence_grounding_p0_overstatement_review_summary(
        packet_path=p0_packet_out,
        reviewed_csv_path=p0_reviewed,
    )
    p0_open_issue = tmp_path / "p0_open_issues.csv"
    write_evidence_grounding_p0_overstatement_review_summary_open_issue_csv(p0_summary, p0_open_issue)

    structured_brief = tmp_path / "frontier_active_reviewer_brief.md"
    p0_brief = tmp_path / "p0_active_reviewer_brief.md"
    brief_audit = tmp_path / "active_reviewer_brief_audit.json"
    readiness_out = tmp_path / "active_review_readiness.json"
    refresh_out = tmp_path / "active_reviewer_handoff_refresh.json"

    result = subprocess.run(
        [
            sys.executable,
            "scripts/eval/refresh_evidence_grounding_active_reviewer_handoff.py",
            "--roadmap-audit",
            str(roadmap_audit),
            "--split-manifest",
            str(split_manifest),
            "--structured-brief-out",
            str(structured_brief),
            "--p0-packet",
            str(p0_packet_out),
            "--p0-reviewed-csv",
            str(p0_reviewed),
            "--p0-open-issue-csv",
            str(p0_open_issue),
            "--p0-summary-out",
            str(tmp_path / "p0_summary.json"),
            "--p0-brief-out",
            str(p0_brief),
            "--brief-audit-out",
            str(brief_audit),
            "--active-review-readiness-out",
            str(readiness_out),
            "--out",
            str(refresh_out),
            "--generated-date",
            "2026-05-31",
        ],
        cwd=Path(__file__).resolve().parents[1],
        text=True,
        capture_output=True,
        check=False,
    )

    assert result.returncode == 0, result.stderr
    assert "[active_reviewer_handoff_refresh] audit_all_passed=true" in result.stdout
    assert "readiness_blocker_count=4" in result.stdout
    assert structured_reviewed.read_text(encoding="utf-8") == structured_reviewed_before
    assert p0_reviewed.read_text(encoding="utf-8") == p0_reviewed_before
    refresh_payload = json.loads(refresh_out.read_text(encoding="utf-8"))
    assert refresh_payload["schema_version"] == "evidence_grounding_active_reviewer_handoff_refresh.v1"
    assert refresh_payload["brief_audit_all_passed"] is True
    assert refresh_payload["brief_audit_counts"]["structured_open_csv_row_count"] == 1
    assert refresh_payload["brief_audit_counts"]["p0_open_issue_row_count"] == 1
    assert refresh_payload["brief_audit_counts"]["p0_open_paper_count"] == 1
    assert refresh_payload["active_review_ready_for_downstream_review_steps"] is False
    assert refresh_payload["active_review_readiness_blocker_count"] == 4
    p0_summary_payload = json.loads((tmp_path / "p0_summary.json").read_text(encoding="utf-8"))
    assert p0_summary_payload["open_issue_csv_path"] == str(p0_open_issue.resolve())
    refresh_compatibility = build_evidence_grounding_contract_compatibility_report(
        artifact_paths=[refresh_out]
    )
    assert refresh_compatibility.fail_count == 0
    assert refresh_compatibility.items[0].schema_version == (
        "evidence_grounding_active_reviewer_handoff_refresh.v1"
    )
    audit_payload = json.loads(brief_audit.read_text(encoding="utf-8"))
    assert audit_payload["all_passed"] is True
    readiness_payload = json.loads(readiness_out.read_text(encoding="utf-8"))
    assert readiness_payload["schema_version"] == "evidence_grounding_active_review_readiness.v1"
    assert readiness_payload["blocker_count"] == 4
    assert "- Open records: `1`" in structured_brief.read_text(encoding="utf-8")
    assert "- Open issue rows: `1`" in p0_brief.read_text(encoding="utf-8")


def test_summarize_p0_overstatement_review_packet_api_masks_paths_and_writes_output(tmp_path):
    run_dir = tmp_path / "runs" / "paper-1" / "run-1"
    _write_p0_overstatement_packet_source_run(run_dir)
    report_path = tmp_path / "benchmark.json"
    report_path.write_text(
        json.dumps(_benchmark_payload(benchmark_id="bench-seed", goldset_split="seed", include_scorecard=True)),
        encoding="utf-8",
    )
    packet = build_evidence_grounding_p0_overstatement_review_packet_from_benchmark_reports([report_path])
    packet_out = tmp_path / "packet.json"
    packet_out.write_text(packet.model_dump_json(indent=2), encoding="utf-8")
    reviewed_csv = tmp_path / "reviewed.csv"
    _write_p0_overstatement_reviewed_csv(
        reviewed_csv,
        decision="NO",
        rationale="The claim stays within the cited evidence.",
    )
    summary_out = tmp_path / "api_summary.json"
    open_issue_csv = tmp_path / "api_open_issues.csv"
    client = TestClient(api_main.app)

    response = client.post(
        "/evidence-grounding/p0-overstatement-review-packet/summarize",
        json={
            "packet_path": str(packet_out),
            "reviewed_csv_path": str(reviewed_csv),
            "out": str(summary_out),
            "open_issue_csv_out": str(open_issue_csv),
        },
    )

    assert response.status_code == 200
    payload = response.json()
    assert payload["schema_version"] == "evidence_grounding_p0_overstatement_review_summary.v1"
    assert payload["ready_for_p0_metric"] is True
    assert payload["overstatement_rate_status"]["value"] == 0.0
    assert payload["source_packet_path"] == f".../{packet_out.name}"
    assert payload["source_reviewed_csv_path"] == f".../{reviewed_csv.name}"
    assert payload["open_issue_csv_path"] == f".../{open_issue_csv.name}"
    assert str(tmp_path.resolve()) not in json.dumps(payload)
    persisted_payload = json.loads(summary_out.read_text(encoding="utf-8"))
    assert persisted_payload["source_packet_path"] == str(packet_out.resolve())
    assert persisted_payload["source_reviewed_csv_path"] == str(reviewed_csv.resolve())
    assert persisted_payload["open_issue_csv_path"] == str(open_issue_csv.resolve())
    assert open_issue_csv.exists()


def test_roadmap_completion_accepts_completed_p0_overstatement_summary_as_metric_evidence(tmp_path):
    paths = _write_roadmap_completion_package_inputs(tmp_path)
    candidate_payload = json.loads(paths["candidate"].read_text(encoding="utf-8"))
    candidate_payload["aggregate_gold_scored_metrics"].pop("overstatement_rate")
    candidate_payload["scorecards"][0]["scorecard"]["gold_scored_metrics"]["overstatement_rate"] = {
        "status": "not_available",
        "source": "paper_understanding_gold.review_failure_codes",
        "detail": "Requires explicit OVERSTATED_RESULT labels or structured human review.",
    }
    paths["candidate"].write_text(json.dumps(candidate_payload), encoding="utf-8")

    packet_run_dir = tmp_path / "runs" / "paper-1" / "run-1"
    _write_p0_overstatement_packet_source_run(packet_run_dir)
    packet_report = tmp_path / "p0_packet_source_benchmark.json"
    packet_report.write_text(
        json.dumps(_benchmark_payload(benchmark_id="bench-seed", goldset_split="seed", include_scorecard=True)),
        encoding="utf-8",
    )
    packet = build_evidence_grounding_p0_overstatement_review_packet_from_benchmark_reports([packet_report])
    packet_out = tmp_path / "packet.json"
    packet_out.write_text(packet.model_dump_json(indent=2), encoding="utf-8")
    reviewed_csv = tmp_path / "reviewed.csv"
    _write_p0_overstatement_reviewed_csv(
        reviewed_csv,
        decision="NOT_OVERSTATED",
        rationale="Reviewer judged the claim as not overstated against the packet context.",
    )
    summary = build_evidence_grounding_p0_overstatement_review_summary(
        packet_path=packet_out,
        reviewed_csv_path=reviewed_csv,
    )
    summary_out = tmp_path / "p0_overstatement_review_summary.json"
    summary_out.write_text(summary.model_dump_json(indent=2), encoding="utf-8")

    report = build_evidence_grounding_roadmap_completion_audit_report(
        comparison_suite_path=paths["comparison_suite"],
        gold_release_readiness_report_path=paths["gold_release_readiness"],
        additional_artifact_paths=[summary_out],
        out=tmp_path / "roadmap_with_p0_summary.json",
    )

    p0_check = next(item for item in report.checks if item.requirement_id == "p0_metrics_reported")
    assert p0_check.status == "pass"
    assert "missing_p0_metrics=-" in p0_check.evidence
    assert "p0_overstatement_review_summary_ready_for_p0_metric=true" in p0_check.evidence
    assert "p0_overstatement_review_summary_overstatement_rate=0" in p0_check.evidence


