def _write_gold_release_manifest_paths(tmp_path: Path) -> list[Path]:
    manifest_paths: list[Path] = []
    for split in ("seed", "eval", "holdout"):
        gold_dir = tmp_path / "gold_release" / split
        gold_dir.mkdir(parents=True, exist_ok=True)
        gold_path = gold_dir / f"paper-{split}.json"
        gold_path.write_text(
            json.dumps(_ready_paper_understanding_gold_payload(paper_id=f"paper-{split}")),
            encoding="utf-8",
        )
        staging_manifest_path = gold_dir / "staging_manifest.json"
        staging_manifest_path.write_text(
            json.dumps(
                {
                    "schema_version": "paper_understanding_gold_staging_manifest.v1",
                    "layer": "review_gate_artifact",
                    "canonical_status": "non_canonical",
                    "generated_at": datetime.now(timezone.utc).isoformat(),
                    "source_draft_paths": [],
                    "out_dir": str(gold_dir.resolve()),
                    "require_ready": True,
                    "staged_count": 1,
                    "staged_paths": [str(gold_path.resolve())],
                    "readiness_summary": {"pass_count": 1, "warn_count": 0, "fail_count": 0},
                }
            ),
            encoding="utf-8",
        )
        manifest_path = tmp_path / "gold_release" / f"{split}_manifest.json"
        manifest = build_paper_understanding_gold_manifest(
            [staging_manifest_path],
            goldset_id="paper-understanding-pilot-2026-05-22",
            goldset_split=split,
            manifest_path=manifest_path,
            require_ready=True,
        )
        manifest_path.write_text(manifest.model_dump_json(indent=2), encoding="utf-8")
        manifest_paths.append(manifest_path)
    return manifest_paths


def _write_gold_release_staging_split_items(tmp_path: Path) -> list[PaperUnderstandingGoldReleaseManifestBuildItem]:
    items: list[PaperUnderstandingGoldReleaseManifestBuildItem] = []
    for split in ("seed", "eval", "holdout"):
        staging_manifest = _write_staged_gold_manifest(
            tmp_path / "gold_release_staged" / split,
            paper_id=f"paper-{split}",
        )
        items.append(
            PaperUnderstandingGoldReleaseManifestBuildItem(
                staging_manifest_path=str(staging_manifest),
                goldset_split=split,
                manifest_out=str(tmp_path / "gold_release_from_staged" / f"{split}.json"),
            )
        )
    return items


def _write_gold_release_split_plan_from_staged_items(
    tmp_path: Path,
    items: list[PaperUnderstandingGoldReleaseManifestBuildItem],
) -> Path:
    split_plan_path = tmp_path / "gold_release_split_plan.json"
    split_plan_path.write_text(
        json.dumps(
            {
                "schema_version": "paper_understanding_gold_release_split_plan.v1",
                "layer": "review_gate_artifact",
                "canonical_status": "non_canonical",
                "generated_at": datetime.now(timezone.utc).isoformat(),
                "plan_id": "paper-understanding-gold-release-split-plan",
                "source_staging_manifest_path": str((tmp_path / "combined" / "staging_manifest.json").resolve()),
                "out_dir": str((tmp_path / "gold_release_staged").resolve()),
                "manifest_out_dir": str((tmp_path / "gold_release_from_split_plan").resolve()),
                "split_names": [item.goldset_split for item in items],
                "min_ready_per_split": 1,
                "ready_input_count": len(items),
                "invalid_input_count": 0,
                "release_ready_candidate": True,
                "split_manifests": [item.model_dump() for item in items],
                "split_items": [
                    {
                        "goldset_split": item.goldset_split,
                        "staging_manifest_path": item.staging_manifest_path,
                        "manifest_out": item.manifest_out,
                        "staged_count": 1,
                        "paper_ids": [f"paper-{item.goldset_split}"],
                    }
                    for item in items
                ],
                "warnings": [],
            }
        ),
        encoding="utf-8",
    )
    return split_plan_path


def _write_threshold_adoption_inputs(tmp_path: Path, *, p0_complete: bool = True) -> dict[str, Path]:
    tmp_path.mkdir(parents=True, exist_ok=True)
    baseline_path = tmp_path / "baseline.json"
    candidate_path = tmp_path / "candidate.json"
    calibration_path = tmp_path / "threshold_calibration.json"
    comparison_path = tmp_path / "comparison.json"
    run_readiness_path = tmp_path / "run_readiness.json"
    comparison_suite_path = tmp_path / "comparison_suite.json"
    baseline_metrics = {"claim_precision": 0.9}
    candidate_metrics = {"claim_precision": 0.91}
    if p0_complete:
        baseline_metrics.update(
            {
                "evidence_support_precision": 0.9,
                "locator_precision": 0.9,
                "unsupported_claim_rate": 0.01,
                "overstatement_rate": 0.01,
                "limitation_recall": 0.9,
                "method_result_confusion_rate": 0.01,
            }
        )
        candidate_metrics.update(
            {
                "evidence_support_precision": 0.91,
                "locator_precision": 0.91,
                "unsupported_claim_rate": 0.005,
                "overstatement_rate": 0.005,
                "limitation_recall": 0.91,
                "method_result_confusion_rate": 0.005,
            }
        )
    baseline_path.write_text(
        json.dumps(_benchmark_payload(benchmark_id="baseline", **baseline_metrics)),
        encoding="utf-8",
    )
    candidate_path.write_text(
        json.dumps(_benchmark_payload(benchmark_id="candidate", **candidate_metrics)),
        encoding="utf-8",
    )
    if p0_complete:
        build_evidence_grounding_threshold_calibration_report(
            report_paths=[baseline_path],
            out=calibration_path,
        )
        compare_evidence_grounding_scorecard_reports(
            baseline=baseline_path,
            candidate=candidate_path,
            threshold_preset="p0_gold_minimum",
            out=comparison_path,
        )
    else:
        build_evidence_grounding_threshold_calibration_report(
            report_paths=[baseline_path],
            metric_names=["claim_precision"],
            metric_preset="explicit",
            out=calibration_path,
        )
        compare_evidence_grounding_scorecard_reports(
            baseline=baseline_path,
            candidate=candidate_path,
            threshold_metric_values={"gold_scored_metrics.claim_precision": 0.9},
            out=comparison_path,
        )
    run_readiness_path.write_text(
        json.dumps(_run_readiness_payload(comparison_run_ready=True)),
        encoding="utf-8",
    )
    comparison_suite_path.write_text(
        json.dumps(
            {
                "schema_version": "evidence_grounding_fixed_goldset_comparison_suite.v1",
                "layer": "review_gate_artifact",
                "canonical_status": "non_canonical",
                "generated_at": datetime.now(timezone.utc).isoformat(),
                "comparison_suite_id": "threshold-adoption-suite",
                "baseline_report_path": "baseline.json",
                "candidate_report_path": "candidate.json",
                "comparison_report_path": "comparison.json",
                "run_readiness_report_path": "run_readiness.json",
                "comparison_passed": True,
                "comparison_run_ready": True,
                "run_readiness_fail_count": 0,
            }
        ),
        encoding="utf-8",
    )
    return {
        "baseline": baseline_path,
        "candidate": candidate_path,
        "calibration": calibration_path,
        "comparison": comparison_path,
        "run_readiness": run_readiness_path,
        "comparison_suite": comparison_suite_path,
    }


def _write_roadmap_completion_package_inputs(tmp_path: Path) -> dict[str, Path]:
    paths = _write_threshold_adoption_inputs(tmp_path)
    full_baseline_metrics = {
        "claim_precision": 0.9,
        "evidence_support_precision": 0.9,
        "locator_precision": 0.9,
        "unsupported_claim_rate": 0.01,
        "overstatement_rate": 0.01,
        "limitation_recall": 0.9,
        "method_result_confusion_rate": 0.01,
    }
    full_candidate_metrics = {
        "claim_precision": 0.91,
        "evidence_support_precision": 0.91,
        "locator_precision": 0.91,
        "unsupported_claim_rate": 0.005,
        "overstatement_rate": 0.005,
        "limitation_recall": 0.91,
        "method_result_confusion_rate": 0.005,
    }
    for key, benchmark_id, metrics in (
        ("baseline", "baseline", full_baseline_metrics),
        ("candidate", "candidate", full_candidate_metrics),
    ):
        paths[key].write_text(
            json.dumps(
                _benchmark_payload(
                    benchmark_id=benchmark_id,
                    goldset_id="paper-understanding-seed",
                    goldset_split="eval",
                    goldset_manifest_path="goldset/manifests/eval.json",
                    goldset_item_count=1,
                    goldset_covered_paper_count=1,
                    goldset_readiness_pass_count=1,
                    goldset_readiness_fail_count=0,
                    input_artifact_coverage_rate=1.0,
                    missing_input_artifact_count=0.0,
                    malformed_input_artifact_count=0.0,
                    stage_gold_metrics={"grounding_checker": {"evidence_support_precision": metrics["claim_precision"]}},
                    include_scorecard=True,
                    candidate_config=_candidate_config_payload(benchmark_id),
                    **metrics,
                )
            ),
            encoding="utf-8",
        )
    compare_evidence_grounding_scorecard_reports(
        baseline=paths["baseline"],
        candidate=paths["candidate"],
        gate_preset="p0_gold",
        threshold_preset="p0_gold_minimum",
        out=paths["comparison"],
    )
    correction_log = tmp_path / "claim_evidence_corrections.jsonl"
    correction_log.write_text(
        json.dumps(
            {
                "paper_id": "paper-1",
                "run_id": "run-1",
                "claim_id": "c1",
                "field_path": "claims[0].text",
                "before_claim_text": "Treatment proves broad benefit.",
                "after_claim_text": "Treatment improved survival in the measured cohort.",
                "before_evidence_refs": [{"page": 2, "quote": "Treatment improved survival."}],
                "after_evidence_refs": [{"page": 2, "quote": "Treatment improved survival."}],
                "reason_codes": ["OVERSTATED_RESULT"],
                "reviewer_id": "reviewer-1",
                "parser_version": "parser-v2",
                "llm_provider": "local",
                "llm_model": "reader-model",
                "llm_model_version": "reader-model-2026-05-22",
                "prompt_version": "grounding-prompt-v2",
                "reader_profile_version": "reader-profile-v2",
                "created_at": datetime.now(timezone.utc).isoformat(),
                "accepted_for_eval": True,
            }
        )
        + "\n",
        encoding="utf-8",
    )
    for name in ("migration", "backfill", "public_contract"):
        path = tmp_path / f"{name}.md"
        path.write_text(f"{name} review complete.", encoding="utf-8")
        paths[name] = path
    gold_release_readiness_path = tmp_path / "gold_release_readiness.json"
    gold_release_manifests = _write_gold_release_manifest_paths(tmp_path)
    gold_release_readiness_payload = _gold_release_readiness_payload()
    for summary, manifest_path in zip(gold_release_readiness_payload["split_summaries"], gold_release_manifests):
        summary["manifest_path"] = str(manifest_path.resolve())
    gold_release_readiness_path.write_text(json.dumps(gold_release_readiness_payload), encoding="utf-8")
    gold_release_package_path = tmp_path / "gold_release_package.json"
    gold_release_package_path.write_text(
        json.dumps(
            {
                "schema_version": "paper_understanding_gold_release_package.v1",
                "layer": "review_gate_artifact",
                "canonical_status": "non_canonical",
                "generated_at": datetime.now(timezone.utc).isoformat(),
                "package_id": "paper-understanding-gold-release-package",
                "goldset_id": "paper-understanding-pilot-2026-05-22",
                "source_split_manifests": [
                    {
                        "staging_manifest_path": str(
                            (tmp_path / "gold_release" / split / "staging_manifest.json").resolve()
                        ),
                        "goldset_split": split,
                        "manifest_out": str(manifest_path.resolve()),
                    }
                    for split, manifest_path in zip(("seed", "eval", "holdout"), gold_release_manifests)
                ],
                "manifest_paths": [str(path.resolve()) for path in gold_release_manifests],
                "release_readiness_report_path": gold_release_readiness_path.name,
                "release_readiness": gold_release_readiness_payload,
            }
        ),
        encoding="utf-8",
    )
    paths["correction_log"] = correction_log
    paths["gold_release_readiness"] = gold_release_readiness_path
    paths["gold_release_package"] = gold_release_package_path
    paths["gold_release_manifests"] = gold_release_manifests
    return paths


