    repair_template = tmp_path / "claim_evidence_correction_repair_patch_template.json"
    repair_prefilled_template = tmp_path / "claim_evidence_correction_repair_patch_template_prefilled.json"
    repair_prefilled_readiness = tmp_path / "claim_evidence_correction_repair_patch_template_prefilled_fill_readiness.json"
