    repair_fill_tasks_markdown = tmp_path / "claim_evidence_correction_repair_patch_template_fill_tasks.md"
    repair_reviewed_csv = tmp_path / "claim_evidence_correction_repair_patch_template_prefilled_fill_tasks_reviewed.csv"
    repair_annotated_csv = tmp_path / "claim_evidence_correction_repair_patch_template_prefilled_fill_tasks_annotated.csv"
    repair_open_csv = tmp_path / "claim_evidence_correction_repair_patch_template_prefilled_fill_tasks_open.csv"
    repair_review_status = tmp_path / "claim_evidence_correction_repair_patch_template_prefilled_fill_review_status.json"
    repair_template.write_text(
        json.dumps(_claim_evidence_correction_repair_patch_template_payload()),
        encoding="utf-8",
    )
    build_evidence_grounding_patch_template_prefill_from_suggestions(
        patch_template_path=repair_template,
        out=repair_prefilled_template,
    )
    build_evidence_grounding_patch_template_fill_readiness_report(
        patch_template_path=repair_prefilled_template,
        out=repair_prefilled_readiness,
    )
    build_evidence_grounding_patch_template_fill_task_export(
        fill_readiness_path=repair_prefilled_readiness,
        out=repair_fill_tasks,
        markdown_out=repair_fill_tasks_markdown,
    )
    _write_reviewed_fill_task_csv(
        task_export_path=repair_fill_tasks,
        out=repair_reviewed_csv,
        values_by_field={"parser_version": "parser-reviewed"},
    )
    build_evidence_grounding_patch_template_fill_review_status_report(
        task_export_path=repair_fill_tasks,
        reviewed_csv_path=repair_reviewed_csv,
        annotated_csv_path=repair_annotated_csv,
        open_csv_path=repair_open_csv,
        out=repair_review_status,
    )

    return [
        candidate_template,
        candidate_prefilled_template,
        candidate_prefilled_readiness,
        candidate_fill_tasks,
        candidate_review_status,
        repair_template,
        repair_prefilled_template,
        repair_prefilled_readiness,
        repair_fill_tasks,
        repair_review_status,
    ]


