def _write_reviewed_fill_task_csv(
    *,
    task_export_path: Path,
    out: Path,
    values_by_field: dict[str, str],
    include_evidence: bool = True,
    include_evidence_hint: bool = False,
    missing_evidence_fields: set[str] | None = None,
) -> None:
    task_export = json.loads(task_export_path.read_text(encoding="utf-8"))
    missing_evidence_fields = missing_evidence_fields or set()
    lines = [
        "task_id,record_ref,field_name,suggested_value,available_context_keys,"
        "available_context_values,filled_patch_fields,review_required,reviewer_value,"
        "reviewer_value_hint,reviewer_evidence_hint,reviewer_evidence,reviewer_notes"
    ]
    for task in task_export["tasks"]:
        field_name = task["field_name"]
        reviewer_value = values_by_field.get(field_name, "")
        reviewer_evidence = (
            f"evidence-for-{field_name}"
            if reviewer_value and include_evidence and field_name not in missing_evidence_fields
            else ""
        )
        lines.append(
            ",".join(
                [
                    task["task_id"],
                    task["record_ref"],
                    field_name,
                    task.get("suggested_value") or "",
                    ";".join(task.get("available_context_keys") or []),
                    ";".join(
                        f"{key}={value}"
                        for key, value in sorted((task.get("available_context_values") or {}).items())
                    ),
                    ";".join(task.get("filled_patch_fields") or []),
                    str(task.get("review_required", True)).lower(),
                    reviewer_value,
                    task.get("suggested_value") or "",
                    (
                        ";".join(
                            f"{key}={value}"
                            for key, value in sorted((task.get("available_context_values") or {}).items())
                        )
                        if include_evidence_hint
                        else ""
                    ),
                    reviewer_evidence,
                    "",
                ]
            )
        )
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")


